window.POLICIES = [{"id":"small-business-income-tax","title":"关于进一步支持小微企业和个体工商户发展有关税费政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第12号","publishedAt":"2023-08-02","effectiveAt":"2023-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠","企业所得税","个人所得税"],"audience":["小型微利企业","个体工商户"],"hot":98,"summary":"小型微利企业年应纳税所得额不超过300万元的部分，实际税负降到5%；个体工商户年应纳税所得额不超过200万元的部分，减半征收个人所得税。执行到2027年底。","sections":[{"no":"一","title":"小型微利企业所得税","text":"对小型微利企业年应纳税所得额不超过300万元的部分，减按25%计入应纳税所得额，按20%的税率缴纳企业所得税。"},{"no":"二","title":"个体工商户个人所得税","text":"对个体工商户年应纳税所得额不超过200万元的部分，减半征收个人所得税。个体工商户在享受现行其他个人所得税优惠政策的基础上，可叠加享受本条优惠政策。"},{"no":"三","title":"执行期限","text":"上述政策执行至2027年12月31日。"}],"interpretations":[{"sectionNo":"一","headline":"利润300万以内，企业所得税实际只交5%","who":"同时满足三个条件：从业人数不超过300人、资产总额不超过5000万元、年应纳税所得额不超过300万元，且从事国家非限制和禁止行业。注意「应纳税所得额」是税法口径的利润，不是账面利润，需要按税法调整。","materials":["季度预缴时的《企业所得税月（季）度预缴纳税申报表》","年度汇算清缴的《企业所得税年度纳税申报表》","从业人数、资产总额的核算说明（系统内填报，一般无需额外报送）"],"window":"按季预缴、年度汇算清缴（次年5月31日前），符合条件自动享受，无需事前备案。","where":"电子税务局在线申报，或主管税务机关办税服务厅。","tip":"超过300万元的部分不再享受该优惠，卡在临界点附近时，可结合研发费用加计扣除、设备一次性扣除做合规的税前安排。"},{"sectionNo":"二","headline":"个体户200万以内所得，个税直接减半","who":"查账征收与核定征收的个体工商户均可享受；按「经营所得」计税，且年应纳税所得额不超过200万元。","materials":["《个人所得税经营所得纳税申报表》","减免税事项报告表（电子税务局填报时自动带出）"],"window":"月度或季度预缴时即可享受，年度终了后3个月内汇算清缴。","where":"电子税务局「经营所得申报」，或办税服务厅。","tip":"减半是在算出应纳税额后再减免，可与残疾人、退役士兵等其他优惠叠加。"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202308/content_6896379.htm","sourceNote":"请在税务总局官网「政策文件」栏按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）","verified":true,"isSample":false,"hunan":false},{"id":"vat-small-scale","title":"关于增值税小规模纳税人减免增值税政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第19号","publishedAt":"2023-08-02","effectiveAt":"2023-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠","增值税","小规模纳税人"],"audience":["小规模纳税人","个体工商户","小微企业"],"hot":96,"summary":"小规模纳税人月销售额10万元（季度30万元）以下免征增值税；适用3%征收率的收入减按1%征收。执行到2027年底。","sections":[{"no":"一","title":"起征点免税","text":"对月销售额10万元以下（含本数）的增值税小规模纳税人，免征增值税。"},{"no":"二","title":"征收率下调","text":"增值税小规模纳税人适用3%征收率的应税销售收入，减按1%征收率征收增值税；适用3%预征率的预缴增值税项目，减按1%预征率预缴增值税。"},{"no":"三","title":"执行期限","text":"上述政策执行至2027年12月31日。"}],"interpretations":[{"sectionNo":"一","headline":"一个月卖不到10万，增值税一分不用交","who":"登记为小规模纳税人的企业和个体户；按季申报的，季度销售额30万元以下同样免征。销售额是「不含税销售额」，开具增值税专用发票的部分不能免税。","materials":["增值税及附加税费申报表（小规模纳税人适用）","开票数据由系统自动归集，无需另行报送"],"window":"按月或按季申报期内随申报享受；一旦某月超限，当月全部销售额照章征税（不是只对超出部分征税）。","where":"电子税务局申报即享受，无需备案。","tip":"客户要求开专票时，这部分收入要正常缴税；建议把专票需求和免税额度分开测算，避免整月失去免税资格。"},{"sectionNo":"二","headline":"开3%的票，实际只按1%交","who":"适用3%征收率的小规模纳税人（多数现代服务、部分货物销售），且未选择放弃减免。","materials":["增值税申报表附列资料","发票开具记录"],"window":"申报时按1%计算，无需额外申请。","where":"电子税务局。","tip":"开具发票时税率栏选1%；若已按3%开具，需要作废重开或按3%申报，不能事后退差额。"}],"sourceUrl":"https://www.gov.cn/zhengce/zhengceku/202308/content_6896287.htm","sourceNote":"请在税务总局官网按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）","verified":true,"isSample":false,"hunan":false},{"id":"rd-super-deduction","title":"关于进一步完善研发费用税前加计扣除政策的公告","level":"national","region":"全国","issuer":"财政部 税务总局","documentNo":"财政部 税务总局公告2023年第7号","publishedAt":"2023-03-26","effectiveAt":"2023-01-01","status":"active","tags":["税收优惠","研发创新","科技型企业"],"audience":["科技型企业","制造业企业","有研发投入的企业"],"hot":88,"summary":"企业实际发生的研发费用，未形成无形资产的按100%加计扣除；形成无形资产的按成本的200%在税前摊销。所有符合条件行业均可享受。","sections":[{"no":"一","title":"加计扣除比例","text":"企业开展研发活动中实际发生的研发费用，未形成无形资产计入当期损益的，在按规定据实扣除的基础上，自2023年1月1日起，再按照实际发生额的100%在税前加计扣除；形成无形资产的，自2023年1月1日起，按照无形资产成本的200%在税前摊销。"},{"no":"二","title":"研发活动范围","text":"研发活动指企业为获得科学与技术新知识，创造性运用科学技术新知识，或实质性改进技术、产品（服务）、工艺而持续进行的具有明确目标的系统性活动。"}],"interpretations":[{"sectionNo":"一","headline":"花100万研发，税前能扣200万","who":"会计核算健全、实行查账征收并能够准确归集研发费用的居民企业。烟草制造、住宿餐饮、批发零售、房地产、租赁商务服务、娱乐业等负面清单行业除外。","materials":["研发项目立项决议与项目计划书","研发费用辅助账（按项目设置）","研发人员工时分配与工资表","委托研发、合作研发的合同及登记证明","《研发费用加计扣除优惠明细表》"],"window":"7月预缴时可选择就上半年研发费用享受，10月预缴时可就前三季度享受，年度汇算清缴（次年5月31日前）据实享受。","where":"电子税务局「企业所得税申报—加计扣除」模块。","tip":"辅助账是税务核查重点：立项、工时、领料三者必须能对上；科技型中小企业还需先完成入库登记才能叠加其他优惠。"},{"sectionNo":"二","headline":"什么才算研发，别把日常改版当研发","who":"需要区分「研发」与「常规性升级」：产品迭代、简单外观改动、市场调研、售后维护都不属于研发活动。","materials":["研发项目技术说明（要解决的技术问题、创新点、技术路线）","阶段性成果或测试报告"],"window":"项目立项时即应留痕，事后补材料在核查中风险较高。","where":"企业自行判定并留存备查，争议时可申请科技部门鉴定。","tip":"建议每个项目准备一页「技术问题—方案—结果」说明，这是核查时最容易被问到的一页纸。"}],"sourceUrl":"https://zc.gjzwfw.gov.cn/art/2023/3/29/art_14_63825.html","sourceNote":"请在税务总局官网按文号检索原文核对；2026-11-08 链接替换为官方原文页（标题与文号已核对）","verified":true,"isSample":false,"hunan":false},{"id":"startup-guarantee-loan","title":"关于进一步加大创业担保贷款贴息支持力度的通知","level":"national","region":"全国","issuer":"财政部 人力资源社会保障部 中国人民银行","documentNo":"财金〔2018〕22号","publishedAt":"2018-03-27","effectiveAt":"2018-03-27","status":"active","tags":["融资支持","贷款贴息","创业担保"],"audience":["创业者","小微企业","返乡创业人员","高校毕业生"],"hot":84,"summary":"符合条件的创业者个人可申请创业担保贷款并由财政贴息，小微企业也可申请；具体额度、期限与贴息比例由各地在中央政策框架内确定。","sections":[{"no":"一","title":"支持对象","text":"创业担保贷款支持对象包括城镇登记失业人员、就业困难人员、复员转业退役军人、刑满释放人员、高校毕业生、化解过剩产能企业职工和失业人员、返乡创业农民工、网络商户、建档立卡贫困人口等，以及符合条件的小微企业。"},{"no":"二","title":"贴息机制","text":"对符合条件的创业担保贷款，由财政按规定给予贴息；对贫困地区符合条件的个人创业担保贷款，可按规定免除反担保要求。"}],"interpretations":[{"sectionNo":"一","headline":"你不是「普通借款人」，很多身份都能申请","who":"个人：属于城镇登记失业人员、高校毕业生（含在校生及毕业5年内）、返乡创业农民工、退役军人、网络商户等身份之一，且有具体经营项目。小微企业：当年新招用符合条件人员达到在职职工一定比例。","materials":["申请书与创业项目说明","身份证明及对应身份材料（毕业证、退役证、失业登记证明等）","营业执照或经营场所证明","征信授权与还款能力证明","反担保材料（各地要求不同）"],"window":"全年可申请，具体受理节奏以当地人社部门与合作银行公布为准；贷款期限一般不超过3年。","where":"创业地人社部门（就业服务中心）或经办银行网点，多地已支持线上申请。","tip":"最高额度与贴息比例各地差异大（多数地区个人上限在20万—30万区间），务必以你所在城市当年文件为准，别照搬外地标准。"},{"sectionNo":"二","headline":"利息由政府补一部分，贫困地区还能免反担保","who":"获得创业担保贷款资格并经银行放款的个人或小微企业；贴息比例按当地规定执行，贫困地区可免除反担保。","materials":["贷款合同","银行放款凭证","贴息申请表"],"window":"贴息按年度结算，通常在还款后由经办机构统一申报。","where":"经办银行代为申报，或由人社部门统一办理。","tip":"申请贷款前先确认「是否在贴息名录内」，否则拿到的是商业贷款，利息差可能相差数万元。"}],"sourceUrl":"https://www.mof.gov.cn/","sourceNote":"财政部官网按文号检索；地方实施口径请查当地人社局文件；2026-11-08 核对：现有链接指向部委首页，原文链接待补","verified":false,"isSample":false,"hunan":false},{"id":"sme-gradient-cultivation","title":"优质中小企业梯度培育管理暂行办法","level":"national","region":"全国","issuer":"工业和信息化部","documentNo":"工信部企业〔2022〕63号","publishedAt":"2022-06-01","effectiveAt":"2022-08-01","status":"active","tags":["认定资质","专精特新","创新型中小企业"],"audience":["科技型中小企业","制造业中小企业"],"hot":76,"summary":"建立「创新型中小企业—专精特新中小企业—专精特新小巨人企业」三级梯度培育体系，各级有明确评价或认定标准，认定后可对接相应扶持。","sections":[{"no":"一","title":"三级梯度","text":"优质中小企业由创新型中小企业、专精特新中小企业和专精特新「小巨人」企业三个层次组成，实行梯度培育、动态管理。"},{"no":"二","title":"评价与认定","text":"创新型中小企业由省级中小企业主管部门组织评价；专精特新中小企业由省级主管部门认定；专精特新「小巨人」企业由工业和信息化部认定。"}],"interpretations":[{"sectionNo":"一","headline":"先当「创新型」，再冲「专精特新」","who":"在中华人民共和国境内工商注册登记、具有独立法人资格、符合中小企业划型标准的企业；重点是细分市场有特色、研发投入稳定的制造业与生产性服务业企业。","materials":["企业基本情况表（注册时间、人员、营收、研发投入）","知识产权清单（专利、软著）","研发费用归集表","主营产品在细分市场的说明材料"],"window":"多数省份每年集中受理一次，通常在上半年；创新型中小企业评价滚动开展。","where":"省级中小企业主管部门线上系统（多为「中小企业公共服务平台」）。","tip":"从「创新型」起步门槛最低，多数地区对研发费用占比、知识产权数量有硬指标，提前一年准备最稳。"},{"sectionNo":"二","headline":"认定层级不同，主管理部门也不同","who":"已具备一定营收规模、细分市场占有率和研发能力的企业；小巨人一般要求主导产品在细分领域有较高市场份额。","materials":["申报书","近三年审计报告","研发机构与人员证明","质量体系与标准参与证明"],"window":"按主管部门年度通知申报，错过需等下一批。","where":"省级主管部门推荐，工信部组织认定。","tip":"认定不是终身制，有效期届满需复核；用认定结果申报地方奖励时，注意奖励与复核周期的衔接。"}],"sourceUrl":"https://www.miit.gov.cn/","sourceNote":"工信部官网按文号检索；各省评价细则以省级主管部门文件为准；2026-11-08 核对：现有链接指向部委首页，原文链接待补；2026-11-08 发现 2026 年新版《优质中小企业梯度培育管理办法》，本条（2022 暂行办法）疑似已被替代，待确认","verified":false,"isSample":false,"hunan":false},{"id":"sample-one-time-startup-subsidy","title":"〔示例〕一次性创业补贴实施办法","level":"city","region":"示例地区","issuer":"示例市人力资源和社会保障局","documentNo":"示例人社〔2025〕1号","publishedAt":"2025-03-01","effectiveAt":"2025-03-01","expiresAt":"2026-12-31","status":"expiring","tags":["创业补贴","补贴申领"],"audience":["首次创业者","高校毕业生","返乡创业人员"],"hot":70,"summary":"这是用于演示地区级政策的示例数据：对首次创办小微企业或个体户、正常经营满一定期限的创业者，给予一次性创业补贴。真实标准请以当地文件为准。","sections":[{"no":"一","title":"补贴对象","text":"（示例条款）首次在本市创办小微企业或个体工商户，正常经营并依法缴纳社会保险费满6个月的创业者，可申请一次性创业补贴。"},{"no":"二","title":"补贴标准与申领","text":"（示例条款）补贴标准为每人一次性5000元至10000元，同一创业者只能享受一次；申请人应在经营满6个月后的12个月内提出申请。"}],"interpretations":[{"sectionNo":"一","headline":"首创办企业，经营满半年就能领","who":"本市户籍或在本市创业的首次创业者；创办主体需为小微企业或个体工商户，且本人依法缴纳社保满6个月。已享受过同类补贴的不能重复申请。","materials":["补贴申请表","营业执照副本","社保缴费记录","本人身份证与银行账户","经营场所证明"],"window":"经营满6个月后12个月内申请，逾期视为放弃。","where":"创业地街道（乡镇）便民服务中心或人社局线上申报入口。","tip":"示例数据，仅用于演示申请流程；各地金额与条件差异很大，务必核对本地当年文件。"},{"sectionNo":"二","headline":"5000到10000元，一生只能领一次","who":"符合对象条件且未重复享受的创业者。","materials":["同上一节材料","补贴发放确认单"],"window":"按季度集中审核发放。","where":"人社部门审核后拨付至本人账户。","tip":"部分地区要求「正常经营」需有实际流水，空壳注册通常无法通过审核。"}],"sourceUrl":"https://www.mohrss.gov.cn/","sourceNote":"本条为演示用示例数据，非真实政策，请勿据此申领","verified":false,"isSample":true,"hunan":false},{"id":"changsha-one-time-startup-subsidy-2026","title":"关于开展长沙市一次性创业补贴（含大学生一次性创业补贴）申报工作的通知","level":"city","region":"长沙市","issuer":"长沙市人力资源和社会保障局","documentNo":"","publishedAt":"2026-05-25","effectiveAt":"","expiresAt":"","status":"active","tags":["创业补贴"],"audience":["初创企业","高校毕业生"],"summary":"长沙初创企业正常经营1年以上并吸纳就业，按吸纳人数补5000至30000元，大学生同项补1万至3万元。","sections":[{"no":"一","title":"一次性创业补贴申报","text":"（一）申报条件\n\n申报长沙市一次性创业补贴，须同时具备以下条件：\n\n1.在湖南湘江新区、芙蓉区、天心区、开福区、雨花区、望城区范围内登记注册的初创企业；登记注册时间在5年以内（自注册之日至申报之日不超过5年）；\n\n2.正常经营1年以上，吸纳1名及以上劳动者就业，缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态；\n\n3.符合长沙市产业发展方向；\n\n4.在信用中国无行政处罚、严重失信等记录；\n\n5.申报人为企业法定代表人，属于就业困难人员或返乡入乡农民工，持股比例不低于企业总股份的30%；\n\n申报人非企业第一任法定代表人的，不纳入补贴范围。\n\n（二）所需资料\n\n1.《长沙市一次性创业补贴申请表》（申报系统填写资料后自动生成）；\n\n2.营业执照、申报人身份证；企业股权分配证明资料；\n\n3.申报人属于返乡入乡农民工的需提供长沙市行政区域范围内户籍地乡镇（街道）人力资源社会保障服务站或村（社区）出具的返乡创业佐证资料；属于就业困难人员的无需提供佐证资料，由湖南湘江新区民政和社会保障局、各区人力资源和社会保障局在信息系统中核实。\n\n（三）补贴标准\n\n根据吸纳城乡劳动者就业人数申请5000至30000元不等的一次性创业补贴。吸纳城乡劳动者就业人数取申报前3个月缴纳城镇职工社会保险人数的平均值。吸纳1人的按5000元标准给予一次性创业补贴；吸纳1人以上的每增加1人给予1000元补贴，最高不超过30000元。已经享受过市财政同一项目补贴的，不能重复享受。"},{"no":"二","title":"大学生一次性创业补贴","text":"（一）申报条件\n\n申报大学生一次性创业补贴，须同时具备以下条件：\n\n1.在湖南湘江新区、芙蓉区、天心区、开福区、雨花区、望城区范围内登记注册的初创企业；登记注册时间在5年以内（自注册之日至申报之日不超过5年）；\n\n2.正常经营1年以上，吸纳1名及以上劳动者就业，缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态；\n\n3.符合长沙市产业发展方向；\n\n4.在信用中国无行政处罚、严重失信等记录；\n\n5.申报人为企业法定代表人，属于离校2年内高校毕业生，且持股比例不低于企业总股份的30%；\n\n申报人非企业第一任法定代表人的，不纳入补贴范围。\n\n（二）所需资料\n\n1.《长沙市大学生一次性创业补贴申请表》（申报系统填写资料后自动生成）；\n\n2.营业执照、申报人身份证、企业股权分配证明资料；\n\n3.申报人属于离校2年内高校毕业生的相关证明材料（毕业证或学信网学籍证明）。\n\n（三）补贴标准\n\n根据吸纳城乡劳动者就业人数申请10000至30000元不等的一次性创业补贴。吸纳城乡劳动者就业人数取申报前3个月缴纳城镇职工社会保险人数的平均值。吸纳1人的按10000元标准给予一次性创业补贴；吸纳1人以上的每增加1人给予1000元补贴，最高不超过30000元。已经享受过市财政同一项目补贴的，不能重复享受。"},{"no":"三","title":"申报流程","text":"（一）线上申报。长沙市一次性创业补贴、大学生一次性创业补贴进行线上申报。申报人登录湖南省政务服务网点击“高效办成一件事”，选择“大学生就业创业落户‘一件事’——创业补贴申领”（离校2年内高校毕业生）或“个人创业‘一件事’——创业补贴申领”（返乡入乡农民工、就业困难人员），按要求填写相关信息，并上传相关资料。\n\n（二）审核报送。湖南湘江新区民政和社会保障局、各区人力资源和社会保障局负责辖区内申报资料的审核，并做好实地考察工作，将符合条件的申报人名单报送至市人力资源社会保障局。\n\n（三）市级复审。市人力资源社会保障局对申报人资料进行复审，核定申报人是否符合申报条件，对符合条件的，核定其吸纳就业人数和应补贴金额，形成拟补贴名单。\n\n（四）网上公示。每个季度对该季度拟补贴的申报人名单在市人力资源社会保障局官网上进行公示，公示期为5个工作日。\n\n（五）资金拨付。受补贴名单公示完毕后，由湘江新区民政和社会保障局、各区县（市）人力资源和社会保障局按照相关规定将扶持资金拨付至申报人账户。"},{"no":"四","title":"补贴终止","text":"出现以下情形之一的，终止享受补贴：\n\n（一）申报审核期间，初创企业实体处于停业状态，或已注销、吊销营业执照的。\n\n（二）经核实有其他不符合补贴发放政策相关条件的。"},{"no":"五","title":"工作要求","text":"（一）加强宣传推荐。湖南湘江新区民政和社会保障局、各区人力资源和社会保障局要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向，代表先进生产力、生产方式的创新创业带动就业的先进典型。\n\n（二）严肃工作纪律。任何服务于补贴申报的公职人员不得假公济私、以权谋私、索拿卡要、刁难企业和个人，收受企业和个人财物。申报人应对申报资料的真实性负责。对在申报过程中弄虚作假的申报人，一经核实，取消申报资格，情节严重的纳入诚信黑名单，不再享受长沙市政府各类财政支持。"},{"no":"六","title":"相关解释","text":"（一）“初创企业”类型包括企业、个体工商户和农民专业合作社等。\n\n（二）普通高校是指国家教育行政部门批准或备案的实施高等学历教育为主的高等学校，包括全日制大学、独立学院、职业技术学院、高等专科学校。非全日制研究生享受与全日制研究生同等对待。\n\n（三）各县（市）根据本通知精神，可参照制定相关办法。\n\n（四）其他未尽事宜，由市人力资源社会保障局负责解释。"}],"interpretations":[],"sourceUrl":"http://rsj.changsha.gov.cn/xxgk/fdzdgk/zfcg_131322/cggg_131324/202605/t20260525_12390713.html","sourceNote":"2026-10-31 取自长沙市人力资源和社会保障局官网采购公告栏原文页；原文未标注文号，documentNo 留空；适用范围为湘江新区及芙蓉、天心、开福、雨花、望城区。；2026-11-08 核对：页面发布日期 2026-05-25","verified":true,"isSample":false,"hunan":true},{"id":"hunan-2026-business-environment-measures","title":"湖南省人民政府办公厅关于印发《湖南省以问题为靶心优化营商环境若干举措》的通知","level":"provincial","region":"湖南省","issuer":"湖南省人民政府办公厅","documentNo":"湘政办发〔2026〕30号","publishedAt":"2026-06-04","effectiveAt":"","expiresAt":"2031-06-04","status":"active","tags":["营商环境","融资支持"],"audience":["民营企业","中小企业","个体工商户"],"summary":"湖南出台23条优化营商环境举措：政策找企与免申即享、限时清零拖欠民企账款、工商业电价降3—5分/度、入企检查一律扫码、涉企诉求统一归口受理。自印发之日起施行，有效期5年。","sections":[{"no":"一","title":"着力解决惠企政策获得感不强的问题","text":"一、着力解决惠企政策获得感不强的问题\n\n（一）推行“政策找企”主动服务。完善“政企通”涉企政策集中发布系统，分类归集、及时更新国家、省、市惠企政策，同步公开申报条件、审核标准、流程时限等要素，实时推送“湘易办”。加强政策拆解，完善政策标签体系，统一经营主体与惠企政策标注规则，开发“政策计算器”，集中归集涉企数据，为经营主体“精准画像”，点对点推送适配政策。通过“政企通”开展全链条产业政策梳理，依托“湘易办”上线“产业链政策地图”，实现产业政策查询“一站检索”。（责任单位：省工业和信息化厅、省数据局等省直相关单位，各市州人民政府。原则上第一位为牵头单位，以下均需各市州人民政府落实，不再列出）\n\n（二）打造惠企政策兑现“快车道”。出台惠企政策兑现平台管理办法，在省政务服务网建设“惠企政策直达快享专区”，实现申报入口“一键直达”。拓展“免申即享”“直达快享”政策覆盖面，提高兑现实效，可通过数据比对确认条件的兑现事项、普惠性奖补等，实现“无需申报、资金直达”。强化全流程穿透式监管，建立政策兑现超时预警督办机制。推行政策兑现“容缺受理+后置补正”模式，对非核心材料缺失的申报事项“先受理、后补正、快兑付”。（责任单位：省数据局、省财政厅、惠企政策制定单位）\n\n（三）健全惠企政策效能评估。建立惠企政策制定、宣讲、实施、反馈、优化闭环机制，每年开展一次惠企政策效能评估，持续清理、落实、新增一批涉企发展政策。探索运用人工智能大模型辅助开展政策效能分析。（责任单位：省发展改革委、省工商联、省司法厅、惠企政策制定单位）"},{"no":"二","title":"着力解决拖欠民企账款的问题","text":"二、着力解决拖欠民企账款的问题\n\n（四）限时清零存量拖欠。紧盯交通运输、农业、水利、住房城乡建设、教育、卫生健康等重点行业及国有平台公司拖欠民营企业账款问题，建立清偿台账。省级挂牌督办大额拖欠，市县分级包干，限期完成存量拖欠清零。用好地方政府专项债券、盘活存量资产等手段，鼓励通过债务置换、资产证券化等方式筹措清偿资金。将清欠成效纳入地方政府领导班子和领导干部综合考评、国有企业负责人经营业绩考核。（责任单位：省工业和信息化厅、省财政厅、省交通运输厅、省农业农村厅、省水利厅、省住房城乡建设厅、省教育厅、省卫生健康委、省委金融办、省委组织部、省国资委、各行业主管部门）\n\n（五）源头严防新增拖欠。严格执行“无预算不支出、无资金来源不开工”规定，按照工程进度及时足额拨付政府投资项目建设资金。建立账款支付临期、逾期、政务失信三级预警督办机制。推动行业协会等定期披露企业账期信息。对发现的存量台账以外的拖欠，甄别后按漏报瞒报或者新增拖欠处理，如属新增地方政府隐性债务，按有关规定严肃追责问责，由各地自行统筹资金资源限时化解。（责任单位：省财政厅、省工业和信息化厅、各行业主管部门）\n\n（六）加强诚信履约监管。依托现有系统建设“政府合同库”，规范合同线上备案，开放经营主体上传渠道，全量归集政府投资、招商引资、政府采购、工程建设、产业扶持等各类政府合同。聚焦政府负有给付义务的合同，建立全生命周期智慧监管制度。完善政府合同履约投诉管理运行机制。将经核实的机关、事业单位、国有企业违约失信情况纳入政务失信记录，结合审计项目加强监督。对失信主体，依规限制财政资金和扶持政策申请、项目申报、评先评优。（责任单位：省发展改革委、省财政厅、省商务厅、省住房城乡建设厅、省工业和信息化厅、省审计厅、省委组织部、省国资委、各行业主管部门）"},{"no":"三","title":"着力解决资源要素使用成本较高的问题","text":"三、着力解决资源要素使用成本较高的问题\n\n（七）降低企业用能成本。进一步优化电力资源配置，完善水电调度，争取省外优质低价电源，通过改革的手段降低工商业用户电价3—5分钱每千瓦时，每年降低全省企业用能成本30—50亿元。推动省内高速公路充电服务费下降0.1元每千瓦时，每年减少用户支出2000万元。从严核定天然气管道运输价格和配气价格，挖掘空间为用户降价减负。加快推行园区“转改直”，清理转供电环节不合理加价。实行园区通信配套设施与园区建设同步规划、施工、交付。（责任单位：省发展改革委、省能源局、国网湖南省电力公司、省交通运输厅、省高速集团、省市场监管局、省住房城乡建设厅、省通信管理局）\n\n（八）优化土地资源供给。全面实施工业项目“标准地”供应，分地区、分类采取差异化地价支持政策，切实降低企业用地成本。工业用地提高土地利用率和增加容积率的，不再增收土地价款。支持产业链关联企业联合拿地、联合建楼，简化办理工业物业产权分割及转让登记流程。按建筑面积超50%的建筑功能确定土地主导用途，制定土地混合开发和空间复合利用正面清单和管控要求，符合正面清单即视为符合详细规划。因政府原因或自然灾害等不可抗力导致开竣工违约的，可由市县政府集体研究后免除企业违约责任，本文件实施前已实际竣工验收的项目，可不再追究企业开竣工违约责任。（责任单位：省自然资源厅等省直相关部门）\n\n（九）提升金融服务质效。引导金融机构完善奖励政策和尽职免责、容错纠错制度，增加民营经济相关业务绩效考核权重，逐步提升民营经济贷款占比。加强“湘信贷”平台推广应用，订单平均受理时间压减至3个工作日以内，2026年、2027年撮合授信分别达1200亿元、1500亿元以上。完善小微企业融资协调工作机制，推广随借随还、无还本续贷等便利化产品，引导金融机构不盲目停贷、压贷、抽贷、断贷。建立省市县三级政府投资基金统筹管理机制，优化投资决策与投放，形成资金合力。健全政府性融资担保体系，加大保费补贴力度，引导降低担保费率和反担保要求。推行重点企业“金融特派员”制度，银行安排专员“一对一”提供融资辅导和服务。（责任单位：省委金融办、人民银行湖南省分行、湖南金融监管局、省发展改革委、省工业和信息化厅、省科技厅、省财政厅、省融资担保集团、各行业主管部门）\n\n（十）推进物流降本增效。加快推进“公转铁”“公转水”，培育铁水联运精品线路，扩大“一单制”“一箱制”试点。优化跨境多式联运顺势监管，支持内外贸同船运输。大力发展智慧物流，搭建全省物流信息平台，推行物流运价公开透明机制，推广共享物流、统仓统配等模式，推出物流类数据增信金融产品。稳妥推进全省高速公路限速优化调整，试点绿通车辆智能核验。推动航空口岸机场货站智慧化改造，优化场地分区及物流路线，符合条件进口货物实现24小时提离，出口货物实现“抵港直装”。（责任单位：省交通运输厅、省发展改革委、省财政厅、省商务厅、省高速集团、广铁集团长沙铁路物流中心、省港航水利集团、省机场管理集团、长沙海关）"},{"no":"四","title":"着力解决中介服务不规范的问题","text":"四、着力解决中介服务不规范的问题\n\n（十一）深化中介服务源头治理。各行业主管部门分领域编制中介服务事项清单，逐项明确中介服务内容、设定依据、服务时限、收费标准等要素，依托省网上中介服务超市集中发布并动态更新，清单之外一律不得强制或者变相要求申请人委托中介机构开展服务。进一步简化中介服务报告编制，突出必要信息和核心数据，按照简约、高效、便利原则，分级分类明确结果要件要求。规范各部门下属事业单位及主管的行业协会发展，结合事业单位改革，对依托行政权力、垄断中介服务的单位，予以撤并整合。（责任单位：省委社会工作部、省数据局、省委编办、省民政厅、各行业主管部门）\n\n（十二）加强中介服务跟踪管理。全面推广省网上中介服务超市，实现供需对接全程透明。开展中介服务质量跟踪评价，推行“好差评”制度，评价结果与入驻资格、业务承接挂钩。加强中介服务机构监管，建立中介机构不良行为记录库，将失信中介机构名单推送至“信用湖南”一体化平台，依法依规实施联合惩戒。严格规范中介服务收费，严查超标准收费、捆绑收费、变相牟利行为。（责任单位：省数据局、省发展改革委、省市场监管局、各行业主管部门）\n\n（十三）开展中介服务专项整治。聚焦投资项目审批、专项评估评价、检验检测、法律服务、信贷服务、招工服务等重点领域，分类开展中介服务专项整治，纳入群众身边不正之风和腐败问题集中整治重点。严格落实禁止在职、退休公职人员在中介机构兼职取酬的纪律规定，针对性开展审计监督。建立中介违规行为举报绿色通道，对查实的违规中介，清出中介超市，依法依规追责问责。（责任单位：省纪委监委、省委组织部、省委社会工作部、省民政厅、省审计厅、省数据局、各行业主管部门）"},{"no":"五","title":"着力解决涉企执法检查突出问题","text":"五、着力解决涉企执法检查突出问题\n\n（十四）全面深化“扫码入企”。深化“扫码入企、联码督查”，实现亮码入企、全程留痕、闭环监督。公安、税务等部门全面接入扫码入企系统。除法律法规另有规定外，所有入企行政检查、调研、服务等行为一律扫码登记，被检查对象可扫码核验执法资质、检查权限，有异议可一键反馈。建立企业“拒绝未扫码检查”保护机制，严肃查处未按规定扫码、以规避扫码为由要求企业前往相关单位现场办理业务等行为。（责任单位：省司法厅、省公安厅、省税务局、各行政执法部门）\n\n（十五）规范行政执法自由裁量权。依托全省行政执法和行政执法监督一体化平台，建立全省统一的行政处罚裁量权基准数据库、涉企执法案例库，通过案例公开、大数据比较、社会监督，压缩自由裁量空间。（责任单位：省司法厅、各行政执法部门）\n\n（十六）实施分级分类精准监管。健全“信用+风险”监管体系，建立“无感监测”对象清单和“无事不扰”事项清单，对风险低、信用好的企业优先采用非现场检查。动态更新轻微违法行为依法免罚、轻罚事项清单，扩大柔性执法适用范围。对违法行为轻微并及时改正、没有造成危害后果的，推广行政执法“观察期”制度。（责任单位：省司法厅、省市场监管局、省发展改革委、各行政执法部门）"},{"no":"六","title":"着力解决妨碍民营企业公平参与市场竞争的问题","text":"六、着力解决妨碍民营企业公平参与市场竞争的问题\n\n（十七）维护公平竞争秩序。全面开展市场准入效能评估，保障各类经营主体平等进入。定期发布基础设施、公共服务等领域适合民间资本参与的项目，不得设置隐性门槛。持续优化“机器管招投标”，重点规范复评管理、投诉处理等行政监督环节，建立全链条、穿透式数智化监管体系。深化招标投标领域突出问题整治，重点打击、公开曝光围标串标、买标卖标、转包、违法分包等损害市场秩序的违法违规行为。鼓励招标人对信用较好的企业免除投标担保。深化政府采购领域违法违规行为专项整治。（责任单位：省发展改革委、省市场监管局、省财政厅、省公共资源交易中心、各行业主管部门）\n\n（十八）推动市场高效畅通。完善企业跨区域迁移机制，实现只向迁入地申请一次。优化企业注销流程，推动长期未经营或停止经营企业和个体工商户市场退出。严肃查处对企业跨区域经营、迁移或者注销设置障碍等行为。推动行业部门、国有企业主动开放应用场景，建立面向民营企业常态化开放机制。拓展开放平台，支持有条件的市州、园区按照规定程序在重点国别地区设立联络代表处。（责任单位：省市场监管局、省发展改革委、省数据局、省税务局、省人力资源社会保障厅、省医保局、省直住房资金管理中心、省商务厅、省国资委、各行业主管部门）\n\n（十九）深化重点领域整治。建立恶意举报异常名录库，依法打击恶意索赔、敲诈勒索、缠诉闹访等违法行为。重拳整治平台经济乱象，重点规制利用数据和算法、技术、资本优势、平台规则实施的算法共谋、大数据杀熟、“二选一”限定交易、利用规则封禁屏蔽、附加不合理交易条件等垄断行为。严厉打击平台经营者利用市场支配地位向平台内经营者收取不公平高额费用、低于成本销售排挤竞争对手等行为。（责任单位：省市场监管局、省委社会工作部、省高级人民法院、省人民检察院、省发展改革委、省公安厅、各行业主管部门）"},{"no":"七","title":"着力解决民营企业“投诉无门”的问题","text":"七、着力解决民营企业“投诉无门”的问题\n\n（二十）完善诉求办理机制。发挥省民营经济发展局（省营商环境建设局）统一归口受理涉企诉求职能，迭代升级省营商环境诉求办理平台，优化诉求办理全链条闭环管理和服务体系。对深层次营商环境疑难问题，建立“法治会诊”机制，组织政法、公安、检察院、法院、司法行政、纪检、审计部门及行业专家等联合会诊解难。（责任单位：省发展改革委、省委政法委、省公安厅、省人民检察院、省高级人民法院、省司法厅、省纪委监委、省审计厅、各行业主管部门）\n\n（二十一）优化涉企法律服务。完善法律服务对接机制，提供送法进企、法治体检、纠纷调解等服务。加强涉外法律服务机构培育，建强涉外法律服务人才专家库，为出海企业提供公益法律服务。加强一流公证机构和公证领军人才培育，优化公证便企利企服务。依托综治中心加强诉讼、调解、仲裁等对接，提供一站式商事纠纷多元化解服务。（责任单位：省司法厅等省直相关部门）"},{"no":"八","title":"着力解决政商关系“亲清”不分的问题","text":"八、着力解决政商关系“亲清”不分的问题\n\n（二十二）规范政商交往行为。落实省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》，紧扣政商交往突出问题，聚焦企业需求和干部顾虑，推动构建亲而有度、清而有为的亲清新型政商关系。（责任单位：省纪委监委、省委统战部、省工商联）\n\n（二十三）激发干事创业活力。选取不同类型民营企业设立营商环境亲清监测点，动态收集企业意见建议。（责任单位：省委统战部、省工商联）落实“三个区分开来”，区别对待在推动企业发展中出现的失误错误，激励党政机关及公职人员主动担当作为。（责任单位：省纪委监委）对服务企业成效突出的公职人员，在评优评先、选拔任用中予以倾斜。（责任单位：省委组织部）\n\n各级各部门要压实责任，强化协同，细化举措，力戒形式主义，确保落地见效。省发展改革委要加强统筹协调、跟踪督导，提炼推广经验，通报问题不足，重要情况及时向省委、省人民政府请示报告，推动全省营商环境持续优化提升。\n\n本措施自印发之日起施行，有效期5年。"}],"interpretations":[{"sectionNo":"一","headline":"政策主动找企业，符合条件可「免申即享」","who":"在湖南经营的各类经营主体，重点是需要申报惠企政策的企业；通过「政企通」「湘易办」获取政策与申报入口。","materials":[],"window":"持续推进；惠企政策效能评估每年开展一次。","where":"「政企通」涉企政策集中发布系统与「湘易办」平台；省政务服务网「惠企政策直达快享专区」。","tip":"可通过数据比对确认条件的兑现事项、普惠性奖补，目标是「无需申报、资金直达」；非核心材料缺失时可先受理后补正。","evidence":{"headline":["推行“政策找企”主动服务"],"who":["完善“政企通”涉企政策集中发布系统"],"window":["每年开展一次惠企政策效能评估"],"where":["在省政务服务网建设“惠企政策直达快享专区”"],"tip":["实现“无需申报、资金直达”"]}},{"sectionNo":"二","headline":"拖欠民企账款要限期清零，新增拖欠严查","who":"被机关、事业单位、国有企业拖欠账款的民营企业，重点行业包括交通运输、农业、水利、住建、教育、卫生健康及国有平台公司。","materials":["账款凭证与合同（用于主张清偿）"],"window":"限期完成存量拖欠清零；建立台账后按督办节点推进。","where":"省级挂牌督办大额拖欠、市县分级包干；可通过政府合同履约投诉机制反映。","tip":"「无预算不支出、无资金来源不开工」是源头约束；被核实的违约失信会进政务失信记录，并影响其财政资金与项目申报。","evidence":{"headline":["限期完成存量拖欠清零"],"who":["紧盯交通运输、农业、水利、住房城乡建设、教育、卫生健康等重点行业及国有平台公司拖欠民营企业账款问题"],"materials":["建立清偿台账"],"window":["限期完成存量拖欠清零"],"where":["省级挂牌督办大额拖欠，市县分级包干"],"tip":["无预算不支出、无资金来源不开工","将经核实的机关、事业单位、国有企业违约失信情况纳入政务失信记录"]}},{"sectionNo":"三","headline":"工商业电价降3—5分/度，工业用地不再因提容增收地价","who":"省内工商业用电企业、工业用地企业，以及有融资需求的民营企业。","materials":[],"window":"2026—2027年（金融部分明确两个年度的撮合授信目标）。","where":"电价由省发改委、省能源局、国网湖南电力落实；用地找自然资源部门；融资通过「湘信贷」平台。","tip":"工业用地提高利用率、增加容积率不再增收土地价款；因政府原因或不可抗力导致的开竣工违约，可申请免除违约责任。","evidence":{"headline":["降低工商业用户电价3—5分钱每千瓦时","不再增收土地价款"],"who":["引导金融机构完善奖励政策和尽职免责、容错纠错制度"],"window":["2026年、2027年撮合授信分别达"],"where":["加强“湘信贷”平台推广应用"],"tip":["工业用地提高土地利用率和增加容积率的，不再增收土地价款"]}},{"sectionNo":"四","headline":"中介清单之外不得强制委托，收费要透明","who":"需要办理审批、评估、检测、法律、信贷、招工等中介服务的经营主体。","materials":[],"window":"持续推进；专项整治按部署分批开展。","where":"省网上中介服务超市（清单发布、供需对接、「好差评」）。","tip":"清单之外一律不得强制或变相要求委托中介；超标准收费、捆绑收费、变相牟利可举报，失信中介会被联合惩戒。","evidence":{"headline":["清单之外一律不得强制或者变相要求申请人委托中介机构开展服务"],"who":["各行业主管部门分领域编制中介服务事项清单"],"window":["开展中介服务专项整治"],"where":["全面推广省网上中介服务超市"],"tip":["评价结果与入驻资格、业务承接挂钩"]}},{"sectionNo":"五","headline":"入企检查一律扫码，轻微违法多用免罚与观察期","who":"省内接受行政检查、调研、服务的各类企业。","materials":[],"window":"持续执行。","where":"扫码入企系统（公安、税务等部门已接入）；对未扫码检查可一键反馈。","tip":"企业有权拒绝未扫码检查；风险低、信用好的企业优先非现场检查；违法行为轻微并及时改正、没有造成危害后果的，可适用「观察期」。","evidence":{"headline":["所有入企行政检查、调研、服务等行为一律扫码登记"],"who":["建立企业“拒绝未扫码检查”保护机制"],"window":["实现亮码入企、全程留痕、闭环监督"],"where":["公安、税务等部门全面接入扫码入企系统"],"tip":["推广行政执法“观察期”制度","动态更新轻微违法行为依法免罚、轻罚事项清单"]}},{"sectionNo":"六","headline":"招投标不得设隐性门槛，信用好可免投标担保","who":"参与招投标、政府采购、跨区域迁移或注销的各类经营主体，重点是民营企业。","materials":[],"window":"持续执行。","where":"省公共资源交易中心（机器管招投标）、市场监管部门（迁移与注销）。","tip":"企业跨区域迁移只需向迁入地申请一次；招标人可对信用较好的企业免除投标担保；对设置迁移、注销障碍的行为会被查处。","evidence":{"headline":["鼓励招标人对信用较好的企业免除投标担保"],"who":["保障各类经营主体平等进入"],"window":["持续优化“机器管招投标”"],"where":["完善企业跨区域迁移机制，实现只向迁入地申请一次"],"tip":["严肃查处对企业跨区域经营、迁移或者注销设置障碍等行为"]}},{"sectionNo":"七","headline":"涉企诉求统一归口，疑难问题「法治会诊」","who":"在湖南经营、遇到政策兑现或执法争议的民营企业。","materials":[],"window":"持续执行。","where":"省民营经济发展局（省营商环境建设局）统一归口受理；省营商环境诉求办理平台。","tip":"深层次疑难问题可走「法治会诊」，由政法、公安、检察、法院、司法行政、纪检、审计及专家联合会诊。","evidence":{"headline":["统一归口受理涉企诉求职能"],"who":["发挥省民营经济发展局（省营商环境建设局）统一归口受理涉企诉求职能"],"window":["优化诉求办理全链条闭环管理和服务体系"],"where":["迭代升级省营商环境诉求办理平台"],"tip":["建立“法治会诊”机制"]}},{"sectionNo":"八","headline":"政商交往划边界，干事创业有容错","who":"与政府部门打交道的民营企业；以及服务企业的公职人员（激励与容错条款）。","materials":[],"window":"持续执行。","where":"省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》框架下；营商环境亲清监测点。","tip":"落实「三个区分开来」，对推动企业发展中的失误错误区别对待；服务企业成效突出的公职人员在评优评先、选拔任用中倾斜。","evidence":{"headline":["落实省纪委监委《关于规范政商交往推动构建亲清新型政商关系的意见》"],"who":["选取不同类型民营企业设立营商环境亲清监测点"],"window":["推动构建亲而有度、清而有为的亲清新型政商关系"],"where":["紧扣政商交往突出问题，聚焦企业需求和干部顾虑"],"tip":["落实“三个区分开来”"]}}],"sourceUrl":"https://kjt.hunan.gov.cn/kjt/xxgk/zcfg/sbgfxwj/202606/t20260623_34009868.html","sourceNote":"2026-11-02 取自湖南省科技厅政策法规栏目转载原文页（省政府办公厅文件，网页发布 2026-06-04）；原文「本措施自印发之日起施行，有效期5年」，按网页发布日期推算有效期至 2031-06-04；省科技厅为转载栏目，正式文本以省政府门户发布为准。；2026-11-08 核对：页面发布日期 2026-06-04","verified":true,"isSample":false,"hunan":true},{"id":"hunan-2026-wage-guideline","title":"湖南省人力资源和社会保障厅关于发布湖南省2026年企业工资指导线的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅","documentNo":"湘人社规〔2026〕18号","publishedAt":"2026-01-01","effectiveAt":"2026-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["用工成本"],"audience":["各类企业","国有企业","非国有企业"],"summary":"2026年湖南企业工资指导线：上线8%、基准线6%、下线2%，适用于城镇各类企业；效益好的可往上线谈，效益差的可零增长甚至负增长，但不得低于当地最低工资。","sections":[{"no":"一","title":"2026年我省工资指导线","text":"一、2026年我省工资指导线\n\n(一)2026年我省企业工资指导线上线为8%。\n\n(二)2026年我省企业工资指导线基准线为6%。\n\n(三)2026年我省企业工资指导线下线为2%。"},{"no":"二","title":"工资指导线执行范围","text":"二、工资指导线执行范围\n\n2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体。\n\n(一)对经济效益比上年有较大增长幅度或扭亏成效显著的企业,可在工资指导线的基准线和上线区间内协商确定工资增长幅度。\n\n(二)现有工资水平已超过所在地在岗职工平均工资2倍的企业和经济效益比上年增长幅度较小的企业,可在工资指导线的下线与基准线的区间内协商确定工资增长幅度。\n\n(三)当年效益情况与往年持平或略有下降的企业,可结合自身实际参照下线确定工资增长幅度。\n\n(四)对于经营亏损、职工工资发放出现困难的企业,经与工会或职工代表协商,工资可以零增长或负增长,但支付给劳动者的工资不得低于当地最低工资标准。"},{"no":"三","title":"工作要求","text":"三、工作要求\n\n(一)全省各类企业应建立健全工资决定机制和正常增长机制,根据本企业经济效益和劳动生产率的具体情况,协商确定2026年度工资增长比例,合理安排工资增长。着力提高工资水平偏低、工资增长缓慢的普通职工,特别是生产一线及技术工人岗位人员工资水平,使生产一线职工工资增长幅度不低于职工平均工资增长幅度。\n\n1.国有企业(含国有独资、控股和实际控制的企业,下同)应按照国有企业工资决定机制改革的有关规定编制工资总额预算方案,在工资监管部门核准或备案的工资总额预算内,通过与工会开展工资集体协商,合理确定本企业2026年度的职工工资增长幅度和工资水平。\n\n2.非国有企业应依据工资指导线和劳动报酬增长与劳动生产率提高同步的要求,积极主动地与工会或职工协商代表开展工资集体协商,合理确定本企业2026年度的职工工资增长幅度和工资水平。\n\n(二)各级工会组织要加强对企业工会工作的指导,与企业共同协商工资分配制度、分配形式及工资调整幅度,促进企业发展与维护职工权益有机结合,合理提高职工工资水平。\n\n(三)各级人力资源社会保障行政部门要按规定做好国有企业工资总额执行结果的备案工作,加大对工资指导线和《湖南省企业工资集体协商条例》的宣传力度,加强对企业执行情况的监督检查,进一步发挥工资指导线的宏观调控作用,切实提升工资指导线的实施效果和社会影响力。\n\n本通知自2026年1月1日起施行,有效期一年。\n\n政策解读:湖南省2026年企业工资指导线政策解读\n\n湖南省人力资源和社会保障厅\n\n2026年9月28日"}],"interpretations":[{"sectionNo":"一","headline":"2026年工资增长：上限8%、基准6%、下限2%","who":"湖南省内城镇各类企业在与工会协商年度工资增长幅度时参照（原文先给出三条线，再在第二条明确适用范围）。","materials":[],"window":"2026年度工资增长协商时使用。","where":"由企业与工会或职工代表协商确定，报人社部门备案（国企工资总额另有核准/备案程序）。","tip":"三条线是协商区间不是强制标准；效益下滑时按下限甚至零增长谈，别越过当地最低工资。","evidence":{"headline":["企业工资指导线上线为8%","基准线为6%","下线为2%"],"who":["2026年我省企业工资指导线上线为8%"],"window":["2026年我省工资指导线"],"where":["(一)2026年我省企业工资指导线上线为8%"],"tip":["下线为2%"]}},{"sectionNo":"二","headline":"四类企业分别对应不同协商区间","who":"2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体。效益大幅增长或扭亏显著的企业，在基准线与上线之间谈；工资已超过当地在岗职工平均工资2倍、或增幅较小的企业，在下线与基准线之间谈；效益持平或略降的按下线；经营亏损、发薪困难的经协商可零增长或负增长。","materials":[],"window":"2026年度工资集体协商期间。","where":"企业内部工资集体协商；国企另需在工资总额预算内核准备案。","tip":"即使零增长或负增长，支付给劳动者的工资也不得低于当地最低工资标准；超额发放的「超2倍」企业不能往上限方向谈。","evidence":{"headline":["可在工资指导线的基准线和上线区间内协商确定工资增长幅度"],"who":["2026年工资指导线适用于我省城镇各类企业和按照企业经营方式进行经营性活动的各类机构、团体","现有工资水平已超过所在地在岗职工平均工资2倍的企业"],"window":["2026年工资指导线"],"where":["可在工资指导线的下线与基准线的区间内协商确定工资增长幅度"],"tip":["工资可以零增长或负增长,但支付给劳动者的工资不得低于当地最低工资标准"]}},{"sectionNo":"三","headline":"企业要建工资协商机制，一线职工增幅不低于平均","who":"全省各类企业；国有企业需编制工资总额预算方案并在核准或备案的预算内协商，非国有企业依据工资指导线开展集体协商。","materials":["工资总额预算方案（国有企业）","工资集体协商相关材料"],"window":"2026年度；本通知自2026年1月1日起施行，有效期一年。","where":"企业工会/职工代表协商；国有企业报工资监管部门核准或备案；人社部门负责备案与监督检查。","tip":"文件特别要求提高一线及技术工人工资，使生产一线职工工资增长幅度不低于职工平均工资增长幅度。","evidence":{"headline":["协商确定2026年度工资增长比例"],"who":["国有企业(含国有独资、控股和实际控制的企业","非国有企业应依据工资指导线和劳动报酬增长与劳动生产率提高同步的要求"],"materials":["编制工资总额预算方案"],"window":["本通知自2026年1月1日起施行,有效期一年"],"where":["在工资监管部门核准或备案的工资总额预算内"],"tip":["使生产一线职工工资增长幅度不低于职工平均工资增长幅度"]}}],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202610/t20261015_34081933.html","sourceNote":"2026-11-02 取自湖南省人社厅「厅发规范性文件」原文页（湘人社规〔2026〕18号，网页发布 2026-10-15，落款 2026-09-28）；原文「自2026年1月1日起施行，有效期一年」，据此推算有效期至 2026-12-31。；2026-11-08 核对：页面发布日期 2026-10-15","verified":true,"isSample":false,"hunan":true},{"id":"hunan-ai-zhifuwanqi-fund-2026","title":"关于组织开展2026年湖南省“人工智能+”“智赋万企”行动相关项目支持资金申报工作的通知","documentNo":"湘工信财务〔2026〕160号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2026-05-06","effectiveAt":"","expiresAt":"","status":"active","tags":["数字化转型"],"audience":["制造业企业","中小企业"],"summary":"2026年湖南省“人工智能+”“智赋万企”行动相关项目支持资金申报通知，对2025年9月3日实施方案发布以来获评的人工智能创新应用、工业互联网平台、数字化转型促进中心、高标准数字园区、国家级数字化转型标杆等事项给予奖励，网上申报截止2026年6月5日。","sections":[{"no":"一","heading":"支持方向","text":"对2025年9月3日《实施方案》发布以来符合条件事项奖励：（一）人工智能创新应用（优秀算法/数据产品、通过国家网信办备案的大模型、省级人工智能终端产品/大模型/典型应用场景、“人工智能+”十大示范场景）；（二）工业互联网创新发展（国家级“双跨”平台、省工业互联网平台、“5G+工业互联网”标杆工厂、标识解析二级节点）；（三）制造业数字化转型促进中心；（四）高标准数字园区；（五）争创国家级数字化智能化转型标杆、卓越级智能工厂等。"},{"no":"二","heading":"申报条件","text":"申报单位应具独立法人资格、财务管理健全、依法纳税、信用良好；项目符合产业政策、属于前述支持方向，同一申报主体同一年度原则上申报不超过两个项目。违反安全生产环保规定、绩效评价未通过、列入失信名单、存在税务环保安全重大违法违规等情形不得申报。"},{"no":"三","heading":"申报程序","text":"采取网上报送，通过湖南省工信厅项目管理系统提交，相关附件插入项目申请报告一并上传；市州项目由市州工信局牵头联合财政局行文推荐，财政省直管县市参照办理并抄报市州。网上申报及文件报送截止2026年6月5日24:00，系统届时自动关闭。"},{"no":"四","heading":"其他事项","text":"申报单位对材料真实性合法性完整性负责，材料造假或多头重复申报的取消资格、三年内不得申报；申报不收取任何费用，未委托中介代理，举报电话0731-88955596。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202605/t20260506_33970529.html","sourceNote":"湖南省工信厅官网公开正文，2026年度一次性奖励项目申报通知。；2026-11-08 核对：页面发布日期 2026-05-06","verified":true,"isSample":false,"hunan":true},{"id":"hunan-equipment-upgrade-financing-2026","title":"关于组织开展第三批湖南省工业企业设备更新和技术改造项目融资补贴申报工作的通知","documentNo":"","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅、湖南省地方金融管理局、中国人民银行湖南省分行","publishedAt":"2026-09-30","effectiveAt":"","expiresAt":"","status":"active","tags":["融资支持"],"audience":["工业企业","制造业企业"],"summary":"第三批湖南省工业企业设备更新和技术改造项目融资补贴申报通知，对符合条件的工业企业设备更新技改项目给予贷款贴息或融资租赁补贴，项目须在湖南制造强省项目库入库，入库及系统申报截止2026年10月30日。","sections":[{"no":"一","heading":"支持方向","text":"工业企业聚焦制造业智能化、绿色化、融合化发展和本质安全提升，以提升质量、增加品种、塑造品牌、节约成本、降低消耗、增强安全为目的，采取先进适用新设备对现有生产设施、工艺条件和辅助设施进行改造。"},{"no":"二","heading":"申报基本条件","text":"申报单位为具独立法人资格、信用良好的工业企业；项目为在建或2026年3月13日后完工项目，须在湖南制造强省项目库入库，由金融机构提供贷款或融资租赁且于2024年3月7日（含）后签约。贷款贴息项目总投资200万元及以上、贷款期限一年期以上、设备投资占贷款比例不低于50%；融资租赁补贴单笔设备合同金额不低于100万元。同一项目只能享受中央贴息、省级贴息、融资租赁补贴其中一项。"},{"no":"三","heading":"基本程序","text":"企业通过湖南制造强省项目库系统填报入库（截止2026年10月30日24:00），向当地县市区工信部门提出申请，申报材料经省工信厅项目管理系统上传；县市区审查、市州复核推荐，省工信厅会同财政、地方金融、人民银行开展审核和资金测算。项目管理系统关闭时间为2026年10月30日。"},{"no":"四","heading":"申报方式与要求","text":"市州工信部门于2026年10月30日前将正式推荐文件扫描上传系统，并报送纸质推荐文件一式4份至省工信厅投资规划处，项目汇总表电子版发送至邮箱abc2212144@126.com。收件人李嘉璇0731-88955499。"},{"no":"五","heading":"特别提醒","text":"企业对申报真实性负责，材料造假一经查实取消资格、收回补助并依法处理；本次申报不收取任何费用，从未委托中介代理申报，举报电话0731-88955596。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/xxgk_71033/tzgg/202609/t20260930_34075438.html","sourceNote":"湖南省工信厅官网公开正文。该通知未标注独立文号，依据《关于修改〈湖南省工业企业设备更新和技术改造项目融资补贴实施办法〉的通知》（湘财产业〔2025〕5号）组织第三批申报。；2026-11-08 核对：页面发布日期 2026-09-30","verified":true,"isSample":false,"hunan":true},{"id":"hunan-guaranteed-loan-grads-2026","title":"湖南省人力资源和社会保障厅等三部门关于进一步优化创业担保贷款政策全力支持大学生等重点群体创业的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅、中国人民银行湖南省分行","documentNo":"湘人社规〔2026〕9号","publishedAt":"2026-08-14","effectiveAt":"2026-08-14","expiresAt":"2029-08-13","status":"active","tags":["贷款贴息"],"audience":["大学生","小微企业"],"summary":"大学生个人创业担保贷款最高额度提至50万元，按实际利率50%财政贴息，担保费率不高于0.1%并给予补贴。","sections":[{"no":"一","title":"加大政策扶持力度","text":"（一）扩大支持范围。将借款对象中的高校毕业生类别扩大为大学生，包括国内外高校在校学生或毕业5年内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年以内的毕业生。残疾人大学生可放宽至毕业8年内的毕业生。\n\n（二）提高贷款额度。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），将符合条件的大学生个人申请创业担保贷款，最高额度提高至50万元。\n\n（三）提高担保费补贴。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），政府性融资担保机构为大学生个人创业担保贷款提供担保的，收取担保费率不得高于0.1%，省财政按不高于担保金额的1.4%给予补贴。担保费补贴按实际承保期限计算，按年度补贴。"},{"no":"二","title":"完善资金保障与机制","text":"（一）优化财政贴息分担。对于大学生个人创业担保贷款所需贴息资金，由中央和省级财政承担，免除市县配套资金。对创业担保贷款贴息资金分担机制进行优化，分担比例为：脱贫县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担95%、脱贫县承担5%，其他市县所需贴息资金由省财政统筹中央奖补资金和省级配套资金承担75%、其他市县承担25%。各市州、县市区须严格落实本级应承担的贴息配套资金。\n\n（二）预拨贴息资金。参照湖南省财政厅等四部门《关于实施大学生创业贷款财政补助政策的通知》（湘财金〔2025〕43号），建立贴息预拨机制，鼓励各市县财政按照当地创业担保贷款余额，年初预拨当年贴息资金，年底据实结算。贴息资金暂时不足的，由担保基金垫付，待财政贴息资金到位后直接拨付至担保基金。\n\n（三）完善基金风险分担和补充机制。将创业担保贷款纳入现有国家中小微企业贷款风险分担政策范围，各级可根据实际引入政府性担保公司担保。建立健全担保基金持续补充机制，担保基金不足的地区要及时补充。建立呆坏账代偿核销机制，每年开展一次呆坏账清理。\n\n（四）落实创业担保贷款奖补政策。落实我省创业担保贷款有关规定，省财政加大创业担保贷款奖补资金保障力度。省人力资源社会保障厅每年4月底前完成奖补资金分配方案。省财政厅每年5月底前完成奖补资金拨付。各级财政部门每年6月底前将奖补资金拨付至各单位。"},{"no":"三","title":"强化协同与宣传引导","text":"（一）健全协同与激励机制。省人力资源社会保障厅、省财政厅、人民银行湖南省分行要积极推动创业担保贷款政策落实，将发放创业担保贷款纳入年度省重点民生实事项目，将创业担保贷款担保情况纳入政府性融资担保公司绩效评价体系，并将创业担保贷款开展情况作为就业专项资金分配因素及纳入其他评价激励体系，鼓励各类银行积极参与，对服务优质、贡献突出的合作银行，在业务对接、省级财政资金存放等方面予以重点倾斜。各级人力资源社会保障、财政、人民银行等部门要提高政治站位，将落实创业担保贷款政策作为稳就业、促创业的重要举措，明确专人负责，压实工作责任。\n\n（二）优化经办服务。由省财政牵头、省融资担保集团旗下的省中小担保公司建设全线上经办的创业担保贷款数字化管理系统，接入人力资源社会保障、教育、金融监管等部门数据，推动资格审核、担保审批、银行授信、资金结算等流程并联审批。各级人力资源社会保障部门应加快人员资格审核速度，简化纸质资料，优化经办流程，及时推送担保机构。\n\n（三）加大宣传力度。各地要统筹宣传资源，创新宣传方式，充分利用政府网站、新闻发布、政策宣讲等多种渠道，广泛宣传政策内容、申请流程和典型案例，有效提高政策知晓度、覆盖面和获得感。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/hnszf/szf/hnzb_18/2026/202615/szfbmwj_98721_88_1urmmqrurrdbvpccutqhrmsteguugvmdqkupkguegktvspfmfnnccnmvnkhnueqhqrmcrunhkbqgcqshkecsrgbnercksgkvunnqqdpsgvgpukgdtd/202608/t20260814_34045077.html","sourceNote":"2026-10-31 取自湖南省人民政府门户网站政府公报2026年第15期原文页；原文“自公布之日起施行，有效期3年”，公布日为公报发布日2026-08-14，据此推算有效期至2029-08-13。；2026-11-08 核对：页面发布日期 2026-08-14","verified":true,"isSample":false,"hunan":true},{"id":"hunan-one-time-startup-subsidy-2026","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于进一步做好一次性创业补贴工作的通知（试行）","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2026〕11号","publishedAt":"2026-08-05","effectiveAt":"2026-08-01","expiresAt":"2027-07-31","status":"active","tags":["创业补贴"],"audience":["小微企业","个体工商户"],"summary":"首次创办市场主体并正常经营1年以上，高校毕业生/在校学生补不低于1万元，其他重点群体不低于5000元。","sections":[{"no":"一","title":"补贴对象","text":"省内首次创办小微企业或从事个体经济,且所创办企业或个体工商户(以下称市场主体)自工商登记注册之日起正常运营1年以上的离校2年内高校毕业生、院校在校学生、就业困难人员、返乡入乡农民工。已在我省享受过一次性创业补贴的单位或个人,原则上不重复享受,各市州和县市区另有明确规定的除外。"},{"no":"二","title":"补贴标准","text":"就业困难人员、返乡入乡农民工创办的市场主体按最低不少于5000元/家的标准给予补贴。对离校2年内高校毕业生、院校在校学生创办的市场主体按最低不少于10000元/家的标准给予补贴。\n\n补贴所需资金从各地就业专项资金中列支。安排其他非就业专项资金用于发放一次性创业补贴的,可按照相应文件执行。"},{"no":"三","title":"补贴拨付流程","text":"(一)申请。符合条件的市场主体可采用线上或线下的方式申请一次性创业补贴。\n\n1.线上申请。符合条件的市场主体可通过“湘易办”高效办成个人创业“一件事”专区或“湘就业”小程序等线上平台填写并提交人员身份、项目等信息。\n\n2.线下申请。符合条件的市场主体可前往当地人力资源社会保障部门或相关窗口现场办理,并提供《一次性创业补贴申请表》、营业执照、国家企业信用信息公示系统下载的《企业年度报告》、法定代表人身份证明材料(具体要求见《人员身份证明材料》)。\n\n通过省人社一体化业务管理系统业务协同获得的信息,可不再提供相关证明材料。\n\n(二)审核。各级人力资源社会保障部门收到申请后,对申报资料进行审核。申请对象提供材料不实、不准导致审核错误的,后果由申请对象承担。\n\n(三)发放。审核通过后,各级人力资源社会保障、财政部门及时将补贴资金发放至补贴对象。"},{"no":"四","title":"相关要求","text":"(一)各级人力资源社会保障、财政部门要提高政治站位,将落实一次性创业补贴工作作为稳就业、促创业的重要举措。要依托省人社一体化业务管理系统,简化纸质材料、优化经办流程,切实提升经办效率。要加强政策宣传,不断提升政策知晓度。\n\n(二)各级财政、人力资源社会保障部门要严格按照相关规定,做好资金申报、审核和拨付工作,切实保障财政资金安全规范、高效精准使用。要统筹安排好资金,持续加大保障投入力度,确保政策落地见效。\n\n(三)本通知自2026年8月1日起施行,有效期一年。各地已有政策的,可按补贴对象从宽、补贴标准从高原则执行。各市州可结合实际制定细则,具备条件的,可适度放宽补贴对象、提高补贴标准。"}],"interpretations":[],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202608/t20260805_34040428.html","sourceNote":"2026-10-31 取自湖南省人社厅官网厅发规范性文件栏目原文页；有效期一年据原文“自2026年8月1日起施行，有效期一年”推算为2027-07-31。；2026-11-08 核对：页面发布日期 2026-08-05","verified":true,"isSample":false,"hunan":true},{"id":"hunan-sme-development-fund-2025","title":"关于做好2025年湖南省中小企业发展专项资金项目申报工作的通知","documentNo":"湘工信中小发展〔2025〕226号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2025-07-09","effectiveAt":"","expiresAt":"","status":"active","tags":["专项资金"],"audience":["中小企业","专精特新中小企业"],"summary":"2025年湖南省中小企业发展专项资金项目申报通知，以无偿补助方式重点支持专精特新发展类和完善服务体系类两类项目，明确申报基本条件、项目类别、名额分配、申报程序与资料要求，网上申报截止2025年8月7日。","sections":[{"no":"一","heading":"申报基本条件","text":"在湖南省内依法登记注册、一般应具独立法人资格，截至2024年12月31日成立1年以上，财务管理健全、信用良好。已申报2025年度其他省级财政专项资金补助类项目、2024年已获省工信厅管理专项补助支持、被列入“信用湖南”黑名单、材料造假等情形不得申报。"},{"no":"二","heading":"申报项目类别","text":"以无偿补助方式重点支持两类：（一）专精特新发展类项目，支持中小企业数字化网络化智能化建设、购置设备、改造场地、引进技术服务，重点为2024年认定的湖南省专精特新中小企业；（二）完善服务体系类项目，含服务能力建设项目和服务业务补助项目（“一起益企”服务、中小企业出海、“一月一链”融资促进等）。"},{"no":"三","heading":"项目申报程序","text":"市州项目由市州工信局牵头、财政局配合，联合行文上报省工信厅；财政省直管县市参照办理并抄报市州；省直单位申报服务体系项目由主管部门行文上报。审核部门在“信用湖南”查询信用情况并严格审查。"},{"no":"四","heading":"申报资料要求","text":"实行网上申报，不受理纸质资料，通过湖南省工信厅项目管理系统填报；2025年8月7日前完成系统审核上报及推荐文件上传，逾期不予受理。对报大建小、材料造假、多头重复申报的，取消资格并登记不良信用，三年内不得申报。"},{"no":"五","heading":"联系人及地址","text":"省工信厅地址：长沙市天心区新韶东路467号，邮编410004。专精特新发展类项目联系人孙丹0731-88955539；完善服务体系类项目联系人黄轶凡0731-88955535；系统技术咨询张凯迪0731-88955465。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202507/t20250709_33734493.html","sourceNote":"湖南省工信厅官网公开正文，2025年度一次性申报通知。；2026-11-08 核对：页面发布日期 2025-07-09","verified":true,"isSample":false,"hunan":true},{"id":"hunan-specialized-sme-2026-batch2","title":"关于组织开展2026年第二批湖南省专精特新中小企业申报工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅","documentNo":"","publishedAt":"2026-05-21","effectiveAt":"","expiresAt":"","status":"active","tags":["认定资质"],"audience":["中小企业","创新型中小企业"],"summary":"组织2026年第二批湖南省专精特新中小企业申报，须为有效期内创新型中小企业，经属地工信部门审核推荐、专家评审认定。","sections":[{"no":"一","title":"条件标准","text":"1.申报企业应在湖南省内依法设立，符合《中小企业划型标准规定》，遵守国家法律法规和行业规范。\n\n2.申报期间未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定。\n\n3.坚持企业自愿原则，符合《专精特新中小企业认定标准》（工信部企业〔2026〕2号，附件1）。\n\n4.重点聚焦制造强国重点产业（新一代信息技术产业、高档数控机床和机器人、航空航天装备、海洋工程装备及高技术船舶、先进轨道交通装备、节能与新能源汽车、电力装备、农机装备、新材料、生物医药及高性能医疗器械）、工业“六基”（核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础）、“4×4”现代化产业体系（现代石化、绿色矿业、食品加工、轻工纺织4大传统产业，工程机械、轨道交通装备、现代农业、文化旅游4大优势产业，数字、新能源、大健康、空天海洋4大新兴产业，以及人工智能、生命工程、量子科技、前沿材料4大未来产业）等领域。"},{"no":"二","title":"申报时间","text":"2026年5月20日-2026年6月1日"},{"no":"三","title":"申报方式","text":"1.申报企业须是有效期内的创新型中小企业，有效期内的专精特新中小企业、专精特新“小巨人”企业不再申报。\n\n2.按属地原则，申报企业须首先在优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下称“培育平台”）完成数字化水平评测，然后在培育平台进行线上申报，完整填写《专精特新中小企业申请书》，并打包上传佐证材料（附件2）。"},{"no":"四","title":"有关要求","text":"1.各市州工信部门要高度重视专精特新中小企业培育工作，认真履行职责，坚持条件标准，严格审核把关，确保申报质量。\n\n2.请各市州工信部门于6月1日前在培育平台提交审核意见，并将专精特新中小企业推荐函和汇总表（附件3，纸质件2份）报省工业和信息化厅，逾期不候。\n\n3.严禁弄虚作假。申报企业对申报材料的完整性、真实性、合法性负责，相关后果由申报企业自行承担。凡在申报过程中存在弄虚作假行为的，一经发现，取消本年度申报资格，并且三年内不得再次申报。\n\n4.严禁代理申报。省工业和信息化厅从未委托任何单位或个人为企业代理申报事宜，请相关企业按程序自主申报。凡委托代理申报的，一经发现，取消参评资格，且三年内不得再次申报。各级工信部门受理申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并请向当地相关部门举报。任何单位不得以参加收费培训班或解读班作为企业申报前提条件。\n\n联系电话：0731-88955419\n\n邮寄地址：长沙市天心区新韶东路467号\n\n培育平台相关问题咨询电话：85559832"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202605/t20260521_33982323.html","sourceNote":"2026-10-31 取自湖南省工业和信息化厅文件通知栏目原文页；原文未标注文号，documentNo 留空；申报窗口为2026-05-20至2026-06-01，认定标准依据工信部企业〔2026〕2号。；2026-11-08 核对：页面发布日期 2026-05-21","verified":true,"isSample":false,"hunan":true},{"id":"hunan-zhifuwanqi-digital-transformation-2025","title":"关于印发《深化“智赋万企”行动 加快制造业数字化转型实施方案》的通知","documentNo":"湘工信人工智能〔2025〕325号","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅、湖南省财政厅","publishedAt":"2025-09-12","effectiveAt":"2025-09-03","expiresAt":"2028-09-02","status":"active","tags":["数字化转型"],"audience":["制造业企业","专精特新中小企业"],"summary":"湖南省深化“智赋万企”行动、加快制造业数字化转型的实施方案。提出到2027年规上工业企业数字化研发设计工具普及率超90%、关键工序数控化率超75%，并从评估诊断、人工智能应用、工业互联网、数字化转型促进中心、数字园区、争创国家级标杆等方面明确财政支持比例与上限。","sections":[{"no":"一","heading":"目标要求","text":"以深化“智赋万企”行动为抓手，以推进企业数字化智能化改造为方向。到2027年，全省规上工业企业数字化研发设计工具普及率、关键工序数控化率分别超过90%、75%，全省工业大市和重点园区规上工业企业实现数字化改造全覆盖。"},{"no":"二","heading":"重点任务","text":"包括：（一）推动数字基础设施建设，提升智能算力供给、完善新型网络设施；（二）推动产业“智改数转网联”，健全数字服务体系、“点线面”协同推进；（三）推动人工智能技术和智能装备推广，推广人工智能创新应用、加快智能装备部署；（四）推动软硬件更新和安全防护，推动基础软硬件一体化更新、加快工业软件应用迭代、提升工业信息安全防护能力。"},{"no":"三","heading":"支持措施","text":"（一）评估诊断：省级财政对各市州购买诊断服务费用给予补贴，每家企业不超过2万元；（二）人工智能创新应用：优秀算法/数据产品按投资额20%支持、最高100万元，通过国家网信办备案的大模型按30%支持、最高300万元；（三）工业互联网：国家级“双跨”平台按30%、省级平台按20%支持，最高分别300万、100万元；（四）制造业数字化转型促进中心：国家级30%、省级20%，最高300万、100万元；（五）高标准数字园区：国家级30%、省级20%，最高300万、100万元；（六）争创国家级标杆及卓越级智能工厂：按投资额30%支持，最高300万元。"},{"no":"四","heading":"施行日期","text":"本方案自公布之日起实施，有效期3年。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202509/t20250912_33802671.html","sourceNote":"湖南省工信厅官网公开正文。有效期3年自2025-09-03公布日起算，到期日2028-09-02为推算。；2026-11-08 核对：页面发布日期 2025-09-12","verified":true,"isSample":false,"hunan":true},{"id":"national-unemployment-stable-jobs-2026","title":"人力资源社会保障部 教育部 财政部 国家税务总局关于失业保险支持企业稳岗扩岗的通知","documentNo":"人社部发〔2026〕39号","level":"national","region":"全国","issuer":"人力资源社会保障部、教育部、财政部、国家税务总局","publishedAt":"2026-07-10","effectiveAt":"2026-01-01","expiresAt":"2026-12-31","status":"expiring","tags":["就业补贴"],"audience":["企业","中小微企业"],"summary":"国家四部门延续实施失业保险稳岗扩岗政策：稳岗返还中小微企业按不超过上年度实缴失业保险费60%返还，一次性扩岗补助每招用1人不超过1500元，并优化技能提升补贴（初级/中级/高级分别不超过1000/1500/2000元）。政策执行期2026年1月1日至12月31日。","sections":[{"no":"一","heading":"延续实施稳岗返还政策","text":"参保企业足额缴纳失业保险费12个月以上、上年度未裁员或裁员率达标（30人及以下企业裁员率不高于参保职工20%）的，可享受稳岗返还。大型企业按不超过上年度实缴失业保险费30%返还，中小微企业按不超过60%返还。资金可用于职工生活补助、社保费缴纳、转岗培训、技能提升等。社会组织、律所、会所及以单位形式参保的个体工商户参照实施。"},{"no":"二","heading":"延续实施一次性扩岗补助政策","text":"对招用毕业年度及离校两年内未就业高校毕业生、16—24岁登记失业青年，签订劳动合同并足额缴纳3个月以上失业、工伤、职工养老保险费的企业和社会组织，按每招用1人不超过1500元标准发放一次性扩岗补助。"},{"no":"三","heading":"优化技能提升补贴政策","text":"参加失业保险12个月以上的在职职工或领取失业保险金人员，取得急需紧缺职业（工种）目录、数字和绿色职业等级证书之一的，按初级、中级、高级分别领取不超过1000元、1500元、2000元技能提升补贴，每人每年可享受1次，最多不超过3次。"},{"no":"四","heading":"加强高品质服务供给","text":"优化稳岗返还“免申即享”经办模式，通过后台数据比对精准发放；对没有对公账户的小微企业，经企业确认授权后可将资金返还至税务部门协助提供的缴纳社保费账户。"},{"no":"五","heading":"强化基金风险防控","text":"加强基金运行监测评估，设置事后业务核查环节，防范冒领骗取和多发错发。相关政策执行期限为2026年1月1日至12月31日。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/ztsy/zcrd/202607/t20260710_34024368.html","sourceNote":"湖南省人民政府门户网站转载人社部等四部门原文，2026-07-10发布；政策执行期2026-01-01至2026-12-31。；2026-11-08 核对：页面发布日期 2026-07-10","verified":true,"isSample":false,"hunan":false},{"id":"p-2020-3ff489","title":"湖南省社会保险补贴实施办法","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2020〕22号","publishedAt":"2020-11-03","status":"active","tags":["社保补贴","就业补贴"],"audience":["小微企业","高校毕业生"],"summary":"小微企业招用离校2年内未就业高校毕业生并签订1年以上劳动合同的，按实际缴纳的基本养老保险、基本医疗保险、失业保险单位缴费部分给予最长1年社保补贴。","sections":[{"no":"一","title":"第一条","text":"根据《国务院关于进一步做好稳就业工作的通知》(国发〔2019〕28号)、《湖南省人民政府办公厅关于印发<应对新冠肺炎疫情影响进一步做好稳就业工作十六条措施>的通知》(湘政办发〔2020〕20号)和《湖南省财政厅 湖南省人力资源和社会保障厅关于印发〈湖南省就业专项资金管理办法〉的通知》(湘财社〔2018〕25号)等文件精神,结合实际制定本办法。"},{"no":"二","title":"第二条","text":"本省行政区域内各类企业(单位)和公益性岗位招用就业困难人员,或小微企业招用离校2年内未就业高校毕业生申请享受社会保险补贴,以及就业困难人员和离校2年内未就业高校毕业生灵活就业后申报享受社会保险补贴的,适用本办法。"},{"no":"三","title":"第三条","text":"社会保险补贴按照属地管理原则,由参保所在地人力资源和社会保障、财政部门按照本办法规定受理并核拨社会保险补贴资金。在省本级参保且符合享受补贴条件的,就业困难人员在就业困难人员认定地申领,高校毕业生在就业登记地申领。\n第二章 社会保险补贴对象"},{"no":"四","title":"第四条","text":"具备下列条件之一的对象可以按规定享受社会保险补贴:\n(一)企业(单位)招用就业困难人员或安排就业困难人员在公益性岗位工作,且依法参加社会保险,企业(单位)和职工个人按规定履行了社会保险费(基本养老保险费、基本医疗保险费和失业保险费)缴纳义务,并与之签订1年以上劳动合同的;\n(二)小微企业招用离校2年内未就业高校毕业生,且依法履行了社会保险费(基本养老保险费、基本医疗保险费和失业保险费)缴纳义务,并与之签订1年以上劳动合同的;\n(三)就业困难人员灵活就业后,以灵活就业人员身份参加社会保险、且履行了社会保险费缴纳义务的;\n(四)离校2年内未就业高校毕业生灵活就业后,以灵活就业人员身份参加社会保险、且履行了社会保险费缴纳义务的。\n第三章 社会保险补贴范围、期限和标准"},{"no":"五","title":"社会保险补贴范围","text":"社会保险补贴范围\n企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和小微企业招用离校2年内未就业高校毕业生的,可申请基本养老保险、基本医疗保险和失业保险补贴,不包括个人应缴纳的部分。就业困难人员和离校2年内未就业高校毕业生进行灵活就业登记后,可申请基本养老保险、基本医疗保险补贴。代发放工资或代缴社会保险费的第三方单位,以及毕业时间(毕业证发放时间)超过2年的高校毕业生,不在补贴范围之内。"},{"no":"六","title":"社会保险补贴期限","text":"社会保险补贴期限\n(一)企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和就业困难人员灵活就业后享受社会保险补贴最长不超过3年;初次核定其享受社会保险补贴时间不早于初次申报时间一年,领取养老保险待遇后不再申报本补贴。自初次核定其享受社会保险补贴之日起计算,距法定退休时间不足5年的,可延长享受至法定退休时间;提前退休的,以实际退休时间作为享受补贴截止时间,补贴起始时间不能追溯至初次核定享受政策之前;延迟退休的,以法定退休时间作为享受补贴截止时间,延迟退休期间不再继续享受补贴。\n(二)企业(单位)招用就业困难人员、公益性岗位安排就业困难人员和就业困难人员灵活就业的,同一时间、同一对象只能享受企业吸纳社会保险补贴或灵活就业社会保险补贴之中的一种,不能同时享受;对同一人,在不同时间、不同单位,享受企业吸纳社会保险补贴和灵活就业社会保险补贴的累计时间不超过本办法规定的期限。\n(三)小微企业招用离校2年内未就业高校毕业生,给予最长不超过1年的社会保险补贴;对离校2年内未就业高校毕业生进行灵活就业登记的,给予最长不超过2年的社会保险补贴。补贴时限从初次核定其享受社会保险补贴之日起,至毕业时间满2年为止。不同小微企业招用同一符合条件高校毕业生的,均可按规定享受社会保险补贴,累计享受补贴时间不超过1年。同一符合条件高校毕业生,可在不同时间按规定享受小微企业吸纳社会保险补贴和灵活就业社会保险补贴。"},{"no":"七","title":"社会保险补贴标准","text":"社会保险补贴标准\n(一)对企业(单位)和公益性岗位招用就业困难人员、小微企业招用离校2年内未就业高校毕业生的,按其为就业困难人员和高校毕业生实际缴纳的基本养老保险费、基本医疗保险费、失业保险费单位缴费部分进行补贴,不包括个人应缴部分。未缴齐上述三种社会保险费的不予补贴。\n(二)符合条件的就业困难人员灵活就业社会保险补贴计算方式为:社会保险费缴费基数按上年度我省全口径社会平均工资的60%执行,费率按实际缴纳社会保险的费率执行。\"4050\"人员(女性年龄在40周岁以上、男性年龄在50周岁以上,下同)按上述方式计算金额的60%予以补贴,非\"4050\"人员按上述方式计算金额的40%予以补贴。\n(三)符合条件的离校2年内未就业高校毕业生灵活就业后社会保险补贴按前款非\"4050\"人员标准执行。\n第四章 社会保险补贴的申领"},{"no":"八","title":"社会保险补贴实行\"先缴后补\"方式","text":"社会保险补贴实行\"先缴后补\"方式。申请社会保险补贴企业(单位)按规定先行缴纳基本养老保险费、基本医疗保险费和失业保险费,且须通过湖南省公共就业服务信息管理平台(以下简称\"省平台\")向社会保险费缴纳地人力资源和社会保障部门申报社会保险费补贴。"},{"no":"九","title":"第九条","text":"申报社会保险补贴企业(单位)应按照省平台要求填报录入相关信息并上传以下资料:\n1.营业执照副本(组织机构代码证);\n2.与招用的就业困难人员或高校毕业生签订的劳动合同;\n3.享受补贴对象的身份证;属高校毕业生的,还需上传毕业证书。"},{"no":"十","title":"第十条","text":"就业困难人员和离校2年内未就业高校毕业生申报灵活就业社会保险补贴的,在完成缴费后,前往社会保险费缴纳地各社区(村)或通过官方平台自主申报,按要求填报相关信息并录入上传以下资料:\n1.社会保障卡或银行卡;\n2.属高校毕业生的,还需上传毕业证书。\n申报社会保险补贴企业(单位)和个人,对填报录入的所有信息的真实性、准确性负责,对提交虚假错误信息导致的后果由填报单位和个人全部承担。\n第五章 社会保险补贴资金审核拨付"},{"no":"十一","title":"第十一条","text":"人力资源和社会保障部门应及时对企业(单位)提交的社会保险补贴申请通过省平台进行审核。审核通过的,将符合条件的企业(单位)相关补贴信息在同级人力资源和社会保障门户网站公示7天,无异议后,按规定将补贴资金拨付至企业(单位)银行账户。\n公益性岗位安排就业困难人员、小微企业招用离校2年内未就业高校毕业生的社会保险补贴申请和资金拨付,按照上述规定执行。"},{"no":"十二","title":"第十二条","text":"灵活就业人员提交的社会保险补贴申请由社区(村)完成资料录入和调查,提交给街道(乡镇)进行确认,街道(乡镇)完成确认后,提交当地人力资源和社会保障部门进行审核。\n审核通过的,将符合条件的人员相关补贴信息在同级人力资源和社会保障门户网站公示7天,无异议后,按规定将补贴资金拨付至申请者本人社会保障卡账户或银行卡。\n第六章 服务与监督"},{"no":"十三","title":"第十三条","text":"各级人力资源和社会保障部门以及街道(乡镇)、社区(村)应当指导企业(单位)、就业困难人员、高校毕业生申报办理社会保险补贴,并提供咨询服务。"},{"no":"十四","title":"第十四条","text":"人力资源和社会保障、财政部门之间要加强沟通合作,精简工作流程,加强信息化建设,实行网上申报和经办,为申报企业(单位)和个人提供便利。各地人社部门应及时将享受补贴人员姓名、补助标准等情况及时纳入省平台管理,并实现与财政部门的信息共享。"},{"no":"十五","title":"第十五条","text":"人力资源和社会保障部门要做好本行政区域社会保险补贴政策的宣传、落实和统计工作,定期收集上报实施社会保险补贴政策的相关情况和问题。"},{"no":"十六","title":"第十六条","text":"人力资源和社会保障部门要设立举报投诉电话,接受社会监督;对不符合补贴条件或非法恶意骗取社会保险补贴的企业(单位)和个人,应责令其改正并依法追回被骗取的社会保险补贴资金,同时按规定纳入相关信用体系;构成犯罪的,依法追究其刑事责任。"},{"no":"十七","title":"第十七条","text":"人力资源和社会保障部门、财政部门的工作人员违规办理社会保险补贴的,分别由人力资源和社会保障部门、财政部门责令其改正;情节严重的,依法追究相关人员责任。"},{"no":"十八","title":"第十八条","text":"对疏于管理、违规发放社会保险补贴的地区,省人力资源和社会保障厅、省财政厅将适当扣减其下年度就业补助资金。\n第七章 附则"},{"no":"十九","title":"本办法自2021年1月1日起施行,有效期5年","text":"本办法自2021年1月1日起施行,有效期5年。我省之前有关社会保险补贴政策与本办法不一致的,以本办法为准。国家、省有明确新规的,从其规定。"},{"no":"二十","title":"第二十条","text":"各级人力资源和社会保障、财政部门可结合本地实际出台具体实施细则。"}],"interpretations":[],"sourceUrl":"https://rst.hunan.gov.cn/rst/xxgk/zcfg/zxzc/202011/13965787/files/595b67c2f8a940aa8afde9b0a6c964bc.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2023-093de0","title":"湖南省人力资源和社会保障厅 湖南省财政厅关于深入推进创业孵化基地建设工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅","documentNo":"湘人社规〔2023〕5号","publishedAt":"2023-05-08","status":"active","tags":["场地支持","创业补贴","就业补贴"],"audience":["小微企业","个体工商户"],"summary":"对经各级人力资源社会保障部门认定的创业孵化基地给予创业服务补助，每吸纳1家创业实体入孵按每家每月100元给予基地补助、创业实体在孵期间成功注册市场主体的按2000元每家给予一次性补助，每个基地每年享受创业服务补助总额最高不超过40万元，本通知自2023年5月10日起执行，有效期五年。","sections":[{"no":"一","title":"建设原则","text":"创业孵化基地建设按照“政府引导、园区主建、突出特色、注重实效”的原则，以培育市场主体和带动创业就业为导向，以推动创业孵化基地提质增量为目标，以强化优化创业孵化服务能力为重点，建设和认定一批管理规范、服务优良、孵化成功率高、创业带动就业效果好、辐射示范作用强的各级创业孵化基地，为创业者提供良好的创业场所和生态环境。\n\n二"},{"no":"二","title":"目标任务","text":"各县市区至少有1家创业孵化基地，各市州至少要有2家省级创业孵化基地。全省创业孵化基地（含创业园区）总量保持在400家左右，在孵创业实体（含创业企业、创业团队、创业项目）1万家以上，力争实现创业带动就业5万人。\n\n三"},{"no":"三","title":"工作措施","text":"（一）整合资源，加大建设力度。各级人力资源社会保障部门要将硬件好、资源优、服务能力强的各类创业园区、工业园区、院校创新创业学院等单位纳入建设范围，推动符合条件的单位积极申报认定创业孵化基地，推动有条件的县市区依托本地园区建设创业孵化基地。鼓励社会组织和民营企业积极参与创业孵化基地建设和运营，凝聚各方资源力量。各地要指导创业孵化基地面向不同产业行业、不同创业群体配齐配优服务，打造特色基地。\n\n（二）强化指导，提高服务水平。各地要推动创业孵化基地强化服务能力建设，指导孵化基地不断健全和完善孵化服务体系。各市州人力资源社会保障部门每年至少要开展1次创业孵化基地管理和服务人员业务培训班，重点提升基地创业项目指导、投融资对接、补贴政策申请、事务代办等服务能力，不断提高孵化服务水平。各地要为各创业孵化基地至少对接2名湖南省创业创新导师团成员（专家、讲师至少各1名），为在孵实体提供创业辅导、技术辅导、政策辅导、赛事辅导等服务，并将服务情况录入湖南省人社业务一体化经办平台（以下简称省平台）。\n\n（三）依托平台，优化服务经办。依托省平台建立全省创业孵化基地信息库和在孵创业实体信息库，各创业孵化基地和在孵创业实体要及时更新单位基本信息、运营管理信息等，确保各项信息真实、准确、完整，为基地建设运营和管理信息化智能化提供数据支撑。各创业孵化基地要通过省平台对创业项目、创业团队和初创企业从评估入园、孵化培育到转化出园的全生命周期进行跟踪管理，要指导协助在孵创业实体按省平台要求完整录入相关信息，准确记录运营情况，及时受理其服务请求并反馈服务结果。\n\n（四）规范发展，实行动态管理。各地每年开展1次创业孵化基地认定工作，将具备条件、积极性高的优秀单位认定为当地创业孵化基地。各地每年要对已认定的创业孵化基地进行复评，对照省平台内各孵化基地创业服务成效情况，对孵化效果欠佳、服务能力不足、工作配合度和群众满意度不高，以及不再符合创业孵化基地认定标准的单位，要取消认定并及时予以退出。\n\n四"},{"no":"四","title":"政策支持","text":"（一）给予创业孵化基地创业服务补助。对经各级人力资源社会保障部门认定的创业孵化基地给予创业服务补助。创业孵化基地每吸纳1家创业实体入孵，按每家每月100元的标准给予基地补助；创业实体在孵期间成功注册市场主体的（在孵创业实体入孵前未注册市场主体），按2000元每家给予基地一次性补助；创业孵化基地内的各在孵创业实体与劳动者签订1年以上劳动合同，签订的劳动合同总人数超过50人的按3万元每年的标准给予基地补助，超过100人的按6万元每年的标准给予基地补助，超过150人的按9万元每年的标准给予补助。被认定为市级创业孵化基地的补助金额总数上浮20%，被认定为省级的补助金额总数上浮40%，被认定为国家级的补助金额总数上浮60%，就高不就低。同一创业孵化基地中的同一在孵创业实体注册多个市场主体的，只能计算1家，不重复补贴。每个基地每年享受创业服务补助总额最高不超过40万元，按照就业专项资金使用的有关规定，主要用于开展创业孵化基地服务项目清单中的有关服务，以及孵化基地服务能力建设和提升，所需资金从所在地就业专项资金中列支。\n\n（二）给予一次性创业补贴。对在孵实体中正常运营一年以上并吸纳一定规模就业的初创企业和初次注册的个体工商户，按规定给予一次性创业补贴，主要用于创业经营性场所租金补贴、一次性开办费补贴和商标补贴等。其中创业经营性场所租金补贴部分，由创业孵化基地代为申请代为支付。所需资金从所在地就业专项资金中列支。\n\n（三）鼓励开展创业服务和活动。支持湖南省创业创新导师团成员为在孵创业实体提供创业指导服务。对于每年积极提供创业服务次数多、满意度高的创业创新导师，优先吸纳为省级创业创新导师团成员；鼓励优秀创业创新导师成立创业指导工作室，为创业实践持续提供后续服务；各级人力资源社会保障部门可通过政府购买创业服务成果的方式，支持创业孵化基地开展创业沙龙、创业讲堂、创业训练营、项目展示交流等创业活动，为创业者搭建资源对接的平台。所需资金从所在地就业专项资金中列支。\n\n（四）落实创业担保贷款相关政策。符合条件的创业孵化基地在孵创业实体申请20万元以下个人创业担保贷款的，免除反担保要求，按规定给予贴息。超过20万元且确需提供反担保的，市级以上创业孵化基地可为其在孵创业实体提供信用担保。\n\n（五）示范引领。各地要按照突出成效、重在特色、典型引领的原则，每年认定一批本级创业孵化基地，发文公布，授予牌匾，引领带动创业孵化基地做大做强，做精做专。\n\n各地安排的其他非就业专项资金用于支持创业孵化基地建设的，可按照自行制定的文件执行。\n\n五"},{"no":"五","title":"工作要求","text":"（一）加强组织领导。各地要把创业孵化基地建设工作作为落实“创响三湘”行动和“五创联动”的重要举措，加强规划引导，做好基地认定、指导、服务、管理等工作，结合本地实际制定细则，认真落实各项补贴政策，切实提升创业孵化基地管理服务水平和孵化实效。\n\n（二）强化工作推动。各地要依托省平台实时掌握创业孵化基地政策落实、创业服务开展、带动就业和满意度情况，上述情况将作为全省创业带动就业相关工作评先评优和考核的重要评价指标，以及享受资金补贴的重要依据。\n\n（三）加强资金监管。各地要按照“谁使用、谁审核、谁负责”的原则，全面加强对创业孵化基地相关补贴资金的监管。要严格按照有关规定做好资金申报、审核和拨付工作，做到公开透明、公平公正，坚决杜绝优亲厚友、虚报冒领等行为。对存在徇私舞弊、套取骗取、贪污挪用等违法违纪行为的，依照法律法规和有关规定严肃追究责任。\n\n本通知自2023年5月10日起执行，有效期五年。此前有关规定与本通知不一致的，以本通知为准。\n\n联系人：胡川 0731-84900136\n\n附件：1.创业孵化基地认定的基本条件\n\n2.创业孵化基地认定及复核程序\n\n3.创业孵化基地服务项目清单\n\n4.创业孵化基地申请表\n\n5.在孵创业实体名册\n\n6.孵化基地补贴申请表"}],"interpretations":[],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS//file/2023/07/14/20230714172148612rpbxgf.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：湘人社规〔2023〕5号，HNPR-2023-11003","verified":true,"isSample":false,"hunan":true},{"id":"p-2023-c9b55d","title":"关于印发《湖南省中小企业发展专项资金管理办法》的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、湖南省工业和信息化厅","documentNo":"湘财企〔2023〕6号","publishedAt":"2023-12-28","status":"active","tags":["专项资金"],"audience":["小微企业"],"summary":"专项资金由省级财政一般公共预算安排、采取财政补助和以奖代补等支持方式，支持中小企业提升创新能力及专业化水平、完善中小企业公共服务体系等，本办法自2024年1月1日起施行，有效期至2026年12月31日。","sections":[{"no":"一","title":"第一条","text":"为规范湖南省中小企业发展专项资金的使用管理，提高资金的使用效益，根据《中华人民共和国预算法》《中华人民共和国中小企业促进法》和《湖南省实施〈中华人民共和国中小企业促进法〉办法》等有关规定，结合我省实际，制定本办法。"},{"no":"二","title":"第二条","text":"本办法所称湖南省中小企业发展专项资金（以下简称专项资金），是指依据《中华人民共和国中小企业促进法》设立，由省级财政一般公共预算安排用于支持中小企业发展的资金。"},{"no":"三","title":"第三条","text":"专项资金管理使用遵循公开公正、择优高效的原则，围绕党中央、国务院和省委、省政府有关决策部署，重点引导完善中小企业公共服务体系、改善中小企业发展环境，突破制约中小企业发展的短板和瓶颈，支持中小企业高质量发展。"},{"no":"四","title":"第四条","text":"专项资金由省财政厅和省工业和信息化厅（以下简称省工信厅）按职责分工共同管理。省财政厅负责明确年度专项资金额度，会同省工信厅确定专项资金支持方向和重点、支持方式和标准；根据省工信厅报送的年度专项资金分配方案、绩效目标建议及有关材料，按程序下达预算、绩效目标并拨付资金；指导督促省工信厅开展监督管理工作。\n\n省工信厅负责提出专项资金年度支持方向和重点、资金需求测算方案、绩效目标；组织项目申报、汇总、审查、评审；根据年度预算编制要求，及时向省财政厅提供年度专项资金分配方案；加强业务指导、绩效管理、监督管理等工作；督促有关方做好专项资金支持政策实施工作。\n\n各市州、财政省直管县（市）财政、工信部门参照省级部门职责分工做好专项资金下达后的资金使用、项目报备、业务指导等工作，并进行监督和全过程绩效管理。\n\n资金申报、使用单位承担资金及项目绩效目标的真实客观申报，合规使用和有效管理的主体责任，负责直接受理资金申报材料的主管部门承担资金申报审核、资金使用监督的直接责任。"},{"no":"五","title":"第五条","text":"专项资金实行管理办法、申报通知、评审结果、分配结果、绩效评价全过程公开。"},{"no":"六","title":"专项资金的支持范围包括：","text":"专项资金的支持范围包括：\n\n（一）支持中小企业提升创新能力及专业化水平，优化创新创业环境。\n\n（二）支持完善中小企业公共服务体系，促进中小企业开展合作交流。\n\n（三）其他促进中小企业发展的工作。\n\n在符合上述支持方向内，每年根据党中央、国务院和省委、省政府有关决策部署，结合我省中小企业发展实际情况、亟待突破的短板和瓶颈等，由省财政厅、省工信厅按照零基安排、绩效导向的原则确定专项资金支持重点。对符合规定条件的新增重大项目和政策，省工信厅要组织开展事前绩效评估。"},{"no":"七","title":"第七条","text":"专项资金支持对象包括符合条件的项目或企业、中小企业公共服务平台等机构或载体，市县、园区等试点示范区域。"},{"no":"八","title":"第八条","text":"专项资金采取财政补助、以奖代补等支持方式，主要用于引导各级政府、社会资本等支持中小企业高质量发展。"},{"no":"九","title":"第九条","text":"专项资金不得用于平衡本级财政预算及偿还债务，不得用于行政事业单位人员经费、机构运转经费等。"},{"no":"十","title":"第十条","text":"专项资金分配可以采取因素法、项目法、因素法和项目法相结合等方式。"},{"no":"十一","title":"专项资金下达时间进度按照预算管理有关规定执行","text":"专项资金下达时间进度按照预算管理有关规定执行。省工信厅报送专项资金分配方案的时间不得晚于专项资金下达时限的前15日。各级财政部门应在收到专项资金指标发文30日内，将专项资金按要求拨付使用单位。"},{"no":"十二","title":"第十二条","text":"专项资金支付按照财政国库管理制度有关规定执行，涉及政府采购的，应当按照政府采购法律法规和有关制度执行。"},{"no":"十三","title":"第十三条","text":"省财政厅、省工信厅根据预算绩效管理和本办法的规定，以及专项资金有关支持政策文件，按照职责分工组织实施专项资金的绩效运行监控、绩效评价，加强绩效评价结果反馈应用。有关绩效评价结果，作为专项资金分配的重要参考。各市州、财政省直管县（市）财政、工信部门应按规定要求实施绩效评价。"},{"no":"十四","title":"省工信厅应当会同省财政厅加强对专项资金的监督管理","text":"省工信厅应当会同省财政厅加强对专项资金的监督管理。各市州、财政省直管县（市）工信、财政部门要建立健全专项资金使用管理、监督检查和跟踪问效制度，如发现资金申报、资金使用存在问题的，应当及时报告省工信厅和省财政厅。"},{"no":"十五","title":"第十五条","text":"资金使用单位收到专项资金后应当按照国家统一的财务会计制度规定管理。专项资金应当专款专用，主动接受财政、审计等部门的监督检查，不得用于支付各种罚款、捐款、赞助等。有关项目实施情况应当接受工信、财政等部门的调度和检查。"},{"no":"十六","title":"第十六条","text":"资金使用单位因市场环境、政策变化等导致不再符合专项资金支持标准的，应及时向直接受理其资金申报材料的工信、财政部门报告，有关工信、财政部门应及时向省工信厅、省财政厅报告。省工信厅会同省财政厅提出处理意见，市县有关部门督促落实，并按要求暂缓、停止拨付资金或收回已拨付资金。"},{"no":"十七","title":"第十七条","text":"专项资金应当严格执行有关财务、会计制度，实行专款专用，不得列支与项目无关的费用。"},{"no":"十八","title":"第十八条","text":"专项资金申报、评审、分配、拨付使用等过程中存在虚报、冒领、截留、挪用、滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，严格按照《中华人民共和国预算法》《中华人民共和国公务员法》《中华人民共和国监察法》《财政违法行为处罚处分条例》等国家有关规定追究责任，涉嫌犯罪的，移送司法机关处理。资金使用单位应当严格遵守财政财务制度和财经纪律，建立健全专项资金管理制度和内部控制制度，加强财务稽核和内部审计，自觉接受审计、财政及主管部门的监督检查。"},{"no":"十九","title":"第十九条","text":"本办法自2024年1月1日起施行，有效期至2026年12月31日。到期后，省财政厅组织开展该专项的实施期绩效评估，评估结果作为该专项存续的依据。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/ztzl/zxzj/zdbf/202403/t20240328_33265389.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2023-12-30","verified":true,"isSample":false,"hunan":true},{"id":"p-2024-7ab56f","title":"关于进一步支持大学生创业就业的若干措施","level":"provincial","region":"湖南省","issuer":"湖南省人力资源和社会保障厅、湖南省财政厅、湖南省教育厅","documentNo":"湘人社规〔2024〕2号","publishedAt":"2024-05-17","status":"active","tags":["创业补贴","贷款贴息","融资支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"大学生初次创办企业或个体工商户正常经营1年以上的，一次性创业补贴最低标准提高至1万元；创业担保贷款额度最高提高至400万元，20万元以下免除反担保。","sections":[{"no":"一","title":"支持和鼓励高校科研人员和学生共同创业","text":"1、高校科研人员离岗与学生共同创办企业的,其本人职称、年龄、资历、科技成果形式、获奖层次、获得专利与否均不作为限制条件,经个人书面申请,单位批准同意,可以申请1次离岗创业,最长期限不超过3年,可在3年内保留人事关系。离岗创业期间,停发工资福利待遇,养老保险、医疗保险(含生育保险)和职业年金依法继续由人事关系所在单位缴纳,单位部分由单位承担,个人部分由个人负责。工伤保险在所创办的企业缴纳,发生工伤时依法享受工伤保险待遇。离岗创业期间,允许通过所创办企业申报职称,所获得的职称可以作为其返回事业单位后参加岗位竞聘的参考。创业业绩突出,年度考核被确定为优秀等次的,不占原单位年度考核优秀比例。提前返岗的,应提前书面报告其人事关系所在单位,单位应在三个月内为其安排相应岗位。本人提出解除聘用合同的,其人事关系所在单位应及时依法解除合同,个人人事档案由用人单位转移到同级人社部门所属人力资源档案管理机构免费保管。\n2、高校科研人员在职与学生共同创办企业的,可在不影响完成本职工作的基础上,经个人书面申请,单位批准同意,进行在职创办企业。期间允许继续享有参加职称评审、项目申报、岗位竞聘、培训、考核、奖励等各方面权利,工资、社会保险等各项福利待遇不受影响。允许与企业职工同等享有获取报酬、奖金、股权激励的权利,国家另有规定的从其规定。工伤保险由在职创办企业缴纳,其在人事关系所在单位外工作期间发生工伤的,依法享受工伤保险待遇,由相关企业承担工伤保险责任。经与人事关系所在单位协商一致,可以实行相对灵活、弹性的工作时间。\n二"},{"no":"二","title":"加大对大学生创业的金融支持力度","text":"3、设立湖南省大学生创业投资基金,扶持大学生创业就业。基金主要投资于具有良好市场发展前景的初创型项目,采用股权投资模式,重点支持大学生主导的创业项目。\n4、降低创业担保贷款及贴息门槛,对于高校毕业生、创业孵化基地在孵实体、获得\"中国创翼\"创业创新大赛市级以上(含市级)奖项的项目和中国国际大学生创新大赛金奖的项目,申请20万元以下个人创业担保贷款的,免除反担保手续,并按规定给予贴息。健全追偿代偿和呆坏账核销机制,制定担保基金尽职免责和激励约束办法,合理提升担保基金代偿比例和效率。加大省级财政支持力度,探索建立各级风险共担机制。\n5、提高一次性创业补贴标准,对大学生初次创办的企业或初次注册的个体工商户,且正常经营1年以上的,按规定给予一次性创业补贴,最低补贴标准提高至1万元(各市州已制定一次性创业补贴标准的,就高不就低)。\n6、提高贷款额度,对大学生创办的符合贷款条件的小微企业,创业担保贷款额度最高提高至400万元。\n三"},{"no":"三","title":"加大对大学生创业的培训和指导力度","text":"7、深入实施\"马兰花\"创业培训行动,将有创业意愿的在校大学生纳入创业培训补贴范围,强化创业基础培训和后续\"陪跑\"服务,全面落实\"创办你的企业\"\"乡村领雁\"培训课程后续服务补贴。完善创业培训后续服务内容和清单,加快制定\"改善你的企业\"\"网络创业培训\"等课程后续服务补贴标准。加强创业培训课程开发,组织专家团队开发适合大学生创业群体创业特性的培训课程体系。\n8、支持高校和社会力量建立\"创业指导工作室\",支持工作室导师采用\"揭榜挂帅\"的方式,对大学生创业项目提供一对一指导、创业培训后续服务和创业\"陪跑\"服务等。鼓励成立创业服务协会、大学生创业者联盟等社会组织,组织开展创业讲堂、创业训练营、创业实训等创业服务活动。\n9、探索在职称(职务)评聘工作中单独设立大学生创业和就业指导专业,进一步畅通创业就业指导教师职称评审渠道。建立完善省级高校创业创新导师数据库,从高校、企业及社会创业就业服务机构遴选创业创新专家。支持高校从校外选聘创业创新专家担任兼职教师,充实高校创业创新师资力量,加快培养一支数量充足、素质优良、服务优质的创业就业导师人才队伍,为我省大学生创业就业指导和研究提供人才储备与智力支持。\n四"},{"no":"四","title":"加大对大学生创业的示范引领力度","text":"10、开展优秀大学生创业项目认定,每年扶持一定数量的已纳入创业孵化基地入孵管理大学生创业项目或创业团队开展创业。对获评省级大学生创业孵化基地的给予重点支持,对各高校开展校园招聘工作,按规定给予校园招聘活动补助。\n11、鼓励各院校建设大学生创业孵化基地,并及时纳入我省创业孵化基地认定范围,开展大学生创业创新孵化示范基地评建,将大学生创业项目孵化时间延长至5年,按规定落实创业孵化基地创业服务补助。降低大学生创业团队入驻条件,优化服务经办流程,为大学生创业团队提供创业指导、开业指导等\"一站式\"孵化服务。鼓励其他院校以外的社会各创业孵化基地安排场地优先提供给大学生创业项目入驻,并给予场租和管理费用减免。\n五"},{"no":"五","title":"加大对大学生创业的保障力度","text":"12、探索设置大学生创业保险,通过政保合作的方式,为大学生创业\"兜底\",解除大学生创业的后顾之忧。完善大学生创业预警机制,对于创业失败大学生及时开展职业培训、就业援助、就业服务,帮助\"再就业\"\"再创业\"。\n13、坚持以赛促教、以赛促学、以赛促创,鼓励各级举办\"中国创翼\"创业创新大赛、中国国际大学生创新大赛、 \"耀动三湘\"网络创业直播大赛等各类创业大赛,引导不同学段学生积极参赛,激发大学生创业创新热情。鼓励与行业企业深化赛事合作,拓宽办赛资金筹措渠道。加强对各类大赛中涌现的优秀项目进行后续跟踪,推动一批大赛优秀项目落地。\n14、建设湖南省大学生创业就业大平台,融合信息服务、技术培训、机动实习、成果转化、企业孵化等内容,加强创业资源的整合与利用。在全省大学生创业创新孵化一体化服务平台、\"湘就业\"平台上设置创业服务专区,推动创业政策发布、信息查询、项目申报、资源对接等功能\"一网集聚\",方便高校学生享受创业一站式服务。\n15、进一步优化政策资金申领流程,充分利用大数据比对等方式,减少申报资料提交,推动实现网上申报、网上审核、联网核查。对能依托管理信息系统或与相关单位信息共享、业务协同获得的个人及单位信息、资料的,不再要求单位及个人报送纸质材料,符合条件的要及时拨付资金。要加强全过程监督,对工作人员在项目申报、评选及资金拨付使用等工作中,存在滥用职权、玩忽职守、徇私舞弊等违纪违法行为的,依照国家有关法律法规追究相应责任。涉嫌犯罪的,依法移送司法机关处理。\n16、加强大学生创业宣传引导,利用短视频等各类新媒体资源,建立宣传矩阵,及时发布相关政策文件与政策解读。利用\"创业微电影\"等方式广泛宣传大学生创业优秀案例,树立大学生创业典型,培育高校创客文化。组织开展\"企业家进校园讲好创业就业故事\"等系列活动,遴选更多优质企业家深入高校开展创业创新公益活动,每年省级层面举办讲座不少于20场次,营造\"鼓励创业、宽容失败\"的良好氛围。\n本文件自2024年5月21日起执行,有效期五年。此前有关规定与本文件不一致的,以本文件为准。"}],"interpretations":[],"sourceUrl":"https://img.zhuzhou.gov.cn/zzcms/DFS/file/2024/06/11/20240611090410597w5kpib.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2025-42786b","title":"关于印发《张家界市进一步降本减负优化营商环境九条措施》的通知","level":"city","region":"张家界市","issuer":"张家界市人民政府办公室","documentNo":"张政办发〔2025〕13号","publishedAt":"2025-07-17","status":"active","tags":["融资支持","场地支持","社保补贴"],"audience":["小微企业","高校毕业生"],"summary":"张家界降低融资、用能、用工、物流、中介、审批、用地、税费、制度性交易九方面成本，优化营商环境。","sections":[{"no":"一","title":"降低融资成本","text":"降低融资成本。严格落实支持小微企业融资协调工作机制，抓实\"千企万户大走访\"，保持小微企业信贷有效供给。加大首贷、信用贷、中长期贷款投放力度，推动法人银行普惠型小微企业贷款和民营企业贷款增速均高于各项贷款增速。持续优化小微企业续贷机制，覆盖2027年9月30日前到期的中型企业流动资金贷款。建立续贷沟通机制，贷款到期前1个月主动对接，实现\"应续尽续\"。根据LPR定价机制，及时主动调整涉企贷款利率。全面落实企业融资收费\"两禁两限\"规定，除银团贷款外不得对小微企业贷款收取承诺费、资金管理费，严格限制对小微企业及其增信机构收取财务顾问费、咨询费。积极推进农村\"三信\"创建，发挥信用信息支持产业融资的作用。充分发挥张家界\"金融超市\"平台、企业收支流水征信平台作用，加大信贷投放力度，力争小微企业信用贷款占比达20%以上。用好我市农业产业贷款风险补偿基金、产业发展基金，不断健全\"政银保担投\"全链条金融服务体系。（市政府办公室、中国人民银行张家界市分行、国家金融监管总局张家界监管分局、市发展改革委、市工业和信息化局、市农业农村局、市融资担保集团公司等按职责分工负责，各区县人民政府负责落实本区县工作；以下均需各区县人民政府负责落实本区县工作，不再列出）\n二"},{"no":"二","title":"降低用能成本","text":"降低用能成本。积极对接和落实天然气管网\"一张网、一个价\"改革。加大对土木溪水厂和花岩水厂设施建设和改良力度。实行用电重点项目\"项目长\"负责制，对重点企业和电价水平长期较高的用户，开展\"一企一策\"指导，支持企业用活分时电价政策，常态开展工业园区客户走访行动。鼓励企业配置新型储能设施，提倡\"低充高用\"，鼓励园区企业加强余热利用。（市住房城乡建设局、国网张家界供电公司、市发展改革委、市自来水公司等按职责分工负责）\n三"},{"no":"三","title":"加大用工保障和补贴降费力度","text":"加大用工保障和补贴降费力度。用好\"用工超市\"和\"张家界就业\"平台，加强就业岗位信息归集共享，2025年发布岗位30万个以上。利用5G技术将招聘信息动态推送至村组干部，加强线上直播带岗。精准发放一次性扩岗补助、吸纳就业困难人员、离校2年内未就业高校毕业生社会保险补贴、就业见习补贴。开展补贴性职业培训6500人次，落实补贴资金900万元。推广\"订单式\"培训，在湖南旅游技师学院开设企业定向技能培养班。继续落实社保降费政策，延续实施阶段性降低失业保险费率至1%政策。实现失业保险稳岗返还政策\"免申即享\"。进一步做好企业用工服务保障工作。（市人力资源社会保障局、市财政局等按职责分工负责）\n四"},{"no":"四","title":"降低物流成本","text":"降低物流成本。调整优化运输结构，持续推进\"公转铁\"。推进铁路物流园建设，2025年完成项目招商引资和立项审批，2026年开工建设。引进1—2家多式联运现代物流企业入驻我市。加快货运设备更新升级，推广使用新能源货运车辆。严格执行鲜活农产品运输\"绿色通道\"政策，落实道路运输和水路运输燃油补贴申报与发放。推行农村客货邮融合发展模式，持续完善县乡村三级物流体系，加强分拨中心、配送中心和末端网点建设。（市交通运输局、市发展改革委、市商务局、张家界高新区管委会、市自然资源和规划局、市邮政管理局等按职责分工负责）\n五"},{"no":"五","title":"降低中介服务成本","text":"降低中介服务成本。按照\"政府引导、行业自律、市场调节\"原则，深入推动中介服务改革，大力开展行政审批中介服务事项清理，梳理公布各类评估评价、检验检测等涉审中介服务事项清单，审批部门不得要求经营主体提供清单之外的中介服务报告。用好\"中介超市\"，实现机构选择、费用支付、报告上传、服务评价等全流程网上办理。引导成立中介服务行业协会或社会组织并加强行业自律，规范中介服务收费，严厉查处中介服务机构出具虚假证明或报告、谋取不正当利益、\"官荐中介\"等违规行为。（市委深改办、市发展改革委、市数据局、市政务服务中心、市市场监管局等按职责分工负责）\n六"},{"no":"六","title":"降低行政审批成本","text":"降低行政审批成本。市、区县政务服务部门建立网办帮办领办机制，大力推行\"全程网办\"，根据企业和群众需求免费提供帮办领办服务，构建\"除了网上办就是帮办领办\"的政务服务新格局。强化行政效能分析以及在线监察，对\"红黄牌\"和\"差评\"加强处置，推动审批人员按期办、提速办、优质办。进一步推动工改系统改革，规划和自然资源、住房城乡建设部门审批时间再压缩20%以上。（市数据局、市政务服务中心等按职责分工负责）\n七"},{"no":"七","title":"降低工业用地成本","text":"降低工业用地成本。用好\"土地超市\"，实现\"一站式\"选地购地，缩减企业拿地时间。探索建立城乡统一基准地价体系，支持产业用地\"标准地\"出让，采用工业用地长期租赁、先租后让、租赁与出让结合、弹性年期出让等供应方式，产业园区全面推进\"用地清单制+告知承诺制\"和\"五即\"（洽谈即服务、签约即供地、开工即配套、竣工即办证、达产即复核）供地模式。继续推进\"验登合一\"\"多测合一\"，针对小微企业免收不动产登记费。（市自然资源和规划局、市工业和信息化局、张家界高新区管委会等按职责分工负责）\n八"},{"no":"八","title":"降低税费成本","text":"降低税费成本。精准推送结构性减税降费政策，实现\"政策找人\"\"一企一策\"个性化服务，推进惠企税务政策\"直达快享\"。提供数字化发票开具、交付、使用服务，降低企业票据管理成本和交易成本。优化纳税信用评价，提升\"银税互动\"质效，将企业纳税信用转化为融资信用，提升企业融资便利度。定期召开税企\"面对面\"座谈交流会，高效解决企业涉税问题。加强涉企收费长效监管，动态更新涉企收费目录，加大违规收费治理力度。（市税务局、市财政局、市发展改革委、市市场监管局等按职责分工负责）\n九"},{"no":"九","title":"降低制度性交易成本","text":"降低制度性交易成本。积极主动融入全国统一大市场建设，修订《张家界市政府性投资工程招投标实施操作办法》，完善政府采购配套措施，推广\"机器管招投标\"，建立排除人工干预的公共资源交易模式，提高评标效率，约束专家自由裁量权。（市发展改革委、市财政局、市公共资源交易中心等按职责分工负责）"}],"interpretations":[],"sourceUrl":"http://www.zjj.gov.cn/c693/20250731/i1095938.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2025-5136c2","title":"湖南省财政厅等四部门关于实施大学生创业贷款财政补助政策的通知","level":"provincial","region":"湖南省","issuer":"湖南省财政厅、中共湖南省委金融委员会办公室、湖南金融监管局、中国人民银行湖南省分行","documentNo":"湘财金〔2025〕43号","publishedAt":"2025-10-21","status":"active","tags":["贷款贴息","融资支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"对在湘个人创业或合伙创业的大学生，个人创业贷款额度不超过50万元、小微企业及其他市场主体创业贷款额度不超过500万元，省财政按贷款实际利率的50%给予贴息、按担保金额的1.5%给予担保机构担保费补贴，本通知自印发之日起实施，有效期至2027年12月31日。","sections":[{"no":"一","title":"政策内容","text":"（一）支持对象与适用条件\n\n1.支持对象：在湘个人创业或合伙创业的大学生。\n\n2.适用条件：同时符合以下条件的创业贷款，可享受省财政补助。\n\n贷款发放时间：本通知印发之日起至2027年12月31日期间新发放。政策到期后如需延期，另行通知。\n\n贷款方式：通过信用贷款方式或由省内纳入再担保体系的政府性融资担保机构（以下简称担保机构）提供免费担保。\n\n贷款额度与利率：个人创业贷款额度不超过50万元，小微企业及其他市场主体创业贷款额度不超过500万元；贷款利率不超过同期贷款市场报价利率（LPR）加100个基点（Bps）。\n\n资金用途：专项用于大学生在湘创办市场主体（企业、个体工商户等）的日常经营、技术研发、设备采购等生产经营活动。\n\n主体资格：“大学生”指国内外在校学生或毕业5年（含）内的大专、本科、硕士、博士毕业生，以及技师学院在校或毕业5年（含）以内的毕业生。残疾人大学生可放宽至毕业8年（含）内的毕业生。\n\n（二）财政补助标准\n\n1.贴息：对经办银行发放的符合条件贷款，省财政按贷款实际利率的50%给予贴息，贴息期限最长不超过3年。逾期或展期的贷款，自逾期或展期之日起不再享受贴息。\n\n2.担保费补贴：省财政按担保金额的1.5%给予担保机构担保费补贴。担保费补贴按实际承保期限计算，按年度补贴。\n\n3.风险补偿：对担保机构与经办银行合作开展的大学生创业担保贷款业务，代偿率在5%（含）以内的部分，由省财政、担保机构、经办银行按40%、40%、20%的比例分担风险。\n\n二"},{"no":"二","title":"经办银行与贷款流程","text":"（一）经办银行范围\n\n省财政补助政策适用于以下开发并运营大学生创业专属贷款产品的银行：中国工商银行等18家全国性银行在湘分支机构、湖南银行、长沙银行及省内各农村商业银行。\n\n（二）经办担保机构范围\n\n省财政补助政策适用于省内纳入再担保体系的政府性融资担保机构。\n\n（三）贷款申请\n\n符合条件的大学生，可向所在地经办银行提出贷款申请，并提供以下材料：\n\n身份证明：在校生提供学校盖章的在校证明；毕业生提供学信网信息查询截图及学历证书（或国外学历学位认证书）复印件。经办银行须核实其真实性。\n\n主体证明：借款人是个体工商户的，提供营业执照；借款人是小微企业或小微企业主的，需提供大学生合计持股比例不低于10%的股东身份证明、担任关键核心岗位（董事长、执行董事、总经理、副总经理、技术总监、营销总监、财务总监、生产总监等）证明及营业执照。\n\n（四）贷款审核与发放\n\n经办银行遵循市场化原则，独立审核、审批贷款申请，自主决定贷款发放与否及具体条件，对符合条件的申请应及时放款。需担保的贷款，经办银行可与担保机构合作，鼓励采用“见贷即保”或联合尽调模式，简化流程。鼓励经办银行、担保机构与大学生创业投资基金建立“投贷担”联动机制，对大学生创业投资基金投资的项目，降低贷款门槛和利率，建立绿色审批通道，优先发放贷款。\n\n三"},{"no":"三","title":"财政补助资金流程","text":"（一）资金预拨\n\n省财政厅按年度向经办银行省级机构（全国性银行省级分行、城市商业银行总行、省农村信用社联合社）预拨贴息资金，向担保机构预拨担保费补贴和风险补偿资金。\n\n（二）资金结算\n\n1.贴息资金。经办银行收到预拨贴息资金后，在收取利息时直接扣减贴息部分。经办银行省级机构按季度向省委金融办数据平台报送贷款发放及贴息情况。每年1月20日前，经办银行省级机构向省委金融办提交上年度贴息资金结算申请及证明材料（贷款合同、借款人身份及主体证明、资金用途证明等）。省委金融办于3月10日前完成审核，将审核结果报省财政厅。省财政厅依据审核结果与经办银行完成年度结算。\n\n2.担保费补贴与风险补偿资金。担保机构发生的担保贷款业务须在省再担保系统备案。每年2月10日前，省再担保公司完成各担保机构上年度担保费补贴、风险补偿资金的结算审核，并将结果报省委金融办。省委金融办复核，并于3月10日前将复核结果报省财政厅。省财政厅依据复核结果与担保机构完成年度结算。\n\n四"},{"no":"四","title":"监督管理","text":"（一）专款专用\n\n贷款主体须确保贷款资金专项用于生产经营活动，严禁虚报、冒领、套取、截留、挤占、挪用；严禁用于偿还其他债务、投资理财等套利活动及个人消费等非生产经营领域。\n\n（二）强化监管\n\n湖南金融监管局落实小微企业贷款差异化监管政策，督促经办银行严格审核资金用途，跟踪贷款使用，确保合规有效。人民银行湖南省分行引导银行机构用好用足各项结构性货币政策工具，充分发挥央行低成本资金的牵引撬动作用，加大首贷、信用贷款投放，创新特色金融产品，支持大学生创新创业。省再担保公司、省委金融办严格审核财政补贴资金申请，确保财政资金安全。\n\n（三）严格责任追究\n\n相关部门应加强全过程跟踪管理。发现违规使用贷款或财政补助资金的，须及时追回并依法依规追究贷款主体、经办银行及相关人员责任。贷款主体及经办银行须自觉接受财会监督、审计监督和行业监管。工作人员存在违规违纪行为的，依法追究责任，涉嫌犯罪的，移送司法机关处理。\n\n五"},{"no":"五","title":"其他事项","text":"1、同一笔贷款如已获得省级财政补助资金的，不得重复享受本政策补助。\n\n2、执行中如遇问题，请及时向省财政厅、省委金融办报告。\n\n3、请各有关单位高度重视，认真贯彻执行。\n\n本通知自印发之日起实施，有效期至2027年12月31日。"}],"interpretations":[],"sourceUrl":"https://jyt.hunan.gov.cn/jyt/sjyt/bys/byszcjd/202603/t20260306_33928168.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布时间 2025-11-05","verified":true,"isSample":false,"hunan":true},{"id":"p-2025-85cf55","title":"永州市人民政府关于印发《永州市推动先进制造业高质量发展若干措施》的通知","level":"city","region":"永州市","issuer":"永州市人民政府","documentNo":"永政发〔2025〕2号","publishedAt":"2025-03-10","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业"],"summary":"永州对新认定国家级专精特新\"小巨人\"、国家级制造业单项冠军奖励50万元；省级专精特新中小企业、省级制造业单项冠军奖励20万元；新入统规模以上工业企业奖励不低于5万元。","sections":[{"no":"一","title":"明确工作目标","text":"到2027年，打造区域先进制造业高地取得重大进展。加快打造食品加工、智能家居、现代农业、文化旅游、新能源、数字产业等6个千亿级产业；推动约500家企业扩能升级。力争制造业增加值占地区生产总值比重提高到25%以上，数字经济核心产业增加值占地区生产总值比重提高到10%以上。高新技术制造业增加值占制造业增加值比重达20%以上，规模以上工业企业高端化智能化绿色化改造率达50%以上。\n二"},{"no":"二","title":"优化区域布局","text":"（一）改造提升传统产业。大力推动食品加工、智能家居（家电）等传统产业提质增效、转型升级，着力培育消费品工业\"三品\"标杆企业。绿色食品产业，用活用足用好省农业农村厅、省发展改革委等四部门联合印发的《支持永州蔬菜出口高质量发展的若干政策措施》（湘农联〔2024〕38号），支持永州陆港熙可全球食品保鲜加工中心、永州首衡国际农产品交易中心建设，推进农产品精深加工和综合利用；支持道县、新田、江永、江华等县区依托本地资源优势，重点打造粤港澳大湾区\"菜篮子\"功能区，加快推进传统优势食品产区和地方特色食品产业发展。智能家居（家电）产业，支持新田、蓝山、双牌、东安等县区优化资源培育，大力推进\"以竹代塑\"\"以竹代木\"行动，着力打造农林产品加工产业集聚区。支持冷水滩、新田、江华等县区以智能家居（家电）、绿色板材及配套产业为重点，开展产品展览、供需对接等产业生态活动。〔市工信局、市商务局、市农业农村局、市林业局，各县市区人民政府（含管理区、永州经开区，下同）按职责分工负责，以下各项措施均需各县市区人民政府落实，不再列出〕\n（二）培育壮大新兴产业。抢抓国家\"两重\"\"两新\"重大机遇，加快培育壮大新能源新材料、数字产业等新兴产业。新能源新材料产业，深入推进新能源产业链上下游融合，以资源换产业，引进一批风光绿色装备制造项目，加快双牌天子山、江华湾水源抽水蓄能等绿能重点项目建设。推进道县锂多金属矿采选冶一体化深度开发应用，加快紫金锂业锂矿采选项目、6万吨碳酸锂冶炼项目建设，将道县建成中国重要的锂电新能源产业基地；加快湖南稀土新材料产业园、江华离子型稀土基地、零陵绿色锰系新材料产业园建设，将永州打造成全国重要的独居石综合利用基地、全国领先的锰系新材料产业基地和产品供应中心。数字产业，加快推进5G基础设施建设，布局和建设一批高性能算力中心，大力发展大数据、人工智能、移动互联网、云计算等绿色计算产业。加快新一代信息技术集成创新和融合应用，推动产品高端化、轻量化和全产业链发展，纵深推进\"智赋万企\"行动，打造更多应用场景。〔市工信局、市数据局（行政审批服务局）、市商务局按职责分工负责〕\n三"},{"no":"三","title":"加快技术改造","text":"（三）支持企业设备更新。抢抓政策机遇，引导企业开展工业领域大规模设备更新。每年支持120家左右工业企业开展技术改造和设备更新，到2027年，推动约500家工业企业就地扩能提质增效。对当年在建且通过湖南省制造强省项目库系统入库的设备更新和技术改造项目，总投资达到500万元以上的，择优向工业和信息化部、省工业和信息化厅推荐争取技术改造再贷款和贴息等政策支持；更新设备投资达到100万元及以上的，对项目一年期（含）以上设备购置贷款，由受益财政按贷款本金的1%给予贴息，贴息期限1年。单个项目贴息1次，最高不超过50万元，单个企业每年最多贴息2个项目。（市工信局、市发改委、市财政局按职责分工负责）\n（四）支持企业数智改造。重点打造一批省级及以上标杆示范企业，推动更多企业实现\"智改数转\"互联。到2027年，力争推动\"上云\"企业15000家以上、\"上平台\"企业1200家以上，新增40家以上企业通过国家两化融合管理体系贯标评定。培育一批数字化转型服务商，对开展两化融合、网络安全分类分级等各类数字化转型服务的服务商，当年完成服务企业20家、40家、60家以上的，由受益财政分别给予5万元、10万元、15万元一次性奖励。对当年新增的两化融合管理体系贯标企业、数字化转型贯标企业、\"5G+工业互联网\"标杆工厂、工业互联网平台、省100个标志性新基建项目、省级数字化转型标杆项目、省级人工智能赋能新型工业化典型应用场景，由受益财政奖励20万元/个。对被工业和信息化部当年新认定的卓越级智能工厂的企业，由受益财政奖励50万元/个；对当年新认定的省级智能制造标杆企业、车间，由受益财政分别奖励20万元/个、10万元/个。对成功入选\"湖南省智能制造系统解决方案供应商推荐目录\"的企业，由受益财政奖励10万元/个。〔市工信局、市财政局、市数据局（行政审批服务局）按职责分工负责〕\n（五）支持企业技术创新。持续推进规模以上工业企业创新研发活动全覆盖工作，支持企业开展新技术、新产品、新工艺研发应用。对当年新认定的国家级、省级工业设计中心，由受益财政分别奖励20万元、10万元。鼓励企业争取\"五首\"产品认定（首台套技术装备、首批次新材料、首版次高端软件、首轮次工程流片芯片、首套件基础电子元器件），对当年新认定国家级、省级\"五首\"产品的企业，由受益财政分别奖励50万元、20万元。对被工业和信息化部当年新认定为国家技术创新示范企业的工业企业，由受益财政给予20万元一次性奖励。对当年新认定为国家级、省级中试基地（平台）的工业企业，由受益财政分别给予50万元、10万元一次性奖励。（市工信局、市科技局、市财政局按职责分工负责）\n（六）支持企业低碳转型。聚焦冶金、建材、纺织等重点领域，加快传统产业转型升级，积极稳妥推进工业领域碳减排。鼓励企业开展协同降碳行动，探索减污降碳协同增效有效模式，推动低碳协同示范和数字化绿色化协同转型。围绕重点行业和领域，培育绿色工厂、绿色园区，严控污染排放，加速循环化改造，积极争取创建零碳工业园区、国家级绿色工业园区，力争每年打造1—2家省级绿色园区、创建5家省级以上绿色工厂，对评为国家级、省级绿色工厂的企业，由受益财政分别给予100万元、50万元一次性奖励。加快园区内企业实施系统性清洁生产改造，鼓励工业企业开展自愿性清洁生产审核，对通过省工业和信息化厅自愿性清洁生产审核验收的工业企业，由受益财政给予3万元一次性奖励。（市工信局、市财政局按职责分工负责）\n（七）支持企业品牌提升。推动企业建立新型质量管理体系和品牌培育管理体系，鼓励企业参与标准制定，持续培育制造业质量标杆企业，遴选推荐一批典型案例，提高企业产品质量和品牌价值。对当年新认定的国家级、省级制造业质量标杆企业，由受益财政分别给予50万元、10万元一次性奖励；对当年新认定的湖南省原材料、消费品工业\"三品\"标杆企业，由受益财政给予5万元奖励。（市市场监管局、市工信局、市财政局按职责分工负责）\n（八）支持企业融通发展。落实大中小企业融通创新\"携手行动\"，全力培育单项冠军等优质企业，支持中小微企业走专精特新发展之路。到2027年，培育国家级专精特新\"小巨人\"企业18家以上、省级专精特新中小企业400家以上，国家级制造业单项冠军企业5家以上、省级制造业单项冠军企业20家以上。对当年新认定的国家级专精特新\"小巨人\"企业、国家级制造业单项冠军企业，由市本级财政奖励50万元；对当年新认定的省级专精特新中小企业、省级制造业单项冠军企业一次性奖励20万元，其中中心城区（冷水滩区、零陵区、永州经开区）企业的奖励资金由市、区两级财政各承担50%，其他县（市）企业的奖励资金由受益县（市）财政承担，奖励标准不低于20万元。对当年通过复核的国家级专精特新\"小巨人\"企业，由市本级财政奖励5万元；对当年通过复核的省级专精特新中小企业，由受益县市区财政奖励1万元。持续开展新增规模以上工业企业行动，每年新增规模以上工业企业100家以上，由受益财政安排规模以上工业企业培育专项资金，对当年新入统规模以上工业企业，给予不低于5万元的一次性奖励。（市工信局、市财政局按职责分工负责）\n四"},{"no":"四","title":"强化要素保障","text":"（九）加大政策要素保障。市本级财政每年预算安排3000万元先进制造业专项资金支持新型工业化发展。引导银行机构聚焦小微企业融资需求，合理确定信贷投放节奏，力争中小企业综合融资成本稳中有降。对重点项目、重点企业，在用工、用地、用林、用能、用气上给予重点支持，进一步优化营商环境，依法平等保护企业合法权益。〔市财政局、市工信局、市人社局、市自然资源和规划局、市林业局、市城管局、市数据局（行政审批服务局）、中国人民银行永州市分行按职责分工负责〕\n（十）支持开展表扬激励。对扩能升级效果明显的重点存量工业企业，优先推荐申报\"湖南省民营企业100强\"\"新湖南贡献奖\"\"全国优秀企业家\"\"湖南省优秀企业家\"\"大国工匠\"\"劳动模范\"等国家级、省级先进集体和个人。加大宣传力度，营造尊重和弘扬企业家精神的良好社会氛围。（市委统战部、市发改委、市工信局、市工商联、市总工会按职责分工负责）\n本文件自公布之日起施行，有效期至2027年12月31日。奖励事项涉及同类奖补政策的，按就高标准执行，对已获得上级奖补资金的同一事项，市县财政不重复奖励。我市已有的政策与本政策规定不一致的，以本政策为准。政策执行过程中，若法律法规和上级政策另有规定的，从其规定。年度内发生较大及以上生产安全事故、环境污染事故及其他重大违法违规行为的企业不予享受政策支持。本文件的具体解释工作由市工信局承担。"}],"interpretations":[],"sourceUrl":"https://zt.yzcity.gov.cn/cnyz/szfwj/202503/1846bc5bdb19429e908c66220dee6359.shtml","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2025-a301d3","title":"湘潭市一次性创业补贴和创业经营场所租金补贴办法","level":"city","region":"湘潭市","issuer":"湘潭市人力资源和社会保障局、湘潭市财政局","documentNo":"","publishedAt":"2025-06-04","status":"active","tags":["创业补贴","场地支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"湘潭市首次创办小微企业或个体经营正常运营1年以上并吸纳就业的，一次性创业补贴3000-15000元；大学生创业还可享经营场所租金补贴第一年每月800元、第二年每月600元。","sections":[{"no":"一","title":"一次性创业补贴申报条件及标准","text":"(一)申报条件\n申报一次性创业补贴(含大学生一次性创业补贴),需同时具备以下条件:\n1.在我市范围内首次登记注册的初创企业,登记注册时间在5年以内(以首次营业执照登记的成立日期为准,2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间,以此类推)。\n2.申报一次性创业补贴需正常运营1年以上,吸纳2名以上(含2名)城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费6个月以上且处于正常缴纳状态。其中,申报大学生一次性创业补贴需正常运营1年以上,吸纳1名以上城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态。\n3.符合湘潭市产业发展方向。\n4.近两年在信用中国(湖南湘潭)无行政处罚等违法记录,无知识产权或其他经济、法律纠纷。\n5.申报一次性创业补贴的企业法定代表人需属于就业困难人员或返乡入乡农民工。其中,申报大学生一次性创业补贴的企业法定代表人需属于毕业2年内的普通高校、职业学校、技工院校学生和留学归国人员。法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的,不纳入补贴范围。\n(二)补贴标准\n根据吸纳城乡劳动者就业人数情况,一次性创业补贴标准为3000元至15000元不等。吸纳城乡劳动者就业人数取近6个月缴纳城镇职工社会保险人数,吸纳2人(含2人)就业的补贴3000元,吸纳2人以上就业的每增加1人给予1000元补贴,最高不超过15000元。\n其中,大学生一次性创业补贴标准为10000元、12000元或15000元不等。吸纳城乡劳动者就业人数取近3个月缴纳城镇职工社会保险人数,吸纳1-5人(含5人)就业的,补贴12000元;吸纳5人以上就业的,补贴15000元。对于我市认定的高校类大学生创业孵化基地内的大学生创业主体,正常运营1年以上的,经专家评审认定,可放宽缴纳城镇职工社会保险费条件,补贴10000元。\n已经享受过市财政同一项目补贴的,不能重复享受。\n(三)所需资料\n1.《湘潭市一次性创业补贴(含大学生一次性创业补贴)申请表》(附件1)。\n2.营业执照或其他登记注册证明,法定代表人身份证,公司股权分配证明资料。\n3.法定代表人相关证明材料。返乡入乡农民工需提供湘潭市行政区域范围内户籍地乡镇(街道)人力资源社会保障服务站出具的返乡入乡创业佐证资料;毕业生需提供毕业证;留学归国人员需提供经教育部门认证的佐证资料。\n就业困难人员无需提供佐证资料,由市县人社部门在信息系统中核实。\n4.申报一次性创业补贴需提供近6个月的城镇职工社会保险费缴纳证明。其中,申报大学生一次性创业补贴需提供近3个月的城镇职工社会保险费缴纳证明(对于我市认定的高校类大学生创业孵化基地内的大学生创业主体,可不提供城镇职工社会保险费缴纳证明,但需提供正常经营相关交易证明材料)。\n5.其他佐证资料。\n二"},{"no":"二","title":"第二条","text":"创业经营场所租金补贴申报条件及标准(仅限大学生群体创业)\n(一)申报条件\n申报创业经营场所租金补贴,需同时具备以下条件:\n1.在我市范围内首次登记注册的初创企业,登记注册时间在5年以内(以首次营业执照登记的成立日期为准,2025年申报企业的注册时间为2020年1月1日至2024年12月31日期间,以此类推)。\n2.正常运营1年以上,吸纳1名以上城乡劳动者就业(不含法定代表人),缴纳城镇职工社会保险费3个月以上且处于正常缴纳状态。\n3.符合湘潭市产业发展方向。\n4.近两年在信用中国(湖南湘潭)无行政处罚等违法记录,无知识产权或其他经济、法律纠纷。\n5.法定代表人属于毕业2年内的普通高校、职业学校、技工院校学生和留学归国人员,法定代表人持股比例不低于公司总股份的30%。法定代表人近两年由不符合以上条件的群体变更为符合以上条件的群体的,不纳入补贴范围。\n使用自有房产创业及各创业孵化基地内享受免费入驻的企业,不纳入创业经营场所租金补贴范围。\n(二)补贴标准\n第一年每月800元、第二年每月600元。补贴期限自营业执照成立日期的次月至补贴有效期内,连续计算两年。实际租金低于补贴标准的,按实际租赁合同约定的租金额度给予补贴。同一初创企业最多申请两次、累计不超过2年的经营场所租金补贴。申报企业有多处经营场所的,只能就一处经营场所提出申请。已经享受过市财政同一项目补贴的,不能重复享受。\n(三)所需资料\n1.《湘潭市创业经营场所租金补贴申请表》(附件2).\n2.营业执照或其他登记注册证明,法定代表人身份证,公司股权分配证明资料。\n3.法定代表人属于大学生群体的相关证明材料。毕业生需提供毕业证;留学归国人员需提供经教育部门认证的佐证资料。\n4.近3个月的城镇职工社会保险费缴纳证明。\n5.房产证明(如无房产证则提供商品房销售合同)、租赁合同、缴纳租金的发票和转账记录(注明租赁起止时间段)等。\n6.其他佐证资料。\n三"},{"no":"三","title":"申报流程","text":"(一)自主申报。符合条件的创业主体按工商注册(或登记机关)属地管理原则,向所在的市、县市区人力资源和社会保障局申报。\n(二)考察审核。人社部门受理申请后,在每季度末月进行审核,核定申报企业吸纳就业人数及补贴金额,并做好实地考察工作。\n(三)网上公示。考察审核完成后确定的补贴企业名单,应在同级人力资源和社会保障局官网上进行公示,公示期为5个工作日。公示期间无异议,或者有异议但经调查不成立的,由同级人力资源和社会保障局行文公布。\n(四)资金拨付。受补贴名单公布后,由人社部门汇总补贴对象信息报送至同级财政部门,按照相关规定将补贴资金拨付至申报企业账户,并在\"湖南人社一体化业务管理系统\"内录入补贴信息。\n四"},{"no":"四","title":"补贴终止","text":"出现以下情形之一的,终止享受补贴:\n1.申报审核期间,初创企业实体处于停业状态,或已注销、吊销营业执照的。\n2.经核实有其他不符合补贴发放政策相关条件的。\n五"},{"no":"五","title":"工作要求","text":"(一)加强宣传推荐。市县人社部门要通过网络、报纸、电视、微信等媒体广泛开展政策宣传。各相关单位要积极推荐符合当地产业发展方向,代表先进生产力、生产方式的创新创业带动就业的先进典型。\n(二)严格审核把关。市县人社部门要严格按照文件要求,严格审核、认真把关,确保真实性。财政部门要加强资金监管,充分提高资金使用效率。\n(三)严肃工作纪律。市县人社部门要优化服务,提供便捷申报受理渠道。申报企业或个人应对申报资料的真实性负责。对有违规申报、弄虚作假、骗取套取等行为的申报企业和个人,一经核实,取消申报资格,情节严重的纳入诚信黑名单,不再享受湘潭市政府各类财政支持,并依法依规作出处理和追究相关单位和个人责任。\n六"},{"no":"六","title":"相关说明","text":"(一)\"初创企业\"类型包括小微企业和个体工商户。\n(二)普通高校是指国家教育行政部门批准或备案的实施高等学历教育为主的高等学校,包括全日制大学、独立学院、职业技术学院、高等专科学校。按照湘教通〔2020〕66号文件精神,非全日制研究生享受与全日制研究生同等的创业扶持政策。\n(三)一次性创业补贴(含大学生一次性创业补贴)资金从各级就业补助资金中列支;创业经营场所租金补贴从各级财政配套的就业补助资金中列支。\n(四)其他未尽事宜,由市人力资源和社会保障局、市财政局负责解释。\n(五)本办法自发布之日起施行,有效期不超过3年。"}],"interpretations":[],"sourceUrl":"http://www.xiangtan.gov.cn/jc2021/xtsjczwgk/uploadfiles/202509/2025090516413958809.pdf","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2025-a3f757","title":"娄底市人民政府办公室关于印发《娄底市支持\"三电\"产业高质量发展若干措施》的通知","level":"city","region":"娄底市","issuer":"娄底市人民政府办公室","documentNo":"娄政办发〔2025〕9号","publishedAt":"2025-09-02","status":"active","tags":["场地支持","融资支持"],"audience":["小微企业"],"summary":"娄底支持\"三电\"（电机、变压器、家电）产业发展，建立梯度培育库，优化用地政策，加强金融服务和人才引育配套。","sections":[{"no":"一","title":"发展产业集群","text":"发展产业集群。坚持需求牵引,发挥龙头企业引领带动作用,以硅钢和\"三电\"产业链吸引新能源汽车、智能装备制造、工业机器人等终端应用企业。支持境内外\"三电\"产业链上下游企业和投融资企业通过绿地投资、股权债权投资、实物投资、无形资产投资、收购并购等方式来娄开展合作。(责任单位:市工信局、市商务局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n二"},{"no":"二","title":"梯度培育优质企业","text":"梯度培育优质企业。建立\"三电\"企业梯度培育库,深化服务,分阶段、分目标、分类别实行梯度式培育,推动形成\"三电\"及其配套中小企业协同发展新格局。发展壮大龙头企业,推动龙头企业参与行业标准制定,鼓励多元化与国际化布局,提升龙头企业品牌影响力。培育创新骨干企业,加快培育一批产品层次高、市场影响力大、具备先发优势的标志性创新型骨干企业。培育高成长性中小微企业,持续开展新增规模工业企业行动,深入实施\"科技小巨人\"培育计划,培育一批主营业务突出、竞争力强、成长性好的高水平中小微企业。(责任单位:市工信局、市科技局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n三"},{"no":"三","title":"优化用地政策","text":"优化用地政策。针对\"三电\"产业特点实施差异化供地策略,对快速成长且固定资产投入较少的产业项目,通过灵活设置用地年限降低企业初始投资成本,项目土地出让允许分期缴纳土地价款,自签订合同之日起1年内缴纳完毕,配套建立弹性续期机制。对上下游配套企业,采用\"先租后让、租让结合\"用地模式,优先保障标准化厂房供应。(责任单位:市资规局、市住建局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n四"},{"no":"四","title":"加快项目筹建投产","text":"加快项目筹建投产。强化市、区两级联动,简化建设报批流程,推行并联审批模式,协助企业\"零跑动\"高效办理各类涉企行政审批手续。落实帮办服务制度,跟踪项目开工建设和投产达产全流程,对重大项目实行\"一事一议\"协调,跨部门解决企业诉求,鼓励企业\"拿地即动工\"\"竣工即投产\"。(责任单位:市发改委、市资规局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n五"},{"no":"五","title":"降低企业要素成本","text":"降低企业要素成本。加强电力保障,探索\"光伏+储能+微电网\"集成模式,协调新能源发电企业与年用电量超500万千瓦时的\"三电\"企业,建立能源应急保障机制,优先保障重点项目稳定用电。加强气源保障,积极对接上游企业,多渠道筹措气源,推进LNG(液化天然气)储备站建设,加快市政燃气基础设施建设,提高应急调峰和燃气输配能力。加强环保要素保障,建设集中式污水处理、危废处理中心及公共检测实验室,对重大\"三电\"项目优先统筹使用市域内污染物排放总量指标,精准调剂主要污染物总量指标。优化物流网络,加快涟水复航、洛湛铁路益娄段电气化改造工程等重大项目建设,打造\"制造业物流枢纽\"。(责任单位:市发改委、市生态环境局、市住建局、市交通运输局、国网娄底供电公司、相关燃气公司,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n六"},{"no":"六","title":"支持科技创新","text":"支持科技创新。鼓励企业加大研发投入,支持企业用数智技术、绿色技术改造提升传统产业,推动企业设备更新、工艺升级及管理创新,支持租赁关键设备和生产线,实施\"技术攻关+产业化应用\"重大科技示范工程,加强知识产权创造、运用、保护、管理和服务。引导\"三电\"企业接入工业互联网平台,推荐数字化转型、智能化改造项目申报国家级、省级智能制造试点。支持各高校和科研所与企业共建高水平科技成果转化平台,促进科技成果就近就地转化应用。鼓励市级科研补贴(补助)资金向\"三电\"企业倾斜,鼓励市级创业基金推动\"三电\"科技成果转化落地,助力\"三电\"企业高端化、智能化、绿色化。(责任单位:市科技局、市发改委、市财政局、市工信局、市市场监管局、市创发集团,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n七"},{"no":"七","title":"建立供应链协同机制","text":"建立供应链协同机制。针对\"三电\"产业对特种钢材、铜铝等原材料的高度依赖,协调建立跨区域原材料储备联盟。通过大宗物资集采、战略储备等方式平抑价格波动,稳定供应链成本,建立原材料供需预警机制,提前做好产能调配和应急储备。建立\"三电\"供需对接平台,定期组织上下游企业开展采购洽谈会,推动供应链上下游企业实现协同采购、协同制造、协同物流,促进大中小企业专业化分工协作,快速响应客户需求,缩短生产周期和新品上市时间,降低生产经营和交易成本。(责任单位:市工信局、市发改委、市市场监管局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n八"},{"no":"八","title":"创新金融服务","text":"创新金融服务。加强政银企对接,定期开展\"行长走市县·金融送解忧\"行动,适时组织\"三电\"产业融资对接会;完善\"金融超市\"平台功能,创新优化金融服务产品,积极为\"三电\"产业链上下游企业提供差异化融资支持。引导金融机构持续开发\"三电贷\"\"三电担\"等专属产品,探索应收账款融资、预付款融资、库存融资、订单融资等供应链融资模式,完善信贷审批流程,缩短贷款审批时限。加快推进设立创投子基金,引导娄底\"材料谷\"产业基金等投资\"三电\"企业。充分发挥商业保理、融资租赁等金融牌照作用,为\"三电\"企业提供银票、商票质押融资和订单保理融资等供应链金融服务。(责任单位:市政府办、市财政局、市国资委、中国人民银行娄底市分行、国家金融监督管理总局娄底监管分局、市城发集团,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n九"},{"no":"九","title":"强化人才引育配套","text":"强化人才引育配套。聚焦人才队伍梯次化、能力全面化、使用实战化,完善构建\"引育用\"全链条机制。支持企业柔性引进各类人才,鼓励有条件的企业与高校等共建高技能、跨学科复合型人才培训基地。实施\"技能人才定向培养计划\",鼓励\"三电\"企业与高职院校合作开设\"钢铁冶金\"\"电力电子\"等专业订单班,由企业参与课程设计,毕业生直接输送至重点企业。建设园区人才公寓,按照需求提供阶梯式住房保障,对重点引进的高层次人才,提供购房补贴配套服务。建立\"人才服务一卡通\"制度,整合医疗、教育、交通等优质资源,提升人才归属感。(责任单位:市委组织部、市科技局、市人社局、市教育局、市财政局、市工信局,娄星区人民政府、娄底经开区管委会、娄星产业发展中心)\n十"},{"no":"十","title":"强化政企沟通与执法监督","text":"强化政企沟通与执法监督。为\"三电\"产业相关企业配备营商环境联企服务专员,纳入营商环境监测。各级营商环境部门、司法行政部门发现破坏营商环境的问题线索,经交办、督办,内部纠偏效果不好的,依法依规依纪移送纪检监察机关核查处理。(责任单位:市纪委监委、市营商环境办、市司法局、各行政执法部门)\n十"},{"no":"十一","title":"建立推动落实工作机制","text":"建立推动落实工作机制。市\"三电\"产业工作专班定期调度工作进展情况,对相关责任单位政策落实情况进行调研,跟踪评估政策实施效果。相关部门严格按照职责分工,推进政策落实落地。(责任单位:市工信局,娄星区人民政府、娄底经开区管委会)\n本政策适用对象为入驻娄星区、娄底经开区(含娄星产业园)的\"三电\"终端成品或主要零配件生产企业。其他县(市)可以参照执行。本政策自公布之日起施行,有效期5年。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202509/t20250924_33813505.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2025-ab4238","title":"益阳市人民政府办公室关于印发《益阳市支持大学生创业十二条措施》的通知","level":"city","region":"益阳市","issuer":"益阳市人民政府办公室","documentNo":"益政办发〔2025〕10号","publishedAt":"2025-07-30","status":"active","tags":["创业补贴","贷款贴息","场地支持"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"为大学生创业提供个人最高30万元、合伙创业或小微企业最高400万元的创业担保贷款并按实际利率给予50%贴息，对首次创办小微企业或从事个体经济且正常运营1年以上的在校大学生或离校2年内高校毕业生最高给予1万元一次性创业补贴，自2025年8月1日起施行，有效期至2029年7月31日。","sections":[{"no":"一","title":"帮扶创业主体，完善政策支持","text":"帮扶创业主体，完善政策支持\n（一）提供创业担保贷款贴息及专属信贷支持。为大学生创业提供贷款支持，个人创业最高可贷30万元，合伙创业或小微企业最高可贷400万元，财政部门按实际利率给予50%贴息。同时推出支持青年创业者、青年领办企业及新市民的专属信贷产品，建立“白名单”推送机制。（责任单位：市人力资源社会保障局、市财政局、团市委、人民银行益阳市分行、益阳金融监管分局按职责分工负责）\n\n（二）给予一次性创业补贴支持。对首次创办小微企业或从事个体经济，且所创办企业或个体工商户自工商登记注册之日起正常运营1年以上的在校大学生或离校2年内高校毕业生，根据实际投入、带动就业人数，最高给予1万元的一次性创业补贴。（责任单位：市人力资源社会保障局、市财政局按职责分工负责）\n\n（三）支持创建大学生创业孵化载体。开展大学生创业孵化基地认定工作，对首次认定的益阳市市级大学生创业孵化基地，给予5万元/家的一次性培育奖补，对已认定的益阳市市级大学生创业孵化基地，参照《关于深入推进创业孵化基地建设工作的通知》（湘人社规〔2023〕5号），根据创业孵化成效给予每年最高不超过40万元的创业服务补助。（责任单位：市人力资源社会保障局、市财政局、市科技局、市教育局按职责分工负责）\n\n（四）给予减税降费支持。高校毕业生在毕业年度内从事个体经营，符合规定条件的，在3年内按一定限额依次扣减其当年实际应缴纳的增值税、城市维护建设税、教育费附加、地方教育附加和个人所得税；对销售额在免税标准以下的小规模纳税人免征阶段性增值税，对小微企业和个体工商户按规定减免所得税。对国家级、省级科技企业孵化器和大学科技园以及国家备案众创空间按规定免征增值税、房产税、城镇土地使用税。（责任单位：市税务局）\n\n（五）加大人才政策倾斜。将市大学生创业典型纳入市级人才计划。在益阳市银城青年人才项目创业类中，针对大学生创业者开设单独赛道，按程序将市大学生创业典型纳入市级人才计划名单，享受相应人才政策。（责任单位：市委组织部、团市委按职责分工负责）\n\n二"},{"no":"二","title":"深化创业培训，增强创业能力","text":"深化创业培训，增强创业能力\n（六）加强创业导师队伍建设与指导服务。重点打造一支由10名核心实战型导师和120名专业导师组成的市级创业导师团队，构建覆盖高等教育、企业管理、法律咨询、金融财务等多领域的综合性导师体系，实现创新创业导师资源的共建共享。结合“益起来创业”系列创业服务活动，组织开展导师进基地、进校园活动，为大学生创业项目提供专业化、多元化、精细化的创业指导；并对有需要、有潜力的创业项目，安排创业导师开展结对帮扶。（责任单位：市科技局、市教育局、市人力资源社会保障局、团市委按职责分工负责）\n\n（七）开展创业课程定制培训。完善创业培训课程体系，针对不同创业阶段、创业类型、创业需求的大学生，提供定制化GYB、SYB、IYB、网络创业、创业模拟实训等课程培训，按规定给予创业培训补贴，提升大学生创业能力。（责任单位：市人力资源社会保障局、市教育局按职责分工负责）\n\n（八）支持大学生在涉农领域创业就业。市农村产权交易中心设立专项服务窗口，为大学生创业提供土地流转、技术指导等政策咨询服务。组织有返乡下乡创业意向大学生参与高素质农民培训，将返乡创业大学生纳入产业发展带头人重点培育对象，开展农村创业项目专题培训。（责任单位：市农业农村局）\n\n三"},{"no":"三","title":"拓展孵化空间，助力创业成长","text":"拓展孵化空间，助力创业成长\n（九）给予大学生创业场地支持服务。大学生创业孵化基地免费提供不低于孵化面积30%的场地给大学生和毕业5年内（含）高校毕业生创业项目，并给予入驻项目场地租金首年全额补贴，次年补贴50%。支持优秀大学生落户中南科创园、龙山港、华盛创业园以及监管企业管理的商铺创业，为其提供必要的管理服务，并予以一定的租金优惠。（责任单位：市人力资源社会保障局、市财政局、市科技局、市教育局、市国资委、益阳高新区管委会按职责分工负责）\n\n（十）给予大学生创业者保障性租赁住房优惠。面向符合条件的大学生创业者供应保障性租赁住房，面积扩大到120平方米以内，租金不高于同地段同品质市场租赁住房租金的80%，实行动态管理。（责任单位：市住房城乡建设局）\n\n（十一）设立市、县两级“大学生创业一站式服务中心”，推行“零打扰”监管和“零跑腿”审批服务模式。推行“不上一次门”制度，对新设立且无投诉举报、无安全隐患的大学生创业企业，实行“首年免检”政策，并实施“轻微免罚”“首违不罚”等柔性执法措施。推进“高效办成一件事”改革，确保“个人创业一件事”落地实施，实现全流程办理。为大学生创业企业提供最大程度的“无事不扰”和“有需必应”的服务环境。（责任单位：市发展改革委、市科技局、市人力资源社会保障局、市市场监管局、团市委、市税务局，各县市区人民政府按职责分工负责）\n\n四"},{"no":"四","title":"弘扬创业精神，营造社会氛围","text":"弘扬创业精神，营造社会氛围\n（十二）打造“‘益’起创青春”宣传品牌，构建全方位创新创业生态。举办“青年夜校·创新创业专场”“益阳市青年创新创业大讲堂”“‘益’起创青春 携手向未来”益阳政企青年解难题促发展主题沙龙等活动，搭建政企对话平台，弘扬新时代创新创业精神，持续激发高校学子创新潜能。同步构建媒体宣传矩阵，开设《正青春 好创业》政策解读专栏和《青春“益”起创》典型宣传栏目，形成“活动赋能+媒体发声”的全方位宣介创业工作，立体化展示青年创业典型，多维度推广基层创新经验，在全社会营造尊重创业、支持创新的良好氛围。（责任单位：市委宣传部、团市委、益阳日报社、市广播电视台按职责分工负责）\n\n大学生创业主体须依法经营并履行社会责任，在享受同类政策时，遵循“奖补不重复”原则。本文件自2025年8月1日起施行，有效期至2029年7月31日。在文件有效期内，如遇法律法规或有关政策调整变化的，从其规定。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202509/t20250924_33813484.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2025-09-24","verified":true,"isSample":false,"hunan":true},{"id":"p-2025-c63084","title":"关于促进专精特新中小企业高质量发展的若干措施","level":"city","region":"长沙市","issuer":"长沙市人民政府办公室","documentNo":"长政办发〔2025〕3号","publishedAt":"2025-02-28","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业"],"summary":"长沙首次认定的专精特新\"小巨人\"企业每家一次性奖励50万元；重点项目每家每年最高补助30万元；数字化改造最高补助30万元。","sections":[{"no":"一","title":"建立梯度培育体系","text":"建立梯度培育体系。构建\"专精特新中小企业—专精特新'小巨人'后备企业—专精特新'小巨人'企业\"的梯度培育体系。围绕重点产业集群和产业链，梳理出一批创新能力强、赛道前景好、市场竞争优势显著的优质中小企业，分层动态建立企业培育体系，实施精准培育。推动科技型中小企业培育为高新技术企业，加快实现升规纳统。对首次认定的专精特新\"小巨人\"企业，每家给予一次性50万元奖励。（责任单位：市工业和信息化局、各区县市人民政府、园区管委会）\n二"},{"no":"二","title":"精准支持科技创新","text":"精准支持科技创新。支持专精特新中小企业自筹建设或者与高校院所、医疗机构等联合共建技术创新中心。支持认定为高新技术企业的专精特新中小企业与国家级创新平台及高校院所组建新型研发机构。支持专精特新中小企业开展行业关键技术攻关和关键产品研发，鼓励企业牵头组建创新联合体，承担市级科技重大专项以及\"揭榜挂帅\"项目。鼓励专精特新中小企业依托长沙市科技创新综合信息平台发布技术需求清单；组织高校院所与专精特新中小企业开展产学研合作对接，支持专精特新中小企业主动吸纳承接高校院所科技成果，鼓励开展技术转让、技术开发、技术许可。指导支持专精特新中小企业开展标准创新型企业培育评价，对参与制定国际、国家和市级地方标准的企业，按规定给予一次性奖励。为企业开展质量诊断服务，指导专精特新中小企业导入先进质量管理模式，支持企业积极争创政府质量奖。（责任单位：市科技局、市工业和信息化局、市市场监管局）\n三"},{"no":"三","title":"强化知识产权保护","text":"强化知识产权保护。将更多专精特新中小企业列入知识产权优势企业培育对象。依托国家专利导航综合服务平台，推进专精特新中小企业深度参与高校院所存量专利盘活工作。对符合条件的专精特新中小企业提供快速预审、快速确权和快速维权的知识产权综合服务。引导专业机构加强专精特新中小企业知识产权培训。（责任单位：市知识产权局）\n四"},{"no":"四","title":"支持重点项目建设","text":"支持重点项目建设。支持专精特新\"小巨人\"后备企业深耕专业细分赛道，提升创新能力和竞争力；重点围绕打造新动能、攻坚新技术、开发新产品和强化产业链配套能力，依规定每年遴选一批重点项目，结合企业主营业务、研发创新、知识产权、数字化水平等综合指标，按照每家企业每年最高不超过30万元的标准给予补助。建立专精特新中小企业项目建设储备机制，实施动态管理，加强综合服务，积极支持符合要求的企业申报中央、省级资金项目。（责任单位：市工业和信息化局、市财政局）\n五"},{"no":"五","title":"强化融资支持","text":"强化融资支持。发挥长沙市小微企业信贷风险补偿基金、长沙市中小企业转贷引导基金作用，推动银行业金融机构面向专精特新中小企业开发特色产品，提供应急转贷资金支持。强化供应链金融服务，探索搭建综合服务平台。建设政府引导基金与专精特新中小企业投资对接机制。依规定遴选符合条件的专精特新重点企业列入上市培育对象；做实北京证券交易所、全国股转系统长沙服务基地，健全战略合作机制，提升服务质效。聚焦重点产业链专精特新中小企业融资需求，开展投融资路演活动。（责任单位：市工业和信息化局、市委金融办、市财政局）\n六"},{"no":"六","title":"强化人才服务","text":"强化人才服务。实施专精特新中小企业就业创业扬帆计划，将专精特新中小企业纳入重点企业用工保障范围。建设市域产教联合体，加强校企对接，开展专场招聘活动。探索推动具备条件的专精特新中小企业开展高级职称自主评定，赋予专精特新\"小巨人\"企业高层次人才举荐权。在企业员工职称评定中，不将论文作为硬性要求，支持将新产品研发等工作绩效作为评价的重要参考，对高端人才探索以业绩陈述代替论文答辩。大力支持专精特新中小企业吸引集聚高端人才，推荐符合条件的企业和人才申报市级\"两大重点人才工程\"、省级\"芙蓉计划\"、国家重点人才计划等人才项目，办理高层次人才分类认定，在人才落户、住房、子女教育和\"长沙市卓越工程师\"等享受政府津贴专家选拔中予以支持。加大人才平台建设力度。支持符合条件的专精特新\"小巨人\"企业建设院士工作站、专家工作站，分别给予每家企业100万元、60万元经费支持。支持符合条件的专精特新\"小巨人\"企业建设博士后科研工作站、博士后创新创业实践基地，分别给予每家企业100万元、60万元经费支持。专项支持专精特新中小企业举办符合长沙产业发展方向和人才需求的学术会议、专业论坛。（责任单位：市委人才办、市教育局、市科技局、市人力资源社会保障局、市科协）\n七"},{"no":"七","title":"支持市场开拓","text":"支持市场开拓。促进大中小企业融通创新，分行业梳理专精特新中小企业产业链分布和协作清单，以集群和产业链为单位，精准推动专精特新中小企业与大企业开展市场、技术、人才对接。推动省、市国有企业开放创新资源和应用场景，与专精特新中小企业加强供需对接。对接国家中小企业国际合作协会、市级\"走出去\"联盟、公共信息服务平台等服务资源，组织开展专项培训，推动重点行业专精特新中小企业抱团\"出海\"、链式\"出海\"。支持专精特新中小企业参加境外展会，利用海外知名搜索引擎、社交媒体、电商平台开展线上推广营销，开展管理体系认证、境外产品认证、境外专利申请和境外商标注册，按规定给予资金支持。（责任单位：市工业和信息化局、市商务局）\n八"},{"no":"八","title":"推进数字化发展","text":"推进数字化发展。深入推进智赋万企行动，支持中小企业上云、上平台。推进中小企业数字化转型城市试点工作。分行业推进中小企业数字化改造，对纳入试点的中小企业开展数字化改造给予补贴，按照每家企业不高于数字化改造采购总额30%的比例给予补助，其中每家企业补助金额最高不超过30万元。在使用中央财政资金按上述标准给予补助的基础上，市级财政根据实际情况给予配套支持，每家企业补助金额最高不超过30万元。打造一批数字化转型标杆，建设中小企业数字化转型公共服务平台，引导服务商研发推广\"小快轻准\"数字化产品和解决方案。支持专精特新中小企业建设智能制造工厂、打造应用场景。（责任单位：市工业和信息化局）\n九"},{"no":"九","title":"促进绿色化发展","text":"促进绿色化发展。支持专精特新中小企业开展节能诊断、节能技术改造和建设工业绿色微电网。优先支持专精特新中小企业建设绿色工厂，创建绿色供应链管理企业。鼓励专精特新中小企业节约集约用地，在符合国土空间规划、不改变用途和保障安全的前提下，对专精特新中小企业通过厂房加层、厂区改造、内部用地整理等方式提高工业用地（不含工业地产）利用率和容积率的，不再增收土地价款。（责任单位：市发展改革委、市工业和信息化局、市自然资源规划局）\n十"},{"no":"十","title":"优化企业服务","text":"优化企业服务。落实专精特新中小企业分层培育政策和服务措施，集成服务资源，提供精准服务。建立专精特新中小企业政府服务专员制度。链接全国中小企业服务一张网，建立线上线下一体化中小企业服务平台，开设专精特新中小企业服务专区，建立政策推送直达系统，完善困难问题帮扶分办系统。依托平台功能征集企业需求，开展融资服务、优才招聘、知识产权、企业管理、市场开拓等服务活动，对服务成效突出的企业服务机构按照每家机构最高不超过20万元的标准给予补助。（责任单位：市工业和信息化局、各区县市人民政府、园区管委会）\n本文件自2025年3月1日起施行，有效期3年，由市工业和信息化局负责具体解释工作。"}],"interpretations":[],"sourceUrl":"http://www.changsha.gov.cn/zfxxgk/zfwjk/szfbgt/202502/t20250228_11761924.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2025-ed049d","title":"关于开展一次性创业补贴申报工作的通知","level":"city","region":"株洲市","issuer":"株洲市人力资源和社会保障局","documentNo":"株人社发〔2025〕8号","publishedAt":"2025-07-23","status":"active","tags":["创业补贴","就业补贴"],"audience":["小微企业","个体工商户","高校毕业生"],"summary":"株洲首次创办企业或个体工商户正常经营1年以上的重点群体，个体工商户补1万元、企业补2万元；大学生创业个体补2万元、企业补3万元。","sections":[{"no":"一","title":"申报条件","text":"（一）申报株洲市一次性创业补贴，需同时满足以下条件：\n1.在株洲市行政区域内首次登记注册的创业企业或个体工商户，登记注册时间在5年以内（以首次营业执照登记的成立日期为准，例如申报2025年度一次性创业补贴的，工商注册时间应在2020年1月1日至2024年12月31日之间），且有固定经营场所。\n2.创业项目符合国家产业发展方向，信用状况良好，无拖欠职工工资、欠缴社会保险费等违法违规信用记录。\n3.个体工商户经营者、企业法定代表人属于下列重点就业群体：返乡入乡农民工；大学生（在校及毕业两年内，含普通高校、职业学校、技工院校和留学归国人员）；就业困难人员。\n4.正常经营1年以上，且个体工商户经营者需带动2名以上劳动者就业，企业需带动5名以上劳动者就业，企业要求缴纳半年以上企业职工养老保险且处于正常缴纳状态。属于大学生创业企业的，带动劳动者就业可以放宽至3名以上，在校生可暂缓缴纳养老保险，当年毕业的大学生按在校生类别申报。\n（二）已申请过人社部门创业补贴的，不得重复申报。\n二"},{"no":"二","title":"补贴标准","text":"（一）个体工商户按10000元/户的标准给予补贴，企业按20000元/户的标准给予补贴。\n（二）属于大学生创业的，个体工商户按20000元/户标准给予补贴、企业按30000元/户标准给予补贴。\n三"},{"no":"三","title":"申报资料","text":"（一）补贴申请表\n《 年度株洲市一次性创业补贴申报表》（附件1）。\n《 年度株洲市在校生一次性创业补贴申报表》（附件2）。\n（二）申报对象基本信息资料\n包含个体工商户经营者或企业法人身份证复印件、营业执照、企业银行开户账号（个体工商户提供银行卡复印件）或其他登记注册证明复印件。\n（三）正常经营一年以上佐证资料\n包含经营场所房产证或租赁合同复印件、职工花名册、劳动合同复印件、经营流水、工资发放证明、企业公司简介、财务报表、员工参加企业职工基本养老保险证明。\n（四）信用佐证资料\n提供信用中国（湖南株洲）或国家企业信用信息公示系统无违法记录证明材料。\n（五）首次创业佐证资料\n提供国家市场监管系统市场主体投资任职情况查询材料。\n（六）申报对象就业重点群体佐证材料\n1.返乡入乡农民工提供户口本或农村土地承包经营权证复印件，以及以下任意一项转移就业经历证明：与原单位签订的劳动合同、返乡前缴纳的社会保险证明、户籍地乡镇（街道）公共服务办公室出具的返乡创业佐证资料等。\n2.普通高校、职业学校、技工院校和留学归国人员提供毕业证复印件或经教育部留学服务中心认证的国外学历学位认证书。在校生提供经学校创业就业指导部门审核的创业计划书、学生证复印件或学校出具的在校生身份证明。\n3.就业困难人员指按照《湖南省就业援助实施办法》进行身份认定，并在人社一体化平台中进行实名登记、动态管理的人员，包括：男满50周岁、女满40周岁人员；城镇零就业家庭人员；享受城市居民最低生活保障人员；残疾人员；失地农民；军队退役人员；市州级以上劳动模范；烈士家属；抚养未成年子女的单亲家庭成员；连续失业1年以上的其他登记失业人员。就业困难人员无需提交身份佐证材料，由人社部门在人社一体化平台信息系统中核实。\n四"},{"no":"四","title":"申报流程","text":"（一）公开申报\n市人社局在官网（http://rsj.zhuzhou.gov.cn）公布政策文件。申报对象向工商注册地所在县市区人社局申报（在校生向所在学校申报），申报资料一式两份，统一用A4纸打印，按资料清单顺序装订成册。\n（二）组织初审\n县市区人社局负责受理辖区内申报对象的申报资料并组织初审（学校受理在校生的申报资料审批后报县市区人社局初审）。初审工作人员通过资料审核、实地走访等方式，核实各类证明、证件原件和资料复印件的真实性，核定申报对象经营情况、带动就业情况、补贴标准。初审完成后，由初审单位在申报表、汇总表签署意见并加盖公章。\n（三）汇总复核\n县市区人社局初审完成后，填报《株洲市一次性创业补贴汇总表》（附件3），自留一份，交市人社局一份。市人社局对申报资料的真实性、准确性进行复核，确定拟补贴对象及补贴金额。\n（四）官网公示\n复核通过后，市人社局将拟发放补贴名单在官网公示5个工作日。\n（五）资金拨付\n公示无异议后，由人社部门汇总补贴对象信息报送至同级财政部门，依据相关规定拨付补贴资金，并在\"湖南人社一体化业务管理系统\"内录入补贴信息。\n五"},{"no":"五","title":"工作要求","text":"（一）加强政策宣传。各相关单位要充分利用网络、报纸、电视等媒体，多渠道、多形式宣传补贴政策，提高政策知晓度，扩大政策覆盖面，鼓励和支持更多有意愿、有能力的群体通过创业带动就业。\n（二）严格审核把关。各县市区人力资源和社会保障局、相关单位要严格按照文件要求，严谨审核，认真把关，确保申报资料的真实性。\n（三）严肃工作纪律。工作人员不得假公济私、以权谋私、索拿卡要、刁难企业和个人，收受企业和个人财物。申报企业和个人应对资料的真实性负责。对在申报过程中弄虚作假的申报企业和个人，一经核实，追回补贴资金、取消申报资格，依法纳入社会信用体系，不得再享受我市人社部门各类创业扶持政策。\n六"},{"no":"六","title":"其他事项","text":"（一）当年度一次性创业补贴申报期截止至当年10月31日。\n（二）本通知自下发之日起实施，有效期5年。有效期内上级出台新规定与本通知不一致的，以上级新规定为准。\n（三）其他未尽事宜，由市人力资源和社会保障局负责解释。\n株洲市人力资源和社会保障局\n2025年7月23日"}],"interpretations":[],"sourceUrl":"https://rsj.zhuzhou.gov.cn/c923/20250723/i2399858.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2026-41937b","title":"常德市人力资源和社会保障局关于延续实施扩大社会保险补贴范围政策的公告","level":"city","region":"常德市","issuer":"常德市人力资源和社会保障局","documentNo":"","publishedAt":"2026-09-02","status":"active","tags":["社保补贴"],"audience":["小微企业","高校毕业生"],"summary":"制造业、生活服务业、现代服务业领域的中小微企业吸纳重点群体就业并在2026年按规定缴纳三项社会保险费的，按照个人实际缴费额的25%给予社会保险补贴，每人累计享受补贴期限不超过12个月，申请期限截至2026年12月31日。","sections":[{"no":"一","title":"为进一步激励企业扩岗吸纳就业，助力重点群","text":"为进一步激励企业扩岗吸纳就业，助力重点群体稳定就业，根据有关文件规定，我市2026年延续实施扩大社会保险补贴范围政策。\n\n1.补贴对象\n\n重点行业领域的中小微企业吸纳重点群体就业，并在2026年按规定为其新缴纳或继续缴纳企业职工基本养老保险费、基本医疗保险费、失业保险费的，按照个人实际缴费额的25%给予社会保险补贴。重点行业领域包括：制造业、生活服务业、现代服务业，具体行业按照国家统计局的行业划分确定。重点群体包括：2026届高校毕业生、2024届和2025届离校未就业高校毕业生，登记失业半年以上人员和防止返贫致贫对象。对于符合《湖南省人力资源和社会保障厅湖南省财政厅关于落实扩大社会保险补贴范围政策有关工作的通知》（湘人社函〔2025〕84号）等文件规定条件，但在2025年未及时申领补贴的人员，可于2026年继续提出申请。\n\n2.申领期限\n\n补贴采用“先缴后补”的方式，可由企业或劳动者向社保参保地或企业所在地的公共就业服务机构提出申请。每人累计享受补贴期限不超过12个月，申请期限截至2026年12月31日。\n\n3.申报流程\n\n个人申报流程\n\n1.智慧人社或电子社保卡扫码登录湖南人社公共服务网上服务大厅（网址：https://ggfw.rst.hunan.gov.cn）。\n\n2.点击公共就业菜单。\n\n3.点击扩围社会保险补贴申请——申请。\n\n4.系统会自动生成身份证、社保卡信息，无社保卡的可以自录银行（填写好申报人的银行信息），申请人填写姓名、联系电话、人员类别（选择符合条件的人员类别）等信息后上传毕业证、身份证正反面、劳动合同后提交申请。\n\n企业申报流程\n\n1.登录界面（https://ggfw.rst.hunan.gov.cn/neaf-ui/#/login）\n\n企业专员使用电子社保卡登录。\n\n2.点击“公共就业”“企业吸纳人员管理”模块进行人员资料完善。\n\n3.填写信息，上传相关资料（仅高校毕业生需要毕业证）后点击保存。\n\n4.点击人员列表后的图标\n\n提交完成。\n\n4.政策咨询电话\n\n市本级7817805\n\n武陵区7230570\n\n鼎城区7375220\n\n西湖管理区2821992\n\n西洞庭管理区7509109\n\n汉寿县2337008\n\n桃源县6612138\n\n临澧县5891049\n\n澧县3127631\n\n石门县5165977\n\n津市市4237358\n\n安乡县4338528"}],"interpretations":[],"sourceUrl":"https://mohrss.changde.gov.cn/zhdt/gggs/content_78217097","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2026-09-02","verified":true,"isSample":false,"hunan":true},{"id":"p-2026-63153b","title":"优质中小企业梯度培育管理办法","level":"national","region":"全国","issuer":"工业和信息化部","documentNo":"","publishedAt":"2026-06-15","status":"active","tags":["认定资质","研发创新"],"audience":["小微企业"],"summary":"优质中小企业分科技和创新型中小企业、专精特新中小企业、专精特新\"小巨人\"企业三个梯度培育，认定后有效期3年，到期复核通过可延长。","sections":[{"no":"一","title":"第一条","text":"为加强和规范优质中小企业培育管理，促进中小企业专精特新发展，支撑推进新型工业化、发展新质生产力、建设现代化产业体系，根据党中央、国务院有关决策部署，制定本办法。"},{"no":"二","title":"第二条","text":"优质中小企业是指在产品、技术、工艺、管理、模式等方面创新能力强、专注细分市场、成长性好的中小企业，包括科技和创新型中小企业、专精特新中小企业、专精特新\"小巨人\"企业。科技和创新型中小企业具有较高专业化水平、较强研发创新能力和发展潜力，是优质中小企业的基础力量；专精特新中小企业实现专业化、精细化、特色化发展，创新能力强、质量效益好，是优质中小企业的骨干力量；专精特新\"小巨人\"企业位于产业基础核心领域、产业链关键环节，创新能力突出、掌握核心技术、细分市场占有率高、质量效益优，是优质中小企业的中坚力量。"},{"no":"三","title":"第三条","text":"优质中小企业梯度培育工作，坚持落实\"两个毫不动摇\"，坚持有效市场和有为政府相结合，坚持专精特新发展方向，坚持分层分类分级指导，坚持动态管理和精准服务。"},{"no":"四","title":"第四条","text":"工业和信息化部负责优质中小企业梯度培育工作的宏观指导、统筹协调和监督检查，推动出台相关支持政策，发布相关认定标准，负责专精特新\"小巨人\"企业认定工作。各省、自治区、直辖市及计划单列市、新疆生产建设兵团中小企业主管部门（以下统称省级中小企业主管部门）负责本地区优质中小企业培育和专精特新中小企业认定工作。\n其他机构未经授权不得开展与科技和创新型中小企业、专精特新中小企业、专精特新\"小巨人\"企业有关的认定、授牌等活动。"},{"no":"五","title":"第五条","text":"工业和信息化部建设优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下简称培育平台），搭建优质中小企业数据库。各级中小企业主管部门应通过培育平台组织开展认定工作，加强服务对接和监测分析，跟踪企业运行、发展态势、意见诉求，以及扶持政策与培育成效，有针对性地制定政策和开展精准服务。落实数字政府建设要求，推动数据互通共享，减轻企业数据填报负担。\n第二章 认定程序和认定标准"},{"no":"六","title":"第六条","text":"省级以上中小企业主管部门按照谁推荐、谁把关，谁审核、谁管理方式组织开展优质中小企业认定工作。"},{"no":"七","title":"第七条","text":"专精特新中小企业认定，由科技和创新型中小企业按属地原则自愿申报，省级中小企业主管部门根据专精特新中小企业认定标准（见附件1），组织对企业申请材料和相关佐证材料进行审核、实地核查和公示。公示通过的，由省级中小企业主管部门认定为专精特新中小企业。"},{"no":"八","title":"第八条","text":"专精特新\"小巨人\"企业认定，由专精特新中小企业按属地原则自愿申报，省级中小企业主管部门根据专精特新\"小巨人\"企业认定标准（见附件2），组织对企业申请材料和相关佐证材料进行初审、实地核查和公示。公示通过的，向工业和信息化部推荐。工业和信息化部组织对被推荐企业进行审核、抽查和认定。原则上每年第二季度组织开展专精特新\"小巨人\"企业认定工作。"},{"no":"九","title":"第九条","text":"各级中小企业主管部门应建立健全优质中小企业主动发现机制，充分挖掘产业链供应链、股权投资、知识产权、科技奖项、人才引育等数据，常态化发现潜在优质中小企业，定向邀请其参加认定。认定标准不降低。"},{"no":"十","title":"第十条","text":"在专精特新中小企业认定和专精特新\"小巨人\"企业推荐工作中，省级中小企业主管部门应健全审核机制、规范全过程管理，组织专家严格对照认定标准，重点对企业申请材料和数据的真实性、准确性、完整性，以及是否符合认定标准等情况进行审核。应采取\"双随机\"（随机抽取专家组成多个评审专家组、即时随机派发审核任务）形式开展审核，评审专家组应包含一定数量的产业专家和财务专家。"},{"no":"十一","title":"第十一条","text":"申报企业应在中华人民共和国境内依法设立，符合《中小企业划型标准规定》，遵守国家法律法规和行业规范。申报期间未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定。应自主、如实申报，按要求填写申请表格并提供必要佐证材料。"},{"no":"十二","title":"第十二条","text":"各级中小企业主管部门及其相关支撑单位应加强宣传培训，指导企业做好申报工作，不得以任何名义直接或变相向申报企业收取费用。"},{"no":"十三","title":"第十三条","text":"各级中小企业主管部门不得将审核认定相关工作委托第三方中介机构承担，应联合相关部门严格防范不良中介机构影响。\n第三章 动态管理"},{"no":"十四","title":"第十四条","text":"省级及以上中小企业主管部门应会同相关部门强化对优质中小企业的运行监测，挖掘利用好金融、信用、司法等各类数据信息，建立健全有进有出的动态管理机制，持续提高优质中小企业发展质量。"},{"no":"十五","title":"第十五条","text":"工业和信息化部按年度对中小企业专精特新发展质量进行评价，并将评价结果纳入中小企业发展环境第三方评估。对于评价得分较低的地区，采取限制推荐名额、控制数量增长等措施。对评价得分较低的企业，加强重点监测。"},{"no":"十六","title":"第十六条","text":"经认定的专精特新中小企业和专精特新\"小巨人\"企业有效期3年，每次到期前由认定部门组织复核（含实地抽查）。复核通过的，有效期延长3年。"},{"no":"十七","title":"第十七条","text":"有效期内的专精特新中小企业和专精特新\"小巨人\"企业，可登录培育平台查询认定状态和有效期，并在每年5月31日前通过培育平台更新企业信息。在同一个有效期内，对首次未进行更新的企业，重点监测；对累计达两次未更新的企业，取消认定。"},{"no":"十八","title":"第十八条","text":"有效期内的专精特新中小企业和专精特新\"小巨人\"企业，如发生合并、重组等与认定条件有关的重大变化，应在发生变化后的3个月内登录培育平台，填写重大变化情况报告表。不再符合认定标准的专精特新中小企业，由省级中小企业主管部门核实后取消认定；不再符合认定标准的专精特新\"小巨人\"企业，由省级中小企业主管部门核实后报工业和信息化部，由工业和信息化部取消认定。对于未报告重大变化情况的，取消复核资格，或取消认定。"},{"no":"十九","title":"第十九条","text":"有效期内的专精特新中小企业和专精特新\"小巨人\"企业，如发生简单更名，应在3个月内在培育平台上同步完成名称变更申请。如发生跨区域迁移，应在3个月内在培育平台上提交跨区域迁移申请，并与迁入地中小企业主管部门联系。后续由迁入地中小企业主管部门负责相关培育和服务监测等工作，迁出地中小企业主管部门应做好配合。"},{"no":"二十","title":"第二十条","text":"有效期内的专精特新中小企业和专精特新\"小巨人\"企业，如发生较大生产安全事故、重大网络和数据安全事件、重大环境违法行为、严重质量问题、严重违反相关行业管理规定、被列入严重失信主体名单，或被发现存在数据造假情形，取消认定且三年内不得再次申报。对取消认定后完成信用修复并移出严重失信主体名单的企业，以及按照行业管理规定要求完成整改并获得相关行业管理部门认可的企业，可以三年内再次申报。"},{"no":"二十一","title":"第二十一条","text":"各级中小企业主管部门应完善机制，加强对优质中小企业的风险监测与处置，涉及专精特新\"小巨人\"企业的重大风险，应及时上报工业和信息化部。"},{"no":"二十二","title":"第二十二条","text":"任何组织和个人可针对优质中小企业相关信息真实性、准确性等方面存在的问题，向负责该企业认定的中小企业主管部门实名举报，并提供佐证材料和联系方式。对受理的举报内容，中小企业主管部门应及时向被举报企业核实。被举报企业未按要求回复或经核查举报内容属实的，视情节轻重要求企业整改，或取消认定。\n第四章 培育服务"},{"no":"二十三","title":"第二十三条","text":"各级中小企业主管部门应着力把功夫下到培育和服务上，坚持质量为先，不层层设定培育数量指标。针对本地区不同发展阶段、不同类型中小企业的特点和需求，强化政策支持、健全服务体系、完善企业治理和加强权益保护，不断优化中小企业发展环境，促进中小企业专精特新发展。"},{"no":"二十四","title":"第二十四条","text":"各级中小企业主管部门应认真贯彻落实建设全国统一大市场和规范招商引资行为有关政策要求，加强部门协同、上下联动。统筹运用财税、金融、科技、产业、人才等政策工具，加强用地、用能、用数等要素保障，着力推动惠企政策\"免申即享、直达快享\"，提高政策精准性和有效性。"},{"no":"二十五","title":"第二十五条","text":"各级中小企业主管部门应着力构建公共服务与市场化服务相互促进的服务体系。推动各级中小企业公共服务机构扩面提质，共同打造线上线下深度融合的全国中小企业服务网，提升服务覆盖面和企业获得感。发挥国家中小企业公共服务示范平台（基地）、中小企业特色产业集群、科技型企业孵化器、校企协同育人基地等平台载体作用，坚持中小企业需求导向，聚焦技术创新、大中小企业融通、数智化转型、权益保护、市场开拓、融资促进、管理提升、国际化发展等领域，提供精准高效公共服务。建立健全服务专员队伍，加强优质中小企业对口联系帮扶。广泛汇聚市场化服务资源，鼓励引导市场化服务机构提高服务标准化、规范化、精准化水平，不断丰富服务产品、提升服务质量。"},{"no":"二十六","title":"第二十六条","text":"各级中小企业主管部门应加强指导，强化人才教育培训，通过政府购买专业机构服务等方式加强面向中小企业的经营管理诊断、精益生产等咨询服务，促进中小企业提升公司治理和经营管理水平。充分发挥企业党组织作用，大力弘扬企业家精神、工匠精神和工程师文化，提升企业凝聚力和竞争力。"},{"no":"二十七","title":"第二十七条","text":"各级中小企业主管部门应积极会同有关部门强化落实支持中小企业发展的有关法律制度，依法保护中小企业产权和知识产权等合法权益。"},{"no":"二十八","title":"第二十八条","text":"在企业认定和培育服务过程中，各级中小企业主管部门及其相关工作人员应当保护企业商业秘密。\n第五章 附则"},{"no":"二十九","title":"第二十九条","text":"与优质中小企业产生投融资、并购重组、交易合作等相关市场行为，由相关主体自主决策、自行负责。"},{"no":"三十","title":"第三十条","text":"科技和创新型中小企业有关要求和标准，以工业和信息化部联合有关部门制定发布的文件为准。在相关文件发布前，科技和创新型中小企业涵盖有效期内的科技型中小企业和创新型中小企业，相关工作继续按照原有标准、工作程序和职责分工开展。"},{"no":"三十一","title":"本办法自2026年4月1日起实施","text":"本办法自2026年4月1日起实施。原《优质中小企业梯度培育管理暂行办法》中涉及专精特新中小企业和专精特新\"小巨人\"企业相关条款和认定标准同时废止。在本办法实施前认定的专精特新中小企业和专精特新\"小巨人\"企业继续有效，有效期到期后自动失效，失效后按本办法重新认定或复核。"},{"no":"三十二","title":"本办法由工业和信息化部负责解释","text":"本办法由工业和信息化部负责解释。\n附件1\n专精特新中小企业认定标准\n需同时满足以下六项指标：\n（一）已获得科技和创新型中小企业称号，截至上年末从事特定细分市场时间达3年以上。\n（二）上年度营业收入总额达1500万元以上或近两年新增股权投资（合格机构投资者的实缴额）总额2000万元以上，主营业务收入总额占营业收入总额比重不低于80%，上年末资产负债率不超过80%。\n（三）近两年研发费用均不低于100万元，且每年占营业收入比重均不低于3%。\n（四）拥有1项以上与主导产品相关的Ι类知识产权，且实际应用并已产生经济效益。对近三年获得省部级以上科学技术奖励（排名前三）或拥有经认定的省部级以上研发机构的企业，不考察本项指标。\n（五）主导产品在国内或国际细分市场占有率较为靠前，且享有一定知名度、影响力。\n（六）本年度中小企业专精特新发展评价得分达50分以上（复核企业近两年任意一年达50分以上即可）。指标体系见《中小企业专精特新发展评价指标体系（试行）》。\n附件2\n专精特新\"小巨人\"企业认定标准\n需同时满足以下七项指标：\n（一）已获得专精特新中小企业称号，截至上年末从事特定细分市场时间达3年以上。\n（二）上年度营业收入总额达5000万元以上，主营业务收入总额占营业收入总额比重不低于90%。近两年营业收入复合增长率不低于5%（复核企业不考查该项指标），上年末资产负债率不超过75%。\n（三）近两年研发费用合计不低于1200万元，且每年占营业收入比重均不低于3%。\n（四）拥有4项以上与主导产品相关的Ι类知识产权，且实际应用并已产生经济效益。对近三年获得国家级科技奖励（排名前三）的企业，不考察本项指标。\n（五）主导产品在国内或国际细分市场占有率达到10%以上或国内前三名，且享有较高知名度、影响力。\n（六）主导产品属于制造业核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础，或属于改造提升传统产业、培育壮大新兴产业、布局建设未来产业，位于产业链关键环节，对提升产业链供应链韧性和安全水平发挥重要作用。\n（七）本年度中小企业专精特新发展评价得分达60分以上（复核企业近两年任意一年达60分以上即可）。指标体系见《中小企业专精特新发展评价指标体系（试行）》。"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/zcfg/gjjfg/202606/t20260615_34002090.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":false},{"id":"p-2026-76cd70","title":"衡阳市人民政府关于印发《关于全面落实\"三高四新\"美好蓝图进一步推动制造业高质量发展的若干支持政策》的通知","level":"city","region":"衡阳市","issuer":"衡阳市人民政府","documentNo":"衡政发〔2026〕1号","publishedAt":"2026-03-03","status":"active","tags":["认定资质","专项资金","研发创新"],"audience":["小微企业","高校毕业生"],"summary":"衡阳对新获评国家级、省级专精特新中小企业分别给予15万元、5万元奖励；国家专精特新\"小巨人\"项目最高补助30万元；数字化转型项目最高贴息60万元。","sections":[{"no":"一","title":"聚焦产业培塑，推动制造业提档升级","text":"聚焦产业培塑，推动制造业提档升级\n1.支持设备更新和技术改造。持续用力打造先进制造业高地，力促规模工业企业\"原地倍增\"，引导企业实施智能化、绿色化、融合化及本质安全改造等设施更新和技术改造项目。支持企业争取中央设备更新贷款贴息、省级工业企业设备更新和技术改造融资补贴，用足用好超长期特别国债资金，促进工业、电子信息、能源电力等重点领域企业加快更新改造步伐。\"原地倍增\"企业实施设备更新和技术改造项目，当年项目总投资达到200万元以上的，市级财政对项目一年期(含)以上贷款按贷款本金的2%给予贴息，单个企业最高不超过200万元；申请贷款贴息项目，设备投资占贷款金额比例应不低于30%。同一项目只能享受中央、省级、市级融资补贴中的一项。(责任部门:市工信局)\n2.推进企业加快数字化转型。深化\"智赋万企\"行动，提升中小企业数字化水平及核心竞争力，对数字化转型升级项目，年投资在200万元以上，单个企业自贷款合同签订后首次付息日起连续12个月按照年基准利率的60%予以贴息补助，最高不超过60万元(\"原地倍增\"贴息、数字化转型贴息原则上不重复享受)。支持开展数字化转型咨询诊断，鼓励企业争取省级诊断服务费补贴资金。(责任部门:市工信局)\n对新获评国家工信部相关试点示范项目、省级工业互联网平台、省级\"5G+工业互联网标杆工厂\"，给予每家最高不超过10万元奖励。对新获评\"两化\"融合管理体系贯标企业、数字化转型成熟度贯标企业、省级人工智能赋能新型工业化典型应用场景企业、省级数字新基建项目，给予每家不超过5万元奖励。带动产业链上下游更多配套中小企业\"上云上平台\"，培育\"上云上平台\"示范企业，给予每家不超过5万元补助。对通过工业互联网网络安全分类分级管理考核或工业和信息化领域数据安全管理考核的企业，给予每家不超过2万元补助。(责任部门:市工信局)\n3.培育壮大市场主体。对首次认定的规模以上工业企业，每家给予10万元的达规入统奖励。首次认定的资质等级建筑业企业、资质等级房地产开发企业、限额以上批零住餐企业、规模以上服务业企业每家分别给予2万元的达规入统奖励。培育专精特新企业，对新获评的国家级、省级专精特新中小企业分别给予15万元、5万元奖励。支持中小企业专精特新发展，推动中小企业转型升级，对国家专精特新\"小巨人\"企业、湖南省专精特新中小企业专精特新发展类项目按项目建设支出比例分别给予最高不超过30万元、20万元补助。支持举办\"创客中国\"衡阳市中小微企业创新创业大赛。加强中小企业服务体系建设，支持省级核心服务机构提升服务能力或开展相关服务业务，根据服务能力建设支出或服务业务支出规模进行补助，最高可补助10万元。降低企业上市股改税费成本，支持企业改制重组依规享受契税、土地增值税、所得税等相关减免与税务处理政策。积极推动企业依规申报多层次资本市场建设奖补资金。(责任部门:市政府办、市工信局、市发改委、市住建局、市商务局、市统计局、市税务局)\n4.打造制造业标杆企业。推动智能制造关键核心技术攻关，助力企业提升发展优势及市场份额，对新获评国家智能制造系统解决方案\"揭榜挂帅\"企业给予20万元奖励。对新认定的国家级、省级制造业单项冠军分别给予20万元、10万元奖励。对新认定的卓越级智能工厂、先进级智能工厂分别给予每家10万元、5万元奖励。鼓励企业开展产品全生命周期绿色管理，构建绿色制造体系，对新认定的省级绿色工厂、绿色供应链管理企业给予10万元奖励。对新认定的省级、市级消费品\"三品\"标杆企业，分别给予10万元、5万元奖励。对当年认定为湖南省首台套重大技术装备、首批次重点新材料、首版次软件、首套件基础电子元器件、首轮次工程流片芯片(简称\"五首\")产品的企业，给予每家不超过10万元奖励。对新增的\"军工资质\"企业给予10万元奖励；对国、省级军民融合示范项目企业，分别给予20万元、10万元奖励。(责任部门:市工信局、市委军民融合办)\n二"},{"no":"二","title":"激发企业活力，增强科技创新发展动能","text":"激发企业活力，增强科技创新发展动能\n5.提升技术创新水平。对首次、再次获得认定的高新技术企业分别一次性奖励10万元、3万元。培育国省科技奖励企业，对入选企业给予10万元奖励；支持科技创新重大项目，每个给予30万元奖励；支持重点研发项目，每个给予10万元奖励；支持基础应用研究，每项给予3万元奖励。设立400万元企业研发费用辅导专项资金，支持县市区辅导企业建立规范的研发费用归集机制并做好会计辅助账。设立科技成果转化专项经费100万元，支持科技成果转化及转化服务能力提升项目。支持企业引进科技人才，支持举办\"双创大赛\"，营造创新创业氛围，提升企业创新创业水平。(责任部门:市科技局)\n6.促进产学研用深度融合。鼓励各产业链领军企业与相关高校、科研院所开展产学研合作，组建创新联合体。对重点产学研合作项目、一般产学研合作项目分别给予30万元、10万元补助，创新联合体给予20万元补助。对新认定的重点实验室、技术创新中心，按照国家级50万元、省级20万元标准，分别给予一次性奖励；对新列入的国家、省级科技孵化器，分别给予30万元、10万元项目资助；对新认定的工程研究中心、企业技术中心(发改部门评定)，按照国家级50万元、省级20万元标准，分别给予一次性奖励；对新认定的省级企业技术中心、省级工业设计中心(工信部门评定)，给予10万元奖励。统筹设立专项资金1亿元，支持衡阳智能衡器计量产业园加快建设国家计量人才实训中心、国家产业计量测试中心等公共技术平台，围绕产业发展开展技术攻关和应用示范；鼓励衡阳智能衡器计量产业园与知名院校、科研院所在人才培养、技术创新等方面开展合作，提高产业集聚程度。(责任部门:市科技局、市发改委、市工信局、衡阳智能衡器计量产业园)\n7.强化标准引领作用。鼓励企业积极参与标准制定，对主持、参与标准制定的企业进行奖励。对主持制定国际标准、国家标准的企业给予奖励，最高不超过40万元；参与制定国际标准、国家标准的企业，最高不超过15万元；主持、参与制定行业标准的企业，最高不超过15万元、10万元；主持、参与制定湖南省地方标准的企业，最高不超过10万元、5万元奖励(同一企业同一标准不重复奖励，累计奖励不超过100万元)。支持企业争创质量奖，对首次获得中国质量奖、省长质量奖、市长质量奖、湖南名品的企业，分别给予50万元、30万元、10万元、10万元奖励。利用物联网、云计算、大数据等技术手段，积极打造数字化、信息化、智能化的\"阳光计量\"交易及监管模式。(责任部门:市市场监管局、衡阳智能衡器计量产业园)\n8.推动知识产权量质齐升。提升知识产权创造运用水平及服务管理能力，对知识产权强链增效项目按10万元/个进行补助，对知识产权重点企业保护项目按6万元/个进行补助，对地理标志运用保护培育工程项目按6万元/个进行补助，对高价值发明专利培育及专利转化运用项目按10万元/个进行补助，对公共服务平台建设项目按10万元/个进行补助，对知识产权优质服务机构建设项目按5万元/个进行补助。对海外知识产权保护项目按6万元/个进行补助。对经国家知识产权局质押登记的专利、商标、数据知识产权质押融资予以补助，根据单笔融资额的0.2%予以补助，最高不超过3万元。(责任部门:市市场监管局)\n三"},{"no":"三","title":"改善融资环境，提升金融服务质效","text":"改善融资环境，提升金融服务质效\n9.发挥产业基金带动效应。树立全市产业基金\"一盘棋\"思想，深化财政资金\"拨改投\"改革，精准布局战略性新兴产业，培育壮大耐心资本，以市场化基金运作方式支持企业发展。强化联动协同，对接省级金芙蓉等基金资源，协同已参股子基金形成合力，并推动有条件的县市区(园区)出资入股，支持市属国企围绕主业设立相关基金，共同扩大惠企资本供给。畅通产融对接，建立由市发改、工信、商务等部门及各园区负责的重点产业链优质项目定期推送机制，引导基金提前介入、予以支持。优化激励与风险管控，在坚守政策目标与资金安全底线的前提下，对实现综合超额收益的基金，可在收益分配上对管理机构及社会出资人给予适当让利，吸引更多社会资本参与企业培育。(责任部门:市发改委、市工信局、市财政局、市商务局、市国资委)\n10.落实创(就)业补贴政策。通过财政贴息引导金融机构加大创业担保贷款投放。对符合创业担保贷款条件的小微企业，按照贷款合同签订日贷款利率(且贷款利率在LPR+150PB以内)的50%给予贴息，贷款额度最高为400万元；贷款期限最长不超过2年；已享受过创业担保贷款政策的小微企业，贷款无逾期还清后可再次享受创业担保贷款，累计次数不得超过3次，再次享受时吸纳就业人员不得与之前申请时吸纳人员重复。落实财政补助支持实施各项就业扶持政策，对符合条件人员参加职业技能培训、高技能人才培训基地和技能大师工作室建设、公共就业服务机构服务能力建设等给予就业创业服务补助。鼓励用人单位吸纳就业，对就业见习、自主创业、就业参保给予补贴。按规定对就业困难人员、困难高校毕业生给予求职帮扶补贴。(责任部门:市财政局、市人社局)\n11.完善政府性融资担保体系。为企业提供融资担保和\"临时性超短期贷款\"(转贷)服务，备案担保项目单户融资担保金额原则上不超过1500万元，对于符合\"民间投资专项担保计划\"的担保额度最高可达2000万元(期限1年以上)，对于科技创新型中小企业单户融资担保金额最高可达3000万元。大力推广\"人才创业贷款担保\"等金融产品，为毕业5年内在我市中心城区自主创业、合伙经营的大学生提供30-110万元融资担保政策；为招用高校毕业生达到一定数量的小微企业提供最高500万元融资担保贷款，对担保费予以优惠。推动普惠金融高质量发展，依托普惠金融发展专项资金，加大对市融资担保公司资本注入力度，鼓励市融资担保公司及市小额贷款公司为中小微企业提供低费用非融资保函等服务，促进政府融资担保扩围加力。(责任部门:市财政局、市融资担保公司)\n四"},{"no":"四","title":"强化服务保障，助力企业降本增效","text":"强化服务保障，助力企业降本增效\n12.优化政府采购环境。符合法定条件的供应商凭《湖南省政府采购供应商资格承诺函》参与政府采购活动，免收投标保证金及采购文件工本费。中小企业凭《中小企业申明函》享受相关评审价格扣除优惠政策。采取保函、电子增信等非现金形式缴纳合同履约保证金，对资信良好的中标企业，鼓励支持采购单位免收履约保证金。预算200万元以下的货物、服务项目和400万元以下的工程项目适宜由中小企业提供的，应面向中小企业采购；上述标准以上的项目适宜由中小企业提供的，应预留40%以上的份额专门面向中小企业，其中小微企业不低于60%。全面推行政府采购贷，中标企业凭政府采购中标通知书和政府采购合同，在湖南政府采购网衡阳分网线上融资平台上自主选择金融机构进行政府采购合同融资。搭建政府采购全流程查询与线上投诉平台，供应商可即时查询相关信息，提升政府采购的公开透明程度。(责任部门:市财政局)\n以上措施自公布之日起实施，有效期至2028年12月31日。执行过程中，如上级及我市另行出台文件对政策期限进行规定的，从其规定。本文件按现行财政体制按比例分级负担，市财政统一结算。各责任部门要结合自身职责职能制定实施细则，实行全程跟踪服务，加强政策宣传和对接，确保政策直达快享，力争各项政策的施行取得更大实效，进一步助推全市制造业高质量发展。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202610/t20261023_34087305.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false","verified":false,"isSample":false,"hunan":true},{"id":"p-2026-d6dec6","title":"关于组织开展2026年湖南省专精特新中小企业申报和复核工作的通知","level":"provincial","region":"湖南省","issuer":"湖南省工业和信息化厅","documentNo":"","publishedAt":"2026-01-27","status":"active","tags":["认定资质"],"audience":["小微企业"],"summary":"申报企业应在湖南省内工商登记注册、符合《专精特新中小企业认定标准》且须是省工业和信息化厅已公告的湖南省创新型中小企业，申报（复核）时间为2026年1月28日—2026年3月4日，须在优质中小企业梯度培育平台完成数字化水平评测后线上申报。","sections":[{"no":"一","title":"条件标准","text":"1、申报企业应在湖南省内工商登记注册，具有独立法人资格，符合《中小企业划型标准规定》。\n\n2、企业未被列入经营异常名录或严重失信主体名单，提供的产品（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生重大安全（含网络安全、数据安全）、质量、环境污染等事故以及偷漏税等违法违规行为。\n\n3、坚持企业自愿原则，符合《专精特新中小企业认定标准》（工信部企业〔2022〕63号，附件1）。\n\n4、重点聚焦制造强国重点产业（新一代信息技术产业、高档数控机床和机器人、航空航天装备、海洋工程装备及高技术船舶、先进轨道交通装备、节能与新能源汽车、电力装备、农机装备、新材料、生物医药及高性能医疗器械）、工业“六基”（核心基础零部件、核心基础元器件、关键软件、先进基础工艺、关键基础材料、产业技术基础）、“4×4”现代化产业体系（现代石化、绿色矿业、食品加工、轻工纺织4大传统产业，工程机械、轨道交通装备、现代农业、文化旅游4大优势产业，数字、新能源、大健康、空天海洋4大新兴产业，以及人工智能、生命工程、量子科技、前沿材料4大未来产业）等领域。\n\n二"},{"no":"二","title":"申报（复核）时间","text":"2026年1月28日-2026年3月4日\n\n三"},{"no":"三","title":"申报（复核）方式","text":"1、申报企业须是省工业和信息化厅已公告的湖南省创新型中小企业。有效期内的专精特新中小企业（湖南省专精特新“小巨人”企业）、专精特新“小巨人”企业不再申报。\n\n2、本次复核的企业为2022年、2023年认定和复核的湖南省专精特新“小巨人”企业，复核公告文件发布之前，企业仍属于有效期内的专精特新中小企业。有效期内的国家级专精特新“小巨人”企业无需参与复核。\n\n3、按属地原则，申报（复核）企业须首先在优质中小企业梯度培育平台（https://zjtx.miit.gov.cn/，以下称“培育平台”）完成数字化水平评测，然后在培育平台进行线上申报和复核，完整填写《专精特新中小企业申请书》，并打包上传佐证材料（附件2）。\n\n四"},{"no":"四","title":"有关要求","text":"1、各市州工信部门要高度重视专精特新中小企业培育工作，认真履行职责，坚持条件标准，严格审核把关，确保申报（复核）质量。\n\n2、请各市州工信部门于3月4日前在培育平台提交审核意见，并将专精特新中小企业推荐函和汇总表（附件3，纸质件2份）报省工业和信息化厅，逾期不候。\n\n3、严禁弄虚作假。申报（复核）企业对申报材料的完整性、真实性、合法性负责，相关后果由申报（复核）企业自行承担。凡在申报（复核）过程中存在弄虚作假行为的，一经发现，取消本年度申报（复核）资格，并且三年内不得再次申报。\n\n4、严禁代理申报。省工业和信息化厅从未委托任何单位或个人为企业代理申报事宜，请相关企业按程序自主申报。凡委托代理申报的，一经发现，取消参评资格，且三年内不得再次申报。各级工信部门受理申报申请，不收取任何费用。如有任何中介机构或个人假借单位或工作人员名义向企业进行推销或收取费用的，请谨防欺诈，避免上当受骗，并请向当地相关部门举报。任何单位不得以参加收费培训班或解读班作为企业申报前提条件。\n\n联系电话：0731-88955419\n\n邮寄地址：长沙市天心区新韶东路467号\n\n培育平台相关问题咨询电话：85559832"}],"interpretations":[],"sourceUrl":"https://gxt.hunan.gov.cn/gxt/xxgk_71033/tzgg/202601/t20260128_33904604.html","sourceNote":"组员采集卡片转入，原文逐字核对前保持 verified: false；2026-11-08 核对：页面发布日期 2026-01-28","verified":true,"isSample":false,"hunan":true},{"id":"vat-law-transition-preferential-2026","title":"财政部 税务总局关于增值税法施行后增值税优惠政策衔接事项的公告","level":"national","region":"全国","issuer":"财政部、税务总局","documentNo":"财政部 税务总局公告2026年第10号","publishedAt":"2026-02-28","effectiveAt":"2026-01-01","expiresAt":"2027-12-31","status":"active","tags":["税收优惠"],"audience":["小规模纳税人","小微企业","个体工商户"],"summary":"2026年至2027年，小规模纳税人月销售额10万元以下免征增值税，3%征收率应税收入减按1%征收。","sections":[{"no":"一","title":"增值税起征点标准","text":"自2026年1月1日至2027年12月31日,小规模纳税人发生应税交易,起征点标准如下:\n\n(一)以一个月为一个计税期间的,起征点为月销售额10万元。以一个季度为一个计税期间的,起征点为季度销售额30万元。\n\n(二)按次纳税的,起征点为每次(日)销售额1000元。一日内发生多次应税交易的,按日适用起征点标准。\n\n小规模纳税人发生应税交易,按照规定以扣除相关价款后的余额计算销售额或者允许从含税销售额中扣除相关价款后计算应纳税额的,以扣除相关价款后的不含税余额,适用本条起征点标准。"},{"no":"二","title":"免征增值税的项目","text":"(一)自2026年1月1日起,下列项目免征增值税。\n\n1.农业生产者销售的自产农产品。\n\n《中华人民共和国增值税法实施条例》(以下简称增值税法实施条例)第二十六条所称从事农业生产,是指直接从事植物的种植、收割和动物的饲养、捕捞;初级农产品,是指《财政部 税务总局关于增值税征税具体范围有关事项的公告》(财政部 税务总局公告2026年第9号)附件1《适用9%增值税税率货物范围注释》中的农产品。\n\n纳税人销售外购的初级农产品,以及用外购农产品生产、加工的初级农产品,不属于本项目免征增值税的范围,应当按照规定缴纳增值税。\n\n2.农业机耕、排灌、病虫害防治、植物保护、农牧保险以及相关技术培训业务,家禽、牲畜、水生动物的配种和疾病防治。\n\n增值税法第二十四条第一款第一项所称农业机耕,是指在农业、林业、畜牧业中使用农业机械进行耕作(包括耕耘、种植、收割、脱粒、植物保护等)的业务;排灌,是指对农田进行灌溉或者排涝的业务;病虫害防治,是指从事农业、林业、畜牧业、渔业的病虫害测报和防治的业务;农牧保险,是指为种植业、养殖业、畜牧业种植和饲养的动植物提供保险的业务;相关技术培训,是指与农业机耕、排灌、病虫害防治、植物保护业务相关以及为使农民获得农牧保险知识的技术培训业务;家禽、牲畜、水生动物的配种和疾病防治,包括与该项服务有关的提供药品和医疗用具的业务。\n\n3.医疗机构提供的医疗服务。\n\n增值税法实施条例第二十七条所称医疗机构,具体包括:各级各类医院、门诊部(所)、社区卫生服务中心(站)、急救中心(站)、城乡卫生院、护理院(所)、疗养院、临床检验中心,各级政府及有关部门举办的卫生防疫站(疾病控制中心)、各种专科疾病防治站(所),各级政府举办的妇幼保健所(站)、母婴保健机构、儿童保健机构,各级政府举办的血站(血液中心)等医疗机构,不包括营利性美容医疗机构。\n\n增值税法第二十四条第一款第二项所称医疗服务,是指医疗机构按照不高于地市级以上医疗保障部门牵头制定的医疗服务价格(包括政府指导价和按照规定由供需双方协商确定的价格等),为就医者提供《全国医疗服务价格项目规范》所列的各项服务,以及医疗机构向社会提供卫生防疫、卫生检疫的服务。\n\n4.残疾人个人提供的服务。\n\n增值税法第二十四条第一款第六项所称残疾人个人提供的服务,是指残疾人本人为社会提供的服务。\n\n5.托儿所、幼儿园提供的育养服务。\n\n增值税法实施条例第二十九条所称有关收费标准,是指公办托儿所、幼儿园经当地有关部门批准的收费标准,以及民办托儿所、幼儿园实行政府指导价管理或政府设置参考区间的实际收费标准。\n\n保育费、保育教育费超过规定收费标准的,以及以开办实验班、特色班和兴趣班等名义收取的费用,与入托、入园挂钩的赞助费、支教费等超过规定范围的各种费用,不属于免征增值税的范围。\n\n6.殡葬服务。\n\n增值税法第二十四条第一款第七项所称的殡葬服务,是指收费标准由各地价格主管部门会同有关部门核定,或者实行政府指导价管理的遗体接运(含抬尸、消毒)、遗体整容、遗体防腐、遗体存放(含冷藏)、遗体火化、骨灰寄存、吊唁设施设备租赁、墓穴租赁及管理等服务。\n\n7.学校提供的学历教育服务。\n\n(1)增值税法第二十四条第一款第八项所称的学历教育,具体包括:\n\n初等教育:普通小学、成人小学。\n\n初级中等教育:普通初中、职业初中、成人初中。\n\n高级中等教育:普通高中、成人高中、中等职业学校(包括普通中专、成人中专、职业高中、技工学校)。\n\n高等教育:普通本专科、成人本专科、网络本专科、研究生(博士、硕士)、高等教育自学考试、高等教育学历文凭考试。\n\n(2)增值税法实施条例第三十条所称学校,具体包括:\n\n普通学校;经地市级以上人民政府或者同级政府的教育行政部门批准成立、国家承认其学员学历的各类学校;经省级及以上人力资源社会保障行政部门批准成立的技工学校、高级技工学校;经省级人民政府批准成立的技师学院。上述学校均包括符合规定的从事学历教育的民办学校,但不包括职业培训机构等国家不承认学历的教育机构。\n\n(3)提供学历教育服务免征增值税的收入,是指学校为列入规定招生计划的在籍学生提供学历教育服务取得的收入,具体包括:经有关部门审核批准并按规定标准收取的学费、住宿费、课本费、作业本费、考试报名费收入,以及学校食堂提供餐饮服务取得的伙食费收入。除此之外的收入,包括学校以各种名义收取的赞助费、择校费等,不属于免征增值税的范围。\n\n8.农业生产用地,具体包括:\n\n(1)将国有农用地出租给农业生产者用于农业生产。\n\n(2)将土地使用权转让给农业生产者用于农业生产。\n\n(3)采取转包、出租、互换、转让、入股等方式将承包地流转给农业生产者用于农业生产。\n\n9.个人从事金融商品转让业务取得的收入。\n\n10.美国船级社(ABS)在非营利宗旨不变、中国船级社在美国享受同等免税待遇的前提下,在中国境内提供的船检服务。\n\n11.台湾航运公司、航空公司从事海峡两岸海上直航、空中直航业务在大陆取得的运输收入。\n\n台湾航运公司,是指取得交通运输部颁发的“台湾海峡两岸间水路运输许可证”且该许可证上注明的公司登记地址在台湾的航运公司。\n\n台湾航空公司,是指取得中国民用航空局颁发的“经营许可”或者依据《海峡两岸空运协议》和《海峡两岸空运补充协议》规定,批准经营两岸旅客、货物和邮件不定期(包机)运输业务,且公司登记地址在台湾的航空公司。\n\n12.土地所有者出让土地使用权和土地使用者将土地使用权归还给土地所有者。\n\n13.县级以上地方人民政府或自然资源行政主管部门出让、转让或收回自然资源使用权(不含土地使用权)。\n\n14.香港市场投资者(包括单位和个人)买卖股票、基金,具体包括:\n\n(1)通过深港通买卖深圳证券交易所上市A股取得的收入。\n\n(2)通过沪港通买卖上海证券交易所上市A股取得的收入。\n\n(3)通过基金互认买卖内地基金份额取得的收入。\n\n15.被撤销金融机构以货物、不动产、无形资产、有价证券、票据等财产清偿债务。\n\n被撤销金融机构,是指经中国人民银行、金融监管总局依法决定撤销的金融机构及其分设于各地的分支机构,包括被依法撤销的商业银行、信托公司、财务公司、金融租赁公司、信用社。除另有规定外,被撤销金融机构所属、附属企业,不享受被撤销金融机构增值税免税政策。\n\n16.人民银行对金融机构的贷款的利息收入。\n\n17.外汇管理部门在从事国家外汇储备经营过程中,委托金融机构发放的外汇贷款取得的利息收入。\n\n18.个人(不含个体工商户中的一般纳税人)销售自建自用住房。\n\n19.涉及家庭财产分割的个人无偿转让不动产、土地使用权。\n\n家庭财产分割,包括下列情形:离婚财产分割;无偿赠予配偶、父母、子女、祖父母、外祖父母、孙子女、外孙子女、兄弟姐妹;无偿赠予对其承担直接抚养或者赡养义务的抚养人或者赡养人;房屋产权所有人死亡,法定继承人、遗嘱继承人或者受遗赠人依法取得房屋产权。\n\n20.执法部门和单位处置罚没财产收入,且作为罚没收入如数上缴财政的。\n\n21.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 国家税务总局 外经贸部关于外国政府和国际组织无偿援助项目在华采购物资免征增值税问题的通知》(财税〔2002〕2号)和《财政部 国家税务总局关于外国政府和国际组织无偿援助项目在华采购物资免征增值税的补充通知》(财税〔2005〕13号)。\n\n(2)《财政部 税务总局关于全国社会保障基金有关投资业务税收政策的通知》(财税〔2018〕94号)。\n\n(3)《财政部 税务总局关于基本养老保险基金有关投资业务税收政策的通知》(财税〔2018〕95号)。\n\n(4)《财政部 税务总局 证监会关于交易型开放式基金纳入内地与香港股票市场交易互联互通机制后适用税收政策问题的公告》(财政部 税务总局 证监会公告2022年第24号)。\n\n(5)《财政部 税务总局关于法律援助补贴有关税收政策的公告》(财政部 税务总局公告2022年第25号)。\n\n(6)《财政部 税务总局关于国债等债券利息收入增值税政策的公告》(财政部 税务总局公告2025年第4号)。\n\n(7)《财政部 税务总局关于划转充实社保基金国有股权及现金收益运作管理税收政策的通知》(财税〔2025〕26号)。\n\n(二)自2026年1月1日至2027年12月31日,下列项目免征增值税。\n\n1.农业生产资料。\n\n(1)农膜、滴灌带、滴灌管和有机肥产品。\n\n(2)饲料产品。具体包括:\n\n单一大宗饲料。指以一种动物、植物、微生物或矿物质为来源的产品或其副产品。其范围仅限于糠麸、酒糟、鱼粉、饲用鱼油、草饲料及除豆粕以外的菜籽粕、棉籽粕、向日葵粕、花生粕等粕类产品。\n\n混合饲料。指由两种以上单一大宗饲料、粮食、粮食副产品及饲料添加剂按照一定比例配置,其中单一大宗饲料、粮食及粮食副产品的掺兑比例不低于95%的饲料。\n\n配合饲料。指根据不同的饲养对象的不同生长发育阶段的营养需要,将多种饲料原料按饲料配方经工业生产后,形成能满足饲养动物全部营养需要(除水分外)的饲料。\n\n复合预混料。指能够按照国家有关饲料产品的标准要求量,全面提供动物饲养相应阶段所需微量元素(4种或以上)、维生素(8种或以上),由微量元素、维生素、氨基酸和非营养性添加剂中任何两类或两类以上的组分与载体为原料、经高压浓缩制成的块状预混物,可供牛、羊等牲畜直接食用的饲料,属于浓缩饲料。\n\n浓缩饲料。指由蛋白质、复合预混料及矿物质等按一定比例配制的均匀混合物。\n\n矿物质微量元素舔砖。指以四种以上微量元素、非营养性添加剂和载体为原料,经高压浓缩制成的块状预混物,可供牛、羊等牲畜直接食用的饲料,属于浓缩饲料。\n\n宠物饲料不属于免征增值税的饲料。\n\n(3)批发和零售的种子、种苗、农药、农机。农机包括不带动力的手扶拖拉机和三轮农用运输车。\n\n(4)农民专业合作社销售本社成员生产的初级农产品,属于农业生产者销售的自产农产品。\n\n农民专业合作社向本社成员销售的农膜、种子、种苗、农药、农机。\n\n农民专业合作社,是指依法设立和登记的农民专业合作社。\n\n2.纳税人提供技术转让、技术开发和与之相关的技术咨询、技术服务。\n\n技术转让、技术开发,是指《财政部 税务总局关于增值税征税具体范围有关事项的公告》(财政部 税务总局公告2026年第9号)附件2《销售服务、无形资产、不动产注释》中的转让“技术”、提供“研发服务”范围内的业务活动。技术咨询,是指就特定技术项目提供可行性论证、技术预测、专题技术调查、分析评价报告等业务活动。与技术转让、技术开发相关的技术咨询、技术服务,是指转让方(或者受托方)根据技术转让或者委托开发合同的规定,为帮助受让方(或者委托方)掌握所转让(或者委托开发)的技术,而提供的技术咨询、技术服务业务,且这部分技术咨询、技术服务的价款与技术转让或者技术开发的价款应当在同一张发票上开具。\n\n纳税人申请免征增值税时,须持技术转让、开发的书面合同,到纳税人所在地省级科技、工信主管部门进行认定,并持有关的书面合同和科技、工信主管部门审核意见证明文件报主管税务机关备查。\n\n3.个人转让著作权。\n\n4.按照国家规定的收费标准向学生收取的高校学生公寓住宿费收入和高校学生食堂为高校师生提供餐饮服务取得的收入。\n\n5.家政服务企业由员工制家政服务员提供家政服务取得的收入。\n\n家政服务企业,是指在企业营业执照的规定经营范围中包括家政服务内容的企业。员工制家政服务员,是指同时符合下列3个条件的家政服务员:\n\n(1)依法与家政服务企业签订半年及半年以上的劳动合同或者服务协议,且在该企业实际上岗工作。\n\n(2)家政服务企业为其按月足额缴纳了企业所在地人民政府根据国家政策规定的基本养老保险、基本医疗保险、工伤保险、失业保险等社会保险。对已享受新型农村养老保险和新型农村合作医疗等社会保险或者下岗职工原单位继续为其缴纳社会保险的家政服务员,如果本人书面提出不再缴纳企业所在地人民政府根据国家政策规定的相应的社会保险,并出具其所在乡镇或者原单位开具的已缴纳相关保险的证明,可视同家政服务企业已为其按月足额缴纳了相应的社会保险。\n\n(3)家政服务企业通过金融机构向其实际支付不低于企业所在地适用的经省级人民政府批准的最低工资标准的工资。\n\n6.国家助学贷款取得的利息收入。\n\n7.福利彩票、体育彩票的发行收入。\n\n8.社会团体收取的会费。\n\n社会团体,是指依照国家有关法律法规设立或登记并取得《社会团体法人登记证书》的非营利法人。会费,是指社会团体在国家法律法规、政策许可的范围内,依照社团章程的规定,收取的个人会员、单位会员和团体会员的会费。\n\n9.中国邮政集团有限公司及其所属邮政企业提供的邮政普遍服务和邮政特殊服务。\n\n10.军队转业干部和随军家属就业。\n\n(1)从事个体经营的军队转业干部,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n为安置自主择业的军队转业干部就业而新开办的企业,凡安置自主择业的军队转业干部占企业总人数60%(含)以上的,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n享受上述优惠政策的自主择业的军队转业干部必须持有师以上部队颁发的转业证件。\n\n(2)从事个体经营的随军家属,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n为安置随军家属就业而新开办的企业,自办理税务登记事项之日起,其提供的应税服务3年内免征增值税。\n\n享受税收优惠政策的企业,随军家属必须占企业总人数的60%(含)以上,并有军(含)以上政治和后勤机关出具的证明。\n\n随军家属必须有师以上政治机关出具的可以表明其身份的证明。\n\n按照上述规定,每一名随军家属可以享受一次免税政策。\n\n11.供残疾人专用的假肢、轮椅、矫型器(包括上肢矫型器、下肢矫型器、脊椎侧弯矫型器)。\n\n12.粮食和商品储备收入,具体包括:\n\n(1)销售政府储备食用植物油。\n\n(2)粮食经营企业经营军队用粮、救灾救济粮、水库移民口粮。\n\n军队用粮:指凭相关凭证按军供价供应中国人民解放军和中国人民武装警察部队的粮食。\n\n救灾救济粮:指经县(含)以上人民政府批准,凭相关凭证按规定的销售价格向需救助的灾民供应的粮食。\n\n水库移民口粮:指经县(含)以上人民政府批准,凭相关凭证按规定的销售价格供应给水库移民的粮食。\n\n(3)国家商品储备管理单位及其直属企业承担商品储备任务,从中央或者地方财政取得的利息补贴收入和价差补贴收入。国家商品储备管理单位及其直属企业,是指接受中央、省、市、县四级政府有关部门(或者政府指定管理单位)委托,承担粮(含大豆)、食用油、棉、糖、肉、盐(限于中央储备)等6种商品储备任务,并按有关政策收储、销售上述6种储备商品,取得财政储备经费或者补贴的商品储备企业。利息补贴收入,是指国家商品储备管理单位及其直属企业因承担商品储备任务从金融机构贷款,并从中央或者地方财政取得的用于偿还贷款利息的贴息收入。价差补贴收入包括销售价差补贴收入和轮换价差补贴收入。销售价差补贴收入,是指按照中央或者地方政府指令销售上述储备商品时,由于销售收入小于库存成本而从中央或者地方财政获得的全额价差补贴收入。轮换价差补贴收入,是指根据要求定期组织政策性储备商品轮换而从中央或地方财政取得的商品新陈品质价差补贴收入。\n\n13.纳税人提供的直接或者间接国际货物运输代理服务。\n\n(1)纳税人提供直接或者间接国际货物运输代理服务,向委托方收取的全部国际货物运输代理服务收入,以及向国际运输承运人支付的国际运输费用,必须通过金融机构进行结算。\n\n(2)纳税人为大陆与香港、澳门、台湾地区之间的货物运输提供的货物运输代理服务参照国际货物运输代理服务有关规定执行。\n\n(3)委托方索取发票的,纳税人应当就国际货物运输代理服务收入向委托方全额开具增值税普通发票。\n\n14.合格境外投资者(QFII)委托境内公司在我国从事证券买卖业务、人民币合格境外机构投资者(RQFII)委托境内公司在我国从事证券买卖业务,以及经中国人民银行认可的境外机构投资银行间本币市场取得的收入。银行间本币市场包括货币市场、债券市场以及衍生品市场。\n\n15.统借统还业务利息收入。\n\n统借统还业务利息收入,是指统借统还业务中,企业集团或企业集团中的核心企业以及集团所属财务公司按不高于支付给金融机构的借款利率水平或者支付的债券票面利率水平,向企业集团或者集团内下属单位收取的利息。\n\n统借方向资金使用单位收取的利息,高于支付给金融机构借款利率水平或者支付的债券票面利率水平的,应全额缴纳增值税。\n\n统借统还业务,是指:\n\n(1)企业集团或者企业集团中的核心企业向金融机构借款或对外发行债券取得资金后,将所借资金分拨给下属单位(包括独立核算单位和非独立核算单位,下同),并向下属单位收取用于归还金融机构或债券购买方本息的业务。\n\n(2)企业集团向金融机构借款或对外发行债券取得资金后,由集团所属财务公司与企业集团或者集团内下属单位签订统借统还贷款合同并分拨资金,并向下属单位收取用于归还金融机构或债券购买方本息的业务。\n\n16.公募证券投资基金(封闭式证券投资基金、开放式证券投资基金)管理人运用基金买卖股票、债券取得的收入。\n\n17.期货保税交割业务,具体包括:\n\n(1)经国务院批准对外开放的货物期货品种保税交割业务。\n\n(2)上海国际能源交易中心股份有限公司的会员和客户通过上海国际能源交易中心股份有限公司交易的原油期货保税交割业务,大连商品交易所的会员和客户通过大连商品交易所交易的铁矿石期货保税交割业务。\n\n(3)上海期货交易所的会员和客户通过上海期货交易所交易的期货保税交割业务。\n\n18.金融同业往来利息收入,具体包括:\n\n(1)金融机构与人民银行所发生的资金往来业务。包括人民银行对一般金融机构贷款,商业银行购买央行票据、与央行开展货币掉期和货币互存,以及人民银行对商业银行的再贴现等。\n\n(2)银行联行往来业务。包括同一银行系统内部不同行、处之间所发生的资金往来业务,境内银行与其境外的总机构、母公司之间的资金往来业务,以及境内银行与其境外的分支机构、全资子公司之间的资金往来业务。\n\n(3)金融机构间的资金往来业务。是指经人民银行批准,进入全国银行间同业拆借市场的金融机构之间通过全国统一的同业拆借网络进行的短期(一年以下,含一年)无担保资金融通行为。\n\n(4)金融机构开展同业存款、同业借款、同业代付、买断式买入返售金融商品、质押式买入返售金融商品、同业存单,取得的利息收入。\n\n同业存款,是指金融机构之间开展的同业资金存入与存出业务,其中资金存入方仅为具有吸收存款资格的金融机构。\n\n同业借款,是指法律法规赋予此项业务范围的金融机构开展的同业资金借出和借入业务。其中,法律法规赋予此项业务范围的金融机构主要是指农村信用社之间以及在农村信用社营业执照业务范围中有反映为向金融机构借款业务的农村信用社。\n\n同业代付,是指商业银行(受托方)接受金融机构(委托方)的委托向企业客户付款,委托方在约定还款日偿还代付款项本息的资金融通行为。\n\n买断式买入返售金融商品,是指金融商品持有人(正回购方)将债券等金融商品卖给债券购买方(逆回购方)的同时,交易双方约定在未来某一日期,正回购方再以约定价格从逆回购方买回相等数量同种债券等金融商品的交易行为。\n\n质押式买入返售金融商品,是指交易双方进行的以债券等金融商品为权利质押的一种短期资金融通业务。\n\n同业存单,是指银行业存款类金融机构法人在全国银行间市场上发行的记账式定期存款凭证。\n\n金融机构,是指银行,包括人民银行、商业银行、政策性银行;信用社;证券公司、金融租赁公司、证券基金管理公司、财务公司、信托公司;保险公司;其他经中国人民银行、金融监管总局、中国证监会批准成立且经营金融保险业务的金融机构等。\n\n19.保险公司开办的一年期以上人身保险产品取得的保费收入。\n\n一年期以上人身保险,是指保险期间为一年期及以上返还本利的人寿保险、养老年金保险和其他年金保险,以及保险期间为一年期及以上的健康保险。\n\n人寿保险,是指以人的寿命为保险标的的人身保险。\n\n养老年金保险,是指以养老保障为目的,以被保险人生存为给付保险金条件,并按约定的时间间隔分期给付生存保险金的人身保险。\n\n养老年金保险应当同时符合下列条件:\n\n(1)保险合同约定给付被保险人生存保险金的年龄不得小于国家规定的退休年龄。\n\n(2)相邻两次给付的时间间隔不得超过一年。\n\n其他年金保险,是指养老年金以外的年金保险。\n\n健康保险,是指以因健康原因导致损失为给付保险金条件的人身保险。\n\n保险公司开办一年期以上人身保险,在保险监管部门出具备案回执或批复文件前依法取得的保费收入,属于上述规定的保费收入。\n\n20.纳税人提供再保险服务(境内保险公司向境外保险公司提供的再保险服务除外),实行与原保险服务一致的增值税政策。再保险合同对应多个原保险合同的,所有原保险合同均适用免征增值税政策时,该再保险合同适用免征增值税政策。否则,该再保险合同应按规定缴纳增值税。原保险服务,是指保险分出方与投保人之间直接签订保险合同而建立保险关系的业务活动。\n\n21.医疗机构接受其他医疗机构委托,按照不高于地市级以上医疗保障部门牵头制定的医疗服务价格(包括政府指导价和按照规定由供需双方协商确定的价格等),提供《全国医疗服务价格项目规范》所列的各项服务,可适用本公告第二条第一项“医疗机构提供的医疗服务”政策。\n\n22.为了配合国家住房制度改革,企业、行政事业单位按房改成本价、标准价出售住房取得的收入。\n\n23.住房公积金管理中心用住房公积金在指定的委托银行发放的个人住房贷款取得的利息收入。\n\n24.黄金生产和经营单位销售黄金(不包括以下品种:牌号为AU9999、AU9995、AU999、AU995,规格为50克、100克、1公斤、3公斤、12.5公斤的黄金,统称标准黄金)和黄金矿砂(含伴生金)。\n\n25.中国信达资产管理股份有限公司、中国中信金融资产管理股份有限公司、中国长城资产管理股份有限公司和中国东方资产管理股份有限公司及各自经批准分设于各地的分支机构(以下称资产公司),在收购、承接和处置剩余政策性剥离不良资产和改制银行剥离不良资产过程中开展的以下业务:\n\n(1)接受相关国有银行的不良债权,借款方以货物、不动产、无形资产、有价证券和票据等抵充贷款本息的,资产公司销售、转让该货物、不动产、无形资产、有价证券、票据以及利用该货物、不动产从事的融资租赁业务。\n\n(2)接受相关国有银行的不良债权取得的利息。\n\n(3)资产公司所属的投资咨询类公司,为本公司收购、承接、处置不良资产而提供的资产、项目评估和审计服务。\n\n政策性剥离不良资产,是指资产公司按照国务院规定的范围和额度,以账面价值进行收购的相关国有银行的不良资产。\n\n处置不良资产,是指资产公司按照有关法律、行政法规,为使不良资产的价值得到实现而采取的债权转移的措施,具体包括运用出售、置换、资产重组、债转股、证券化等方法对贷款及其抵押品进行处置。\n\n资产公司除收购、承接、处置规定的政策性剥离不良资产和改制银行剥离不良资产业务外,从事其他经营业务应一律依法纳税。\n\n除另有规定者外,资产公司所属、附属企业,不得享受资产公司免征增值税的政策。\n\n26.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 国家税务总局关于血站有关税收问题的通知》(财税字〔1999〕264号)。\n\n(2)《财政部 国家税务总局关于医疗卫生机构有关税收政策的通知》(财税〔2000〕42号)第三条。\n\n(3)《财政部 国家税务总局关于中国信达等4家金融资产管理公司税收政策问题的通知》(财税〔2001〕10号)。\n\n(4)《财政部 国家税务总局关于中国东方资产管理公司处置港澳国际(集团)有限公司有关资产税收政策问题的通知》(财税〔2003〕212号)。\n\n(5)《财政部 国家税务总局关于免征蔬菜流通环节增值税有关问题的通知》(财税〔2011〕137号)和《财政部 国家税务总局关于免征部分鲜活肉蛋产品流通环节增值税政策的通知》(财税〔2012〕75号)。\n\n(6)《财政部 国家税务总局关于熊猫普制金币免征增值税政策的通知》(财税〔2012〕97号)。\n\n(7)《财政部 税务总局 海关总署关于第18届世界中学生运动会等三项国际综合运动会税收政策的公告》(财政部 税务总局 海关总署公告2020年第19号)。\n\n(8)《财政部 税务总局关于支持小微企业融资有关税收政策的公告》(财政部 税务总局公告2023年第13号)。\n\n(9)《财政部 税务总局关于金融机构小微企业贷款利息收入免征增值税政策的公告》(财政部 税务总局公告2023年第16号)。\n\n(10)《财政部 税务总局关于延续执行农户、小微企业和个体工商户融资担保增值税政策的公告》(财政部 税务总局公告2023年第18号)。\n\n(11)《财政部 税务总局 科技部 教育部关于继续实施科技企业孵化器、大学科技园和众创空间有关税收政策的公告》(财政部 税务总局 科技部 教育部公告2023年第42号)。\n\n(12)《财政部 税务总局关于延续实施小额贷款公司有关税收优惠政策的公告》(财政部 税务总局公告2023年第54号)。\n\n(13)《财政部 税务总局关于延续实施供热企业有关税收政策的公告》(财政部 税务总局公告2023年第56号)(至2027年供暖期结束)。\n\n(14)《财政部 税务总局关于继续实施农村饮水安全工程税收优惠政策的公告》(财政部 税务总局公告2023年第58号)。\n\n(15)《财政部 税务总局关于延续实施边销茶增值税政策的公告》(财政部 税务总局公告2023年第59号)。\n\n(16)《财政部 税务总局关于延续免征国产抗艾滋病病毒药品增值税政策的公告》(财政部 税务总局公告2023年第62号)。\n\n(17)《财政部 税务总局关于延续实施金融机构农户贷款利息收入免征增值税政策的公告》(财政部 税务总局公告2023年第67号)。\n\n(18)《财政部 税务总局 中央宣传部关于延续实施文化体制改革中经营性文化事业单位转制为企业有关税收政策的公告》(财政部 税务总局 中央宣传部公告2023年第71号)。\n\n(19)《财政部 海关总署 税务总局关于哈尔滨2025年第九届亚洲冬季运动会税收政策的通知》(财税〔2024〕24号)。\n\n(20)《财政部 海关总署 税务总局关于2025年第12届世界运动会税收政策的通知》(财税〔2025〕15号)。"},{"no":"三","title":"适用简易计税方法的项目","text":"(一)自2026年1月1日至2027年12月31日,一般纳税人发生以下应税交易,可以选择适用简易计税方法,按照3%的征收率计算缴纳增值税。\n\n1.销售自行采掘的建筑用和生产建筑材料所用的砂、土、石料,和以自行采掘的砂、土、石料或其他矿物连续自行生产的砖、瓦、石灰(不含粘土实心砖、瓦)。\n\n2.小型水力发电单位销售自产的电力。小型水力发电单位,是指装机容量为5万千瓦以下(含5万千瓦)的小型水力发电单位。\n\n3.销售自来水。水利工程供应天然水比照销售自来水政策执行。\n\n4.寄售商店代销寄售物品(包括居民个人寄售的物品在内)。\n\n5.典当业销售死当物品。\n\n6.提供公共交通运输服务。公共交通运输服务,包括轮客渡、公交客运、地铁、城市轻轨、出租车、长途客运、班车。班车,是指按固定路线、固定时间运营并在固定站点停靠的运送旅客的陆路运输服务。\n\n7.以清包工方式提供的建筑服务。以清包工方式提供建筑服务,是指施工方不采购建筑工程所需的材料或只采购辅助材料,并收取人工费、管理费或者其他费用的建筑服务。\n\n8.为建筑工程老项目提供的建筑服务。建筑工程老项目,是指《建筑工程施工许可证》注明的合同开工日期在2016年4月30日前的建筑工程项目;《建筑工程施工许可证》未注明合同开工日期或者未取得《建筑工程施工许可证》但建筑工程承包合同注明的开工日期在2016年4月30日前的建筑工程项目。\n\n9.依据有关法律、法规批准设立的农村信用社、村镇银行、农村资金互助社、法人机构在县(市、区、旗)及县以下地区的农村合作银行和农村商业银行提供金融服务。县(市、区、旗)不包括直辖市和地级市所辖区。\n\n10.非企业单位提供的研发和技术服务、信息技术服务、鉴证咨询服务,以及销售技术、著作权等无形资产。\n\n11.公路经营企业收取开工日期在2016年4月30日前的高速公路的车辆通行费。高速公路的开工日期,以相关施工许可证明上注明的合同开工日期为准。\n\n12.提供电影放映服务、仓储服务、装卸搬运服务、收派服务和文化体育服务。\n\n13.提供非学历教育服务、教育辅助服务。\n\n14.资管产品管理人运营契约制资管产品过程中发生的增值税应税行为。\n\n资管产品管理人,包括银行、信托公司、公募基金管理公司及其子公司、证券公司及其子公司、期货公司及其子公司、私募基金管理人、保险资产管理公司、专业保险资产管理机构、养老保险公司。\n\n资管产品,包括银行理财产品、资金信托(包括集合资金信托计划、单一资金信托)、财产权信托、公开募集证券投资基金、特定客户资产管理计划、集合资产管理计划、定向资产管理计划、私募投资基金、债权投资计划、股权投资计划、股债结合型投资计划、资产支持计划、组合类保险资产管理产品、养老保障管理产品。\n\n15.下列文件中现行有效的增值税优惠政策。\n\n(1)《财政部 海关总署 税务总局 国家药品监督管理局关于抗癌药品增值税政策的通知》(财税〔2018〕47号)。\n\n(2)《财政部 海关总署 税务总局 药监局关于罕见病药品增值税政策的通知》(财税〔2019〕24号)。\n\n(3)《财政部 海关总署 税务总局 药监局关于发布第二批适用增值税政策的抗癌药品和罕见病药品清单的公告》(财政部 海关总署 药监局公告2020年第39号)。\n\n(4)《财政部 海关总署 税务总局 药监局关于发布第三批适用增值税政策的抗癌药品和罕见病药品清单的公告》(财政部 海关总署 药监局公告2022年第35号)。\n\n(5)《财政部 税务总局关于延续实施中国邮政储蓄银行三农金融事业部涉农贷款增值税政策的公告》(财政部 税务总局公告2023年第66号)。\n\n(二)自2026年1月1日至2027年12月31日,一般纳税人发生以下应税交易,可以选择适用简易计税方法,按照5%的征收率计算缴纳增值税。\n\n1.2016年4月30日前签订的不动产融资租赁合同,或者以2016年4月30日前取得的不动产提供的融资租赁服务。\n\n2.收取开工日期在2016年4月30日前的一级公路、二级公路、桥、闸通行费。公路、桥、闸的开工日期,以相关施工许可证明上注明的合同开工日期为准。\n\n3.出租其2016年4月30日前取得的不动产。\n\n4.销售其2016年4月30日前取得(含自建)的不动产。\n\n5.转让其2016年4月30日前取得的土地使用权。\n\n6.房地产开发企业销售、出租自行开发的房地产老项目。\n\n房地产老项目,是指《建筑工程施工许可证》注明的合同开工日期在2016年4月30日前的房地产项目;《建筑工程施工许可证》未注明合同开工日期或者未取得《建筑工程施工许可证》但建筑工程承包合同注明的开工日期在2016年4月30日前的房地产项目。\n\n房地产开发企业以围填海方式取得土地并开发的房地产项目,以围填海工程《建筑工程施工许可证》或建筑工程承包合同注明的围填海开工日期确定合同开工日期。\n\n房地产开发企业购入未完工的房地产老项目继续开发后,以自己名义立项销售的不动产,属于房地产老项目。\n\n(三)纳税人发生以下应税交易,可以选择适用简易计税方法,按照规定征收率计算缴纳增值税。\n\n1.自2026年1月1日起,一般纳税人销售自己使用过的属于增值税法第二十二条规定不得抵扣且未抵扣进项税额的固定资产,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n固定资产,是指使用期限超过12个月的机器、机械、运输工具以及其他与生产经营相关的设备、工具、器具等。\n\n2.自2026年1月1日起,小规模纳税人(不含自然人)销售自己使用过的固定资产,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n3.自2026年1月1日起,销售旧货,按照简易计税方法依照3%征收率减按2%计算缴纳增值税。\n\n旧货,是指进入二次流通的具有部分使用价值的货物(含旧汽车、旧摩托车和旧游艇),但不包括自己使用过的物品。\n\n4.自2026年1月1日起,个人(不含个体工商户中的一般纳税人)出租住房,按照简易计税方法依照3%征收率减按1.5%计算缴纳增值税。\n\n5.自2026年1月1日起,《财政部 税务总局 住房城乡建设部关于完善住房租赁有关税收政策的公告》(财政部 税务总局 住房城乡建设部公告2021年第24号)中现行有效的增值税优惠政策。\n\n6.自2026年1月1日至2027年12月31日,小规模纳税人发生除销售、出租不动产或者转让土地使用权之外的增值税应税交易,依照3%征收率减按1%征收率征收增值税;按规定预缴增值税的项目,当期在预缴地实现的全部价款、预收款(均不含增值税)合计达到增值税起征点的,减按1%预征率预缴增值税。\n\n7.自2026年1月1日至2027年12月31日,《财政部 税务总局关于延续实施二手车经销有关增值税政策的公告》(财政部 税务总局公告2023年第63号)中现行有效的增值税优惠政策。\n\n(四)有关规定。\n\n1.一般纳税人销售自行开发的房地产项目、提供建筑服务,可以按照房地产开发项目、工程建设项目选择适用简易计税方法。除上述情形外,一般纳税人应当就同一简易计税方法项目的全部应税交易一并选择适用简易计税方法。\n\n2.一般纳税人自选择适用简易计税方法当月起,36个月内不得变更;期限届满后,自选择适用一般计税方法当月起,36个月内不得再选择适用简易计税方法。\n\n3.纳税人按照简易计税方法依照规定征收率计算缴纳增值税的,按照下列公式计算销售额:\n\n销售额=含税销售额÷(1+规定征收率)"},{"no":"四","title":"允许从含税销售额中扣除相关价款的应税交易","text":"自2026年1月1日至2027年12月31日,纳税人发生下列应税交易,允许从含税销售额中扣除相关价款后计算销项税额或者应纳税额\n\n(一)金融机构开展贴现、转贴现业务,以其实际持有票据期间取得的利息收入作为销售额。\n\n金融机构开展贴现、转贴现业务需要就贴现利息开具发票的,由贴现机构按照票据贴现利息全额向贴现人开具增值税普通发票,转贴现机构按照转贴现利息全额向贴现机构开具增值税普通发票。\n\n(二)中国证券登记结算有限责任公司按规定提取的证券结算风险基金、收取的证券公司资金交收违约垫付资金利息、结算过程中收取的资金交收违约罚息,允许从含税销售额中扣除。\n\n(三)融资租赁和融资性售后回租业务。\n\n1.经国务院行业主管部门批准(含备案)从事融资租赁业务的纳税人,提供融资租赁服务,支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息和车辆购置税,允许从含税销售额中扣除。\n\n2.经国务院行业主管部门批准(含备案)从事融资租赁业务的纳税人,提供融资性售后回租服务,对外支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额(不含本金)中扣除。\n\n3.纳税人根据2016年4月30日前签订的有形动产融资性售后回租合同,在合同到期前提供的有形动产融资性售后回租服务,可以继续按照有形动产融资租赁服务缴纳增值税。\n\n继续按照有形动产融资租赁服务缴纳增值税的纳税人,经国务院行业主管部门批准(含备案)从事融资租赁业务的,根据2016年4月30日前签订的有形动产融资性售后回租合同,可以选择以下方法之一计算销项税额或者应纳税额:\n\n(1)向承租方收取的价款本金,以及对外支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额中扣除。\n\n纳税人提供有形动产融资性售后回租服务,计算当期销项税额或者应纳税额时可以扣除的价款本金,为书面合同约定的当期应当收取的本金。无书面合同或者书面合同没有约定的,为当期实际收取的本金。\n\n(2)支付的借款利息(包括外汇借款和人民币借款利息)、发行债券利息,允许从含税销售额中扣除。\n\n4.经商务部授权的省级商务主管部门和国家经济技术开发区批准(含备案)的从事融资租赁业务的纳税人,实收资本达到1.7亿元的,从达到标准的当月起按照上述规定执行。\n\n(四)纳税人提供建筑服务适用简易计税方法计税的,支付的分包款允许从含税销售额中扣除。\n\n(五)一般纳税人提供劳务派遣服务,代用工单位支付给劳务派遣员工的工资、福利和为其办理的社会保险及住房公积金,允许从含税销售额中扣除。\n\n劳务派遣服务,是指取得《劳务派遣经营许可证》的劳务派遣公司,为了满足用工单位对于各类灵活用工的需求,将员工派遣至用工单位,接受用工单位管理并为其工作的服务。\n\n取得《保安服务许可证》的保安服务公司,提供安全保护服务(含武装守护押运服务)比照上述政策执行。\n\n(六)纳税人提供旅游服务,向旅游服务购买方收取并支付给其他单位或者个人的住宿费、餐饮费、交通费、签证费、门票费和支付给其他接团旅游企业的旅游费用,允许从含税销售额中扣除。\n\n(七)纳税人转让其2016年4月30日前取得的土地使用权,选择适用简易计税方法计税的,取得该土地使用权的原价允许从含税销售额中扣除。\n\n(八)一般纳税人销售其2016年4月30日前取得(不含自建)的不动产,选择适用简易计税方法计税的,以及小规模纳税人销售其取得(不含自建)的不动产(不含个人销售购买的住房),该项不动产购置原价或者取得不动产时的作价允许从含税销售额中扣除。\n\n(九)房地产开发企业销售房地产项目。\n\n房地产开发企业销售其开发的适用一般计税方法计税的房地产项目,受让土地时向政府部门支付的土地出让金、征地和拆迁补偿费用、土地前期开发费用和土地出让收益(以下统称土地价款),以及在取得土地时向其他单位或个人支付的货币形式拆迁补偿费用,允许从含税销售额中扣除。\n\n当期允许扣除的土地价款=(当期销售房地产项目建筑面积÷房地产项目可供销售建筑面积)×支付的土地价款\n\n当期销售房地产项目建筑面积,是指当期进行纳税申报的增值税销售额对应的建筑面积。\n\n房地产项目可供销售建筑面积,是指房地产项目可以出售的总建筑面积,不包括销售房地产项目时未单独作价结算的配套公共设施的建筑面积。\n\n房地产开发企业(包括多个房地产开发企业组成的联合体)受让土地向政府部门支付土地价款后,设立项目公司对该受让土地进行开发,同时符合下列条件的,可由项目公司按规定扣除房地产开发企业向政府部门支付的土地价款。\n\n1.房地产开发企业、项目公司、政府部门三方签订变更协议或补充合同,将土地受让人变更为项目公司;\n\n2.政府部门出让土地的用途、规划等条件不变的情况下,签署变更协议或补充合同时,土地价款总额不变;\n\n3.项目公司存续期间的全部股权由受让土地的房地产开发企业持有。\n\n(十)纳税人开展金银首饰以旧换新业务,旧金银首饰的作价允许从含税销售额中扣除。\n\n(十一)纳税人按照本公告第四条第三项至第九项规定从含税销售额中扣除的价款,应当取得符合法律、行政法规或者税务总局规定的合法有效凭证留存备查。否则,不得扣除。\n\n1.适用第四条第五项规定,以工资、福利支付记录,社会保险缴费记录以及住房公积金缴存记录为合法有效凭证。\n\n2.适用第四条第七、九项规定,向政府支付土地价款的,以省级以上(含省级)财政部门监(印)制的财政票据为合法有效凭证。\n\n3.适用第四条第七、八项规定,向其他单位或者个人支付的款项,以发票或者法院判决书、裁定书、调解书,以及仲裁裁决书、公证债权文书为合法有效凭证。如因丢失等原因无法提供取得不动产时的发票,以其他能证明契税计税金额的完税凭证等资料为合法有效凭证。\n\n4.适用第四条第九项规定,向其他单位或个人支付的货币形式拆迁补偿费用,以拆迁协议、拆迁双方支付和取得拆迁补偿费用凭证等能够证明拆迁补偿费用真实性的材料为合法有效凭证。\n\n5.除本项上述规定外,按以下规定执行。\n\n(1)支付给境内单位或者个人的款项,以发票或者省级以上(含省级)财政部门监(印)制的财政票据为合法有效凭证。\n\n(2)支付给境外单位或者个人的款项,以该单位或者个人的签收单据为合法有效凭证,税务机关对签收单据有疑义的,可以要求其提供境外公证机构的确认证明。\n\n(3)缴纳的税款,以完税凭证为合法有效凭证。\n\n纳税人取得的上述凭证属于增值税扣税凭证的,其进项税额不得从销项税额中抵扣。\n\n(十二)纳税人按照第四条第二项至第八项规定从含税销售额中扣除相关价款的,应按以下规定开具发票,否则,不得扣除。\n\n1.适用第四条第二、三、四、六项规定,从含税销售额中扣除的相关价款,不得开具增值税专用发票,可以开具普通发票。\n\n2.适用第四条第五、七、八项规定,全部含税销售额和扣除的价款应在同一张发票上分别列明,发票的税额按含税销售额扣除相关价款后计算。"},{"no":"五","title":"其他增值税优惠项目","text":"(一)自2026年1月1日至2027年12月31日,一般纳税人提供管道运输服务,对其增值税实际税负超过3%的部分实行增值税即征即退政策。\n\n增值税实际税负,是指纳税人当期提供管道运输服务实际缴纳的增值税额占纳税人当期提供管道运输服务取得的销售额的比例。\n\n(二)自2026年1月1日起,一般纳税人购进农产品,取得一般纳税人开具的增值税专用发票或海关进口增值税专用缴款书的,以增值税专用发票或海关进口增值税专用缴款书上注明的增值税额为进项税额;从按照简易计税方法依照3%征收率计算缴纳增值税的小规模纳税人取得增值税专用发票的,以增值税专用发票上注明的金额和9%的扣除率计算进项税额;取得(开具)农产品销售发票或收购发票的,以农产品销售发票或收购发票上注明的农产品买价和9%的扣除率计算进项税额。一般纳税人从农民专业合作社购进的免税农产品,可按9%的扣除率计算进项税额。\n\n(三)自2026年1月1日至2027年12月31日,药品生产企业销售自产创新药的销售额,为向购买方收取的全部价款,其提供给患者后续免费使用的相同创新药,不属于增值税视同应税交易范围。\n\n(四)自2026年1月1日起,下列文件中现行有效的增值税优惠政策继续实施。\n\n1.《财政部 国家税务总局关于软件产品增值税政策的通知》(财税〔2011〕100号)。\n\n2.《财政部 国家税务总局关于外国驻华使(领)馆及其馆员在华购买货物和服务增值税退税政策的通知》(财税〔2016〕51号)和《财政部 税务总局关于外国驻华使(领)馆及其馆员在华购买货物和服务增值税退税政策有关问题的补充通知》(财税〔2017〕74号)。\n\n3.《财政部 税务总局关于完善资源综合利用增值税政策的公告》(财政部 税务总局公告2021年第40号)。\n\n4.《财政部 海关总署 税务总局关于调整风力发电等增值税政策的公告》(财政部 海关总署 税务总局公告2025年第10号)第二条。\n\n(五)自2026年1月1日至2027年12月31日,下列文件中现行有效的增值税优惠政策继续实施。\n\n1.《财政部 国家税务总局关于粮食企业增值税征免问题的通知》(财税字〔1999〕198号)和《财政部 国家税务总局关于免征储备大豆增值税政策的通知》(财税〔2014〕38号)。\n\n2.《财政部 国家税务总局关于退还集成电路企业采购设备增值税期末留抵税额的通知》(财税〔2011〕107号)。\n\n3.《财政部 国家税务总局关于在部分行业试行农产品增值税进项税额核定扣除办法的通知》(财税〔2012〕38号)和《财政部 国家税务总局关于扩大农产品增值税进项税额核定扣除试点行业范围的通知》(财税〔2013〕57号)。\n\n4.《财政部 国家税务总局关于促进残疾人就业增值税优惠政策的通知》(财税〔2016〕52号)。\n\n5.《财政部 税务总局关于明确无偿转让股票等增值税政策的公告》(财政部 税务总局公告2020年第40号)。\n\n6.《财政部 税务总局关于集成电路企业增值税加计抵减政策的通知》(财税〔2023〕17号)。\n\n7.《财政部 税务总局关于工业母机企业增值税加计抵减政策的通知》(财税〔2023〕25号)。\n\n8.《财政部 税务总局 退役军人事务部关于进一步扶持自主就业退役士兵创业就业有关税收政策的公告》(财政部 税务总局 退役军人事务部公告2023年第14号)。\n\n9.《财政部 税务总局 人力资源社会保障部 农业农村部关于进一步支持重点群体创业就业有关税收政策的公告》(财政部 税务总局 人力资源社会保障部 农业农村部公告2023年第15号)。\n\n10.《财政部 税务总局关于民用航空发动机和民用飞机税收政策的公告》(财政部 税务总局公告2023年第27号)。\n\n11.《财政部 税务总局关于继续实施银行业金融机构、金融资产管理公司不良债权以物抵债有关税收政策的公告》(财政部 税务总局公告2023年第35号)。\n\n12.《财政部 商务部 税务总局关于研发机构采购设备增值税政策的公告》(财政部 税务总局公告2023年第41号)和《财政部 科技部 民政部 商务部 税务总局关于继续执行上海市浦东新区有关研发机构适用采购设备增值税政策资格认定事项的通知》(财税〔2023〕32号)。\n\n13.《财政部 税务总局关于先进制造业企业增值税加计抵减政策的公告》(财政部 税务总局公告2023年第43号)。\n\n14.《财政部 税务总局关于延续实施宣传文化增值税优惠政策的公告》(财政部 税务总局公告2023年第60号)和《财政部 税务总局关于更新宣传文化增值税优惠政策适用名单的公告》(财政部 税务总局公告2024年第11号)。\n\n15.《财政部 税务总局关于延续实施支持文化企业发展增值税政策的公告》(财政部 税务总局公告2023年第61号)。\n\n16.《财政部 海关总署 税务总局关于调整风力发电等增值税政策的公告》(财政部 海关总署 税务总局公告2025年第10号)第一条。\n\n17.《财政部 税务总局关于黄金有关税收政策的公告》(财政部 税务总局公告2025年第11号)。\n\n(六)《财政部 国家税务总局关于全面推开营业税改征增值税试点的通知》(财税〔2016〕36号)中附件2《营业税改征增值税试点有关事项的规定》“一般纳税人为甲供工程提供的建筑服务,可以选择适用简易计税方法计税”和《财政部 税务总局关于建筑服务等营改增试点政策的通知》(财税〔2017〕58号)“建筑工程总承包单位为房屋建筑的地基与基础、主体结构提供工程服务,建设单位自行采购全部或部分钢材、混凝土、砌体材料、预制构件的,适用简易计税方法计税”的规定自2026年1月1日起停止执行,纳税人在2026年1月1日前已适用简易计税方法的项目,继续按照原政策规定执行。"},{"no":"六","title":"施行日期","text":"本公告自2026年1月1日起实施。除本公告和增值税法、增值税法实施条例、《财政部 税务总局关于个人销售住房增值税政策的公告》(财政部 税务总局公告2025年第17号)外,在2025年12月31日前制发文件规定的国内环节增值税优惠政策同时停止执行。\n\n特此公告。"}],"interpretations":[],"sourceUrl":"https://www.hunan.gov.cn/zqt/zcsd/202602/t20260228_33923105.html","sourceNote":"2026-10-31 取自湖南省人民政府门户网站政策速递栏目转载页（信息来源：税务总局网站），原文落款2026年1月30日，本网发布2026-02-28；核心小规模纳税人优惠执行期2026-01-01至2027-12-31，故expiresAt记为2027-12-31。；2026-11-08 核对：页面发布日期 2026-02-28","verified":true,"isSample":false,"hunan":false}];
